const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const http = require('node:http');
const {chromium} = require('playwright');
const ROOT=path.resolve(__dirname,'..'), OUT=path.join(ROOT,'results');
const APP_FILE=path.join(ROOT,'board_game_tracker_v27.html');
const STORE='quest-for-glory-v12-slots';
const ALL=['H','S','C','D'].flatMap(s=>Array.from({length:13},(_,i)=>s+(i+1)));
const cost=ids=>ids.reduce((n,id)=>n+Number(id.slice(1))*(id[0]==='D'?2:1),0);
function fixture(over={}) {const base={started:true,round:0,characterName:'Baseline Hero',adventureModule:'Audit',inventory:[],customKeywords:[],customCategories:[],eventKeywords:[],dungeonProgress:[],delve:null,equipment:{weapon:null,armor:null},dead:false,res:{Coin:8,Fate:4,Supply:2},zones:{deck:['H1','H2','H3','S4','C5','D6'],hand:[],fatigue:[],wound:[]},log:[],challenge:null,combat:null,woundTask:null,pointLimit:50,upgradePoints:23,diceType:'6',diceHistory:[]};const x={...base,...over};if(Array.isArray(x.inventory))x.inventory=x.inventory.map(item=>({...item,name:item.name??item.description,keywords:typeof item.keywords==='string'?(item.keywords.trim()?[item.keywords.trim()]:[]):item.keywords}));x.pool=over.pool??ALL.filter(id=>!Object.values(x.zones).flat().includes(id));x.upgradePoints=over.upgradePoints??x.pointLimit-cost(Object.values(x.zones).flat());return x;}
const slot=(state,id='one')=>({id,state,updated:1});
const cases=[];function test(name,fn){cases.push({name,fn});}
async function click(p,s){if(['#renameCharacter','#editModule','#manageKeywords'].includes(s)&&!await p.locator(s).isVisible())await p.locator('#optionsButton').click();await p.locator(s).click();}
async function read(p,id='one'){return p.evaluate(({STORE,id})=>JSON.parse(localStorage.getItem(STORE)).slots.find(s=>s.id===id)?.state,{STORE,id});}
async function seed(p,states=[slot(fixture())],key=STORE){await p.evaluate(({key,states})=>{localStorage.clear();localStorage.setItem(key,JSON.stringify({slots:states}));},{key,states});await p.reload();}
async function load(p,s=fixture()){await seed(p,[slot(s)]);await click(p,'[data-continue="one"]');}
async function random(p,n=.4){await p.evaluate(n=>Math.random=()=>n,n);}
async function action(p,m){await click(p,`[data-mode="${m}"]`);if(m==='rest'&&await p.locator('#restConfirmModal').isVisible())await click(p,'#restConfirmYes');}
async function pick(p,ids){for(const id of ids)await click(p,`#operation [data-card="${id}"]:not([disabled])`);}
async function challenge(p,ids=['H3'],base=5){await action(p,'challenge');await p.locator('#difficulty').fill(String(base));await click(p,'#begin');await pick(p,ids);await click(p,'#commitChallenge');}
async function resolveCombat(p,button='#combatResolve'){await click(p,button);if(await p.locator('#combatRewardModal').isVisible()&&(await read(p)).inventory.length<8)await click(p,'#rewardKeep');}
async function beginCustomCombat(p){await action(p,'combat');await click(p,'#chooseCreateEnemy');}
async function combat(p,ids=['H1'],base=20,wound=1){await beginCustomCombat(p);await p.locator('#combatDifficulty').fill(String(base));await p.locator('#combatWound').fill(String(wound));await click(p,'#startCombat');await pick(p,ids);await click(p,'#combatCommit');}
function invariant(s){const owned=Object.values(s.zones).flat();assert.equal(new Set(owned).size,owned.length,'owned cards unique');assert.equal(new Set([...owned,...s.pool]).size,52,'all 52 cards accounted for');assert.equal(owned.length+s.pool.length,52,'pool has no missing/duplicate cards');}
async function wound(p,n,deck=[]){await action(p,'wound');await p.locator('#woundValue').fill(String(n));await click(p,'#beginWound');await click(p,'#woundNext');if(await p.locator('#finishWound').count()){await pick(p,deck);await click(p,'#finishWound');}}
async function addItem(p,{desc='Rope',base=2,purchased=false,price=base}={}){await click(p,'#inventoryAdd');await p.locator('#inventoryName').fill('Test Item');await p.locator('#inventoryName').fill(desc);await p.locator('#inventoryDescription').fill(desc);await p.locator('#inventoryBaseValue').fill(String(base));if(purchased){await p.locator('#inventoryPurchased').check();await p.locator('#inventoryPurchasePrice').fill(String(price));}await click(p,'#inventoryItemConfirm');}
async function importData(p,data){await p.locator('#importfile').setInputFiles({name:'character.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(data))});await p.waitForTimeout(120);}

test('01 creation defaults, random name, double Diamond cost, initial pool',async p=>{await click(p,'#createCharacter');assert.ok((await p.locator('#characterName').inputValue()).split(' ').length===2);for(const [k,n]of Object.entries({Coin:8,Fate:4,Supply:2}))assert.equal(await p.locator(`[data-start="${k}"]`).inputValue(),String(n));await click(p,'#setupCards [data-card="D6"]');assert.match(await p.locator('#setupTotal').innerText(),/12 \/ 50/);await click(p,'#startGame');const s=await p.evaluate(STORE=>JSON.parse(localStorage.getItem(STORE)).slots[0].state,STORE);assert.equal(s.upgradePoints,38);invariant(s);});
test('02 creation rejects overspend and supports custom starting values',async p=>{await click(p,'#createCharacter');await p.locator('#pointLimit').fill('5');await p.locator('#pointLimit').press('Tab');await click(p,'#setupCards [data-card="D6"]');assert.equal(await p.locator('#startGame').isDisabled(),true);await click(p,'#setupCards [data-card="D6"]');await click(p,'#setupCards [data-card="H1"]');await p.locator('[data-start="Coin"]').fill('13');await p.locator('[data-start="Coin"]').press('Tab');await click(p,'#startGame');assert.equal(await p.locator('#resources strong').first().innerText(),'13');});
test('03 autosave and reload preserve resources, cards, inventory',async p=>{await load(p,fixture({inventory:[{name:'Rope',description:'Rope',keywords:'tool',baseValue:2}]}));await click(p,'[data-resource="Coin"][data-delta="1"]');const s=await read(p);await p.reload();await click(p,'[data-continue="one"]');assert.deepEqual(await read(p),s);assert.match(await p.locator('#inventoryEntries').innerText(),/Rope/);});
test('04 independent slots and five-slot creation/import capacity',async p=>{const slots=Array.from({length:5},(_,i)=>slot(fixture({characterName:'Hero '+i}),String(i)));await seed(p,slots);assert.equal(await p.locator('#createCharacter').isDisabled(),true);await click(p,'#importCharacter');assert.match(await p.locator('#status').innerText(),/5 save slots/);await click(p,'[data-continue="0"]');await click(p,'[data-resource="Coin"][data-delta="1"]');assert.equal((await read(p,'0')).res.Coin,9);assert.equal((await read(p,'1')).res.Coin,8);});
test('05 deletion requires in-app confirmation and Cancel preserves character',async p=>{await seed(p);await click(p,'[data-delete="one"]');assert.equal(await p.locator('#deleteModal').isVisible(),true);await click(p,'#deleteCancel');assert.ok(await read(p));await click(p,'[data-delete="one"]');await click(p,'#deleteConfirm');assert.equal(await p.locator('[data-continue]').count(),0);});
test('06 JSON download/import roundtrip preserves character',async p=>{await seed(p);const download=p.waitForEvent('download');await click(p,'[data-export="one"]');const d=await download;const raw=JSON.parse(fs.readFileSync(await d.path(),'utf8'));assert.equal(raw.format,'quest-for-glory-character');const before=await read(p);await importData(p,raw);const all=await p.evaluate(STORE=>JSON.parse(localStorage.getItem(STORE)).slots,STORE);assert.equal(all.length,2);assert.deepEqual(all[1].state,before);});
test('07 invalid duplicate-card JSON rejected without overwriting save',async p=>{await seed(p);const s=fixture();s.zones.fatigue=['H1'];await importData(p,s);assert.match(await p.locator('#status').innerText(),/Import failed/);assert.equal(await p.locator('[data-continue]').count(),1);});
test('08 resource edits logged, zero protected and Undo restores state',async p=>{await load(p,fixture({res:{Coin:0,Fate:4,Supply:2}}));assert.equal(await p.locator('[data-resource="Coin"][data-delta="-1"]').isDisabled(),true);assert.equal((await read(p)).res.Coin,0);await click(p,'[data-resource="Coin"][data-delta="1"]');assert.match((await read(p)).log[0].message,/Coin \+1/);await click(p,'#undo');assert.equal((await read(p)).res.Coin,0);});
test('09 delegated card-zone tiles work after repeated UI refreshes',async p=>{await load(p);for(const z of ['deck','fatigue','wound']){await click(p,`[data-viewzone="${z}"] .zone-title`);assert.equal(await p.locator('#zoneView').isVisible(),true);await click(p,'[data-resource="Coin"][data-delta="1"]');await click(p,`[data-viewzone="${z}"] .zone-total`);assert.equal(await p.locator('#zoneView').isVisible(),false);}});
test('10 challenge success moves hand to Fatigue and preserves all cards',async p=>{await load(p);await random(p);await challenge(p,['C5'],4);await click(p,'#resolve');const s=await read(p);assert.deepEqual(s.zones.fatigue,['C5']);assert.equal(s.challenge,null);assert.equal(s.dead,false);invariant(s);});
test('11 challenge failure is logged and cards move to Fatigue',async p=>{await load(p);await random(p);await challenge(p,['H1'],10);await click(p,'#resolve');const s=await read(p);assert.match(s.log[0].message,/FAILURE/);assert.deepEqual(s.zones.fatigue,['H1']);invariant(s);});
test('12 modifier six equal random buckets produce -6,-3,0,0,3,6',async p=>{const got=[];for(let i=0;i<6;i++){await load(p);await random(p,(i+.5)/6);await challenge(p);got.push((await read(p)).challenge.modifier);await click(p,'#cancelEncounter');}assert.deepEqual(got,[-6,-3,0,0,3,6]);});
test('13 excluded suits blocked at hand selection and Fate-add stage',async p=>{await load(p);await random(p);await action(p,'challenge');await click(p,'[data-suit="H"]');await click(p,'[data-suit="S"]');await click(p,'[data-suit="C"]');assert.equal(await p.locator('#luckOnlyWarning').isVisible(),true);await click(p,'#begin');assert.equal(await p.locator('#operation [data-card]').count(),1);await pick(p,['D6']);await click(p,'#commitChallenge');assert.equal(await p.locator('#add').isDisabled(),true);});
test('14 first Fate adjustment costs one and the next costs two',async p=>{for(const remove of [false,true]){await load(p);await random(p);await challenge(p,['H3']);await click(p,remove?'#remove':'#add');const id=remove?'H3':'H2';await pick(p,[id]);await click(p,'#apply');const s=await read(p);assert.equal(s.res.Fate,3);assert.equal(s.challenge.adjusted,true);assert.equal(await p.locator('#add').isEnabled(),true);assert.equal(await p.locator('#remove').isDisabled(),s.zones.hand.length===0);assert.match(await p.locator('#add').innerText(),/2 Fate/);invariant(s);}});
test('15 exact-match recovery returns selected cards and conserves deck',async p=>{await load(p);await random(p);await challenge(p,['H2','H3'],5);await click(p,'#resolve');await pick(p,['H2','H3']);await click(p,'#finishExact');const s=await read(p);assert.equal(s.zones.fatigue.length,0);assert.equal(s.zones.deck.length,6);invariant(s);});
test('16 exact-match permits choosing fewer than two cards (spec: up to two)',async p=>{await load(p);await random(p);await challenge(p,['H2','H3'],5);await click(p,'#resolve');await pick(p,['H2']);assert.equal(await p.locator('#finishExact').isEnabled(),true,'one returned card should be permitted');});
test('17 challenge Cancel restores complete pre-action persistent state',async p=>{await load(p);const before=await read(p);await random(p);await challenge(p);await click(p,'#add');await pick(p,['H2']);await click(p,'#apply');await click(p,'#cancelEncounter');assert.deepEqual(await read(p),before);});
test('18 combat success and exact recovery',async p=>{await load(p);await random(p);await combat(p,['C5'],4);await resolveCombat(p);assert.equal((await read(p)).combat,null);await combat(p,['H2','H3'],5);await resolveCombat(p);await pick(p,['H2','H3']);await resolveCombat(p,'#combatExact');const s=await read(p);assert.equal(s.combat,null);invariant(s);});
test('19 combat retries reduce difficulty by two and Cancel restores before all retries',async p=>{await load(p);const before=await read(p);await random(p);await combat(p,['H1'],20);await resolveCombat(p);await pick(p,['H1']);await click(p,'#woundNext');await click(p,'#combatRetry');assert.match(await p.locator('#operation').innerText(),/Base challenge 18/);await pick(p,['H2']);await click(p,'#combatCommit');await resolveCombat(p);await pick(p,['H2']);await click(p,'#woundNext');await click(p,'#combatRetry');assert.match(await p.locator('#operation').innerText(),/Base challenge 16/);await click(p,'#cancelEncounter');assert.deepEqual(await read(p),before);});
test('20 combat fleeing costs two Fate; insufficient Fate disables flee',async p=>{for(const fate of [4,1]){await load(p,fixture({res:{Coin:8,Fate:fate,Supply:2}}));await random(p);await combat(p);await resolveCombat(p);await pick(p,['H1']);await click(p,'#woundNext');if(fate===1)assert.equal(await p.locator('#combatFlee').isDisabled(),true);else{await click(p,'#combatFlee');assert.equal((await read(p)).res.Fate,2);assert.equal((await read(p)).combat,null);}}});
test('21 empty deck cannot begin challenge',async p=>{await load(p,fixture({zones:{deck:[],hand:[],fatigue:['H1'],wound:[]}}));await action(p,'challenge');assert.equal(await p.locator('#actionStatus').innerText(),'Unable to start a challenge without attribute cards');});
test('22 combat retry uses Fatigue hand for explicit two-Fate cost',async p=>{await load(p,fixture({zones:{deck:['H1','H2'],hand:[],fatigue:[],wound:[]}}));await random(p);await combat(p,['H1','H2']);await resolveCombat(p);await pick(p,['H1']);await click(p,'#woundNext');await click(p,'#combatRetry');assert.match(await p.locator('#combatCommit').innerText(),/Deadly Effort/);await pick(p,['H2']);await click(p,'#combatCommit');assert.equal((await read(p)).res.Fate,2);invariant(await read(p));});
test('23 wounds use Fatigue exclusively when it can cover target',async p=>{await load(p,fixture({zones:{deck:['H3','H4'],hand:[],fatigue:['S2','C5'],wound:[]}}));await action(p,'wound');await p.locator('#woundValue').fill('4');await click(p,'#beginWound');assert.equal(await p.locator('#operation [data-card="H3"]').count(),0);await pick(p,['C5']);await click(p,'#woundNext');const s=await read(p);assert.deepEqual(s.zones.wound,['C5']);assert.deepEqual(s.zones.deck,['H3','H4']);invariant(s);});
test('24 insufficient Fatigue is fully allocated before deck cards',async p=>{await load(p,fixture({zones:{deck:['H3','H4'],hand:[],fatigue:['S2'],wound:[]}}));await wound(p,5,['H3']);const s=await read(p);assert.deepEqual(s.zones.wound,['S2','H3']);invariant(s);});
test('25 all owned cards wounded means persistent Game Over and disabled actions',async p=>{await load(p,fixture({zones:{deck:['H1'],hand:[],fatigue:[],wound:[]}}));await wound(p,5);assert.equal((await read(p)).dead,true);assert.equal(await p.locator('#gameOver').isVisible(),true);assert.equal(await p.locator('[data-mode="rest"]').isDisabled(),true);await p.reload();assert.equal(await p.locator('.slot-gameover .gameover-label').innerText(),'GAME OVER');await click(p,'[data-continue="one"]');assert.equal(await p.locator('#gameOver').isVisible(),true);});
test('26 successful challenge does not trigger empty-deck failure death',async p=>{await load(p,fixture({res:{Coin:0,Fate:0,Supply:0},zones:{deck:['H3'],hand:[],fatigue:[],wound:['H1']}}));await random(p);await challenge(p,['H3'],2);await click(p,'#resolve');assert.equal((await read(p)).dead,false);});
test('27 failed challenge detects empty deck + Fatigue + Wounds + zero Fate',async p=>{await load(p,fixture({res:{Coin:0,Fate:0,Supply:0},zones:{deck:['H3'],hand:[],fatigue:[],wound:['H1']}}));await random(p);await challenge(p,['H3'],10);await click(p,'#resolve');assert.equal((await read(p)).dead,true);});
test('28 Rest spends one Supply and enforces recovery value',async p=>{await load(p,fixture({zones:{deck:['H3'],hand:[],fatigue:['H1','H2'],wound:[]}}));await action(p,'rest');await p.locator('#target').fill('1');await pick(p,['H2']);assert.equal(await p.locator('#commit').isDisabled(),true);await pick(p,['H2','H1']);await click(p,'#commit');const s=await read(p);assert.equal(s.res.Supply,1);assert.ok(s.zones.deck.includes('H1'));invariant(s);});
test('29 Rest without Supply wounds five points before recovery',async p=>{await load(p,fixture({res:{Coin:8,Fate:4,Supply:0},zones:{deck:['H3'],hand:[],fatigue:['C5','H2'],wound:[]}}));await action(p,'rest');await click(p,'#restWoundStart');await pick(p,['C5']);await click(p,'#woundNext');await p.locator('#target').fill('2');await pick(p,['H2']);await click(p,'#commit');const s=await read(p);assert.deepEqual(s.zones.wound,['C5']);assert.deepEqual(s.zones.fatigue,[]);assert.equal(s.res.Supply,0);invariant(s);});
test('30 Healing recovers owned Wounds only, within value',async p=>{await load(p,fixture({zones:{deck:['H3'],hand:[],fatigue:[],wound:['H1','H2']}}));await action(p,'heal');await p.locator('#target').fill('1');await pick(p,['H2']);assert.equal(await p.locator('#commit').isDisabled(),true);await pick(p,['H2','H1']);await click(p,'#commit');assert.deepEqual((await read(p)).zones.wound,['H2']);invariant(await read(p));});
test('31 upgrades use leftover budget, Diamonds double, Fate buys three points',async p=>{await load(p);await action(p,'upgrade');await pick(p,['D13']);assert.equal(await p.locator('#purchaseCards').isDisabled(),true);await pick(p,['D13','D1']);await click(p,'#purchaseCards');let s=await read(p);assert.equal(s.upgradePoints,21);assert.ok(s.zones.deck.includes('D1'));await click(p,'#buyUpgrade');s=await read(p);assert.equal(s.pointLimit,53);assert.equal(s.upgradePoints,24);assert.equal(s.res.Fate,3);invariant(s);});
test('32 inventory purchase/sale, custom price, persisted data and Undo',async p=>{await load(p);await click(p,'#inventoryToggle');await addItem(p,{purchased:true,price:3});let s=await read(p);assert.equal(s.res.Coin,5);assert.equal(s.inventory[0].baseValue,2);assert.match(s.log[0].message,/Purchased/);await click(p,'[data-remove-item="0"]');assert.equal(await p.locator('#inventorySalePrice').inputValue(),'2');await p.locator('#inventorySold').check();await p.locator('#inventorySalePrice').fill('4');await click(p,'#inventoryRemoveConfirm');s=await read(p);assert.equal(s.res.Coin,9);assert.equal(s.inventory.length,0);await click(p,'#undo');assert.equal((await read(p)).inventory.length,1);});
test('33 insufficient Coin rejects item purchase with no state mutation',async p=>{await load(p);await click(p,'#inventoryToggle');const before=await read(p);await addItem(p,{purchased:true,price:9});assert.match(await p.locator('#inventoryError').innerText(),/Not enough/);assert.deepEqual(await read(p),{...before,inventoryTipsSeen:{purchase:true}});});
test('34 inventory eight-item limit and combined 300-character bound',async p=>{await load(p,fixture({inventory:Array.from({length:7},(_,i)=>({name:'item '+i,description:'item '+i,keywords:'',baseValue:1}))}));await click(p,'#inventoryToggle');await click(p,'#inventoryAdd');await p.locator('#inventoryName').fill('Test Item');await p.locator('#inventoryName').fill('Budget item');await p.locator('#inventoryDescription').fill('x'.repeat(290));await p.locator('#inventoryKeywords').fill('k'.repeat(20));assert.ok((await p.locator('#inventoryKeywords').inputValue()).length<=10);await click(p,'#inventoryItemConfirm');assert.equal((await read(p)).inventory.length,8);assert.equal(await p.locator('#inventoryAdd').isDisabled(),true);});
test('35 dice open does not roll; all types roll on tap with valid ranges',async p=>{await load(p);assert.equal(await p.locator('#diceBody').isVisible(),false);await click(p,'#diceToggle');assert.equal((await read(p)).diceHistory.length,0);for(const [type,min,max]of [['6',1,6],['8',1,8],['10',1,10],['12',1,12],['2d6',11,66]]){await click(p,`label:has(input[value="${type}"]) span`);await p.waitForTimeout(750);const s=await read(p),r=s.lastDice.result;assert.ok(r>=min&&r<=max);if(type==='2d6')assert.ok(r%10>=1&&r%10<=6);assert.equal(s.diceHistory[0].type,type==='2d6'?'2D6':'D'+type);}});
test('36 2D6 concatenates independent digits and history is newest-first capped at 20',async p=>{await load(p,fixture({diceHistory:Array.from({length:20},()=>({type:'D6',result:1}))}));await p.evaluate(()=>{const xs=[1/6+.01,3/6+.01];let i=0;Math.random=()=>xs[i++%2]});await click(p,'#diceToggle');await click(p,'label:has(input[value="2d6"]) span');await p.waitForTimeout(750);const s=await read(p);assert.equal(s.lastDice.result,24);assert.equal(s.diceHistory.length,20);assert.equal(s.diceHistory[0].result,24);});
test('37 legacy v11 slot migration retains cards, inventory and resources',async p=>{const original=fixture({inventory:[{name:'Old item',description:'Old item',keywords:'',baseValue:2}]});await seed(p,[slot(original)],'quest-for-glory-v11-slots');await click(p,'[data-continue="one"]');assert.deepEqual(await read(p),original);});
test('38 save import requires full card-pool partition',async p=>{await seed(p);const s=fixture({pool:[]});await importData(p,s);assert.match(await p.locator('#status').innerText(),/Import failed/,'missing unowned cards must not be silently accepted');});
test('39 malformed active-action JSON is rejected before storing',async p=>{await seed(p);await importData(p,fixture({challenge:{stage:'choose',allowed:'H'}}));assert.match(await p.locator('#status').innerText(),/Import failed/,'invalid action shape should be rejected');});
test('40 corrupt localStorage is preserved for recovery rather than erased',async p=>{await p.evaluate(STORE=>localStorage.setItem(STORE,'{corrupt-saved-data'),STORE);await p.reload();assert.equal(await p.evaluate(STORE=>localStorage.getItem(STORE),STORE),'{corrupt-saved-data');});
test('41 paid no-Supply Rest can resume after reload without a second wound',async p=>{await load(p,fixture({res:{Coin:8,Fate:4,Supply:0},zones:{deck:['H3'],hand:[],fatigue:['C5','H2'],wound:[]}}));await action(p,'rest');await click(p,'#restWoundStart');await pick(p,['C5']);await click(p,'#woundNext');assert.equal((await read(p)).restWoundResolved,true);await p.reload();await click(p,'[data-continue="one"]');await action(p,'rest');assert.equal(await p.locator('#restWoundStart').count(),0,'already paid wound must not be charged again');});
test('42 dice roll belongs to original character when switching during animation',async p=>{await seed(p,[slot(fixture(),'one'),slot(fixture({characterName:'Other'}),'two')]);await click(p,'[data-continue="one"]');await click(p,'#diceToggle');await click(p,'label:has(input[value="6"]) span');await click(p,'#newGameTop');await click(p,'[data-continue="two"]');await p.waitForTimeout(750);assert.equal((await read(p,'two')).diceHistory.length,0,'other character must not receive pending roll');assert.equal((await read(p,'one')).diceHistory.length,1,'origin character should receive roll');});
test('43 character UI collapse defaults reset on character switch',async p=>{await seed(p,[slot(fixture(),'one'),slot(fixture(),'two')]);await click(p,'[data-continue="one"]');await click(p,'#diceToggle');await click(p,'#activityToggle');await click(p,'#newGameTop');await click(p,'[data-continue="two"]');assert.equal(await p.locator('#diceBody').isVisible(),false);assert.equal(await p.locator('#activityBody').isVisible(),false);});
test('44 Game Over prevents new dice results',async p=>{await load(p,fixture({dead:true}));await click(p,'#diceToggle');await click(p,'label:has(input[value="6"]) span');await p.waitForTimeout(750);assert.equal((await read(p)).diceHistory.length,0);});
test('45 challenge mid-action reload retains hand and Cancel rollback',async p=>{await load(p);const before=await read(p);await random(p);await challenge(p);const committed=await read(p);await p.reload();await click(p,'[data-continue="one"]');assert.deepEqual(await read(p),committed);await click(p,'#cancelEncounter');assert.deepEqual(await read(p),before);});
test('46 selected cards keep ivory, tilt and shadow with a thin dark border',async p=>{await click(p,'#createCharacter');const card=p.locator('#setupCards [data-card="H1"]');await card.click();await p.waitForTimeout(250);for(const interaction of ['normal','hover','focus']){if(interaction==='normal'){await p.mouse.move(0,0);await card.evaluate(e=>e.blur())}if(interaction==='hover')await card.hover();if(interaction==='focus'){await p.mouse.move(0,0);await card.focus()}const css=await card.evaluate(e=>{const s=getComputedStyle(e);return {bg:s.backgroundColor,transform:s.transform,border:s.borderColor,width:s.borderWidth,style:s.borderStyle,shadow:s.boxShadow}});assert.equal(css.bg,'rgb(255, 248, 232)');assert.equal(css.border,'rgb(73, 53, 43)');assert.equal(css.width,'1px');assert.equal(css.style,'solid');assert.notEqual(css.transform,'none');assert.notEqual(css.shadow,'none');}await card.click();await p.waitForTimeout(250);assert.equal(await card.evaluate(e=>e.classList.contains('selected')),false);assert.notEqual(await card.evaluate(e=>getComputedStyle(e).borderColor),'rgb(73, 53, 43)');});
test('47 release identifies itself as Version 27',async p=>{assert.match(await p.locator('header .muted').innerText(),/Version 27\b/);});
test('48 mobile touch: zone tiles, modal and no horizontal page overflow',async(p,ctx,browser)=>{const mobile=await browser.newContext({viewport:{width:390,height:844},isMobile:true,hasTouch:true,deviceScaleFactor:2});const q=await mobile.newPage();await q.goto(p.url());await load(q);await q.locator('[data-viewzone="deck"] .zone-title').tap();assert.equal(await q.locator('#zoneView').isVisible(),true);await click(q,'[data-resource="Coin"][data-delta="1"]');await q.locator('[data-viewzone="deck"] .zone-title').tap();assert.equal(await q.locator('#zoneView').isVisible(),false);await q.locator('#inventoryToggle').tap();await q.locator('#inventoryAdd').tap();assert.equal(await q.locator('#inventoryModal').isVisible(),true);assert.ok(await q.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await q.screenshot({path:path.join(OUT,'mobile-inventory.png'),fullPage:true});await mobile.close();});
test('49 supplied Righteous font is embedded, loads and applies to titles and names',async p=>{await seed(p);await p.evaluate(()=>document.fonts.ready);const fonts=await p.evaluate(()=>[...document.fonts].map(f=>({family:f.family,status:f.status})));assert.ok(fonts.some(f=>f.family==='RighteousEmbedded'&&f.status==='loaded'));for(const selector of ['header h1','.slot strong'])assert.match(await p.locator(selector).first().evaluate(e=>getComputedStyle(e).fontFamily),/RighteousEmbedded/);await click(p,'[data-continue="one"]');await p.evaluate(()=>document.fonts.ready);for(const selector of ['#characterHeading','#moduleHeading']){assert.match(await p.locator(selector).evaluate(e=>getComputedStyle(e).fontFamily),/RighteousEmbedded/);assert.equal(await p.locator(selector).evaluate(e=>getComputedStyle(e).fontWeight),'400');}});

test('50 old v6 single-character storage migrates into an independent slot',async p=>{const s=fixture();await p.evaluate(s=>{localStorage.clear();localStorage.setItem('adventure-tracker-v6',JSON.stringify(s));},s);await p.reload();await click(p,'[data-continue]');assert.equal(await p.locator('#characterHeading').innerText(),s.characterName);});
test('51 no-Supply Rest that wounds every card stops with Game Over',async p=>{await load(p,fixture({res:{Coin:0,Fate:4,Supply:0},zones:{deck:['H1'],hand:[],fatigue:[],wound:[]}}));await action(p,'rest');await click(p,'#restWoundStart');await click(p,'#woundNext');await click(p,'#finishWound');assert.equal((await read(p)).dead,true);assert.equal(await p.locator('#gameOver').isVisible(),true);});
test('52 eligible-suit filtering also applies to two-Fate Fatigue hand',async p=>{const before=fixture({zones:{deck:[],hand:[],fatigue:['H1','S2','D3'],wound:['C5']}});const rollback=JSON.stringify(before);before.challenge={base:5,modifier:null,stage:'choose',adjusted:false,allowed:['H','D'],rollback};await load(p,before);assert.equal(await p.locator('#operation [data-card="S2"]').count(),0);await pick(p,['H1']);await random(p);await click(p,'#commitChallenge');const s=await read(p);assert.equal(s.res.Fate,2);assert.deepEqual(s.zones.hand,['H1']);invariant(s);});
test('53 combat Fate adjustment costs one and subsequent use costs two',async p=>{await load(p);await random(p);await combat(p);await click(p,'#combatAdd');await pick(p,['H3']);await click(p,'#combatApply');const s=await read(p);assert.equal(s.res.Fate,3);assert.equal(s.combat.adjusted,true);assert.equal(await p.locator('#combatAdd').isEnabled(),true);assert.equal(await p.locator('#combatRemove').isEnabled(),true);assert.match(await p.locator('#combatAdd').innerText(),/2 Fate/);invariant(s);});
test('54 imported point balance cannot authorize purchases above point limit',async p=>{await seed(p);const s=fixture({pointLimit:27,upgradePoints:100});await importData(p,s);const imported=await p.locator('[data-continue]').last().getAttribute('data-continue');if(imported==='one'){assert.match(await p.locator('#status').innerText(),/Import failed/);return;}await click(p,`[data-continue="${imported}"]`);await action(p,'upgrade');await pick(p,['D13']);assert.equal(await p.locator('#purchaseCards').isDisabled(),true,'no available points at limit');});
test('55 storage write failure remains visible to player',async p=>{await load(p);await p.evaluate(()=>Storage.prototype.setItem=function(){throw new DOMException('Quota exceeded','QuotaExceededError')});await click(p,'[data-resource="Coin"][data-delta="1"]');assert.match(await p.locator('#status').innerText(),/Save failed/);});
test('56 imported encounter strings cannot insert executable markup',async p=>{await seed(p);const s=fixture({challenge:{base:'<img src="invalid" onerror="window.auditInjected=true">',modifier:0,stage:'decide',adjusted:false,allowed:['H','S','C','D'],rollback:'{}'}});await importData(p,s);const id=await p.locator('[data-continue]').last().getAttribute('data-continue');if(id==='one'){assert.match(await p.locator('#status').innerText(),/Import failed/);return;}await click(p,`[data-continue="${id}"]`);await p.waitForTimeout(200);assert.equal(await p.evaluate(()=>!!window.auditInjected),false,'imported challenge.base inserted executable HTML');});

test('57 app can create and resolve a challenge with networking disabled',async(p,ctx,browser)=>{const c=await browser.newContext({offline:true});const external=[];const origin=new URL(p.url()).origin;await c.route('**/*',r=>{if(new URL(r.request().url()).origin===origin)return r.fulfill({status:200,contentType:'text/html',body:fs.readFileSync(APP_FILE)});external.push(r.request().url());return r.abort()});const q=await c.newPage();await q.goto(origin);await click(q,'#createCharacter');await click(q,'#setupCards [data-card="H3"]');await click(q,'#startGame');await random(q);await challenge(q,['H3'],2);await click(q,'#resolve');assert.match(await q.locator('#log').innerText(),/SUCCESS/);assert.deepEqual(external,[]);await q.reload();assert.equal(await q.locator('[data-continue]').count(),1);await c.close();});

test('58 corrupt storage backup contains original bytes and loading retry recovers',async p=>{const original='{not valid JSON';await p.evaluate(({STORE,original})=>localStorage.setItem(STORE,original),{STORE,original});await p.reload();assert.equal(await p.locator('#storageNotice').isVisible(),true);assert.equal(await p.locator('#createCharacter').isDisabled(),true);assert.equal(await p.locator('#importCharacter').isDisabled(),true);const download=p.waitForEvent('download');await click(p,'#storageBackup');const d=await download;assert.equal(fs.readFileSync(await d.path(),'utf8'),original);assert.equal(await p.evaluate(STORE=>localStorage.getItem(STORE),STORE),original);await p.evaluate(({STORE,state})=>localStorage.setItem(STORE,JSON.stringify({slots:[{id:'one',state,updated:1}]})),{STORE,state:fixture()});await click(p,'#storageRetry');assert.equal(await p.locator('#storageNotice').isVisible(),false);await click(p,'[data-continue="one"]');assert.equal(await p.locator('#characterHeading').innerText(),'Baseline Hero');});
test('59 malformed slot data is preserved atomically instead of filtered or overwritten',async p=>{const raw=JSON.stringify({slots:[slot(fixture()),slot(fixture({zones:{deck:['H1'],hand:[],fatigue:['H1'],wound:[]}}),'bad')]});await p.evaluate(({STORE,raw})=>localStorage.setItem(STORE,raw),{STORE,raw});await p.reload();assert.equal(await p.evaluate(STORE=>localStorage.getItem(STORE),STORE),raw);assert.equal(await p.locator('#storageNotice').isVisible(),true);});
test('60 nested import fields and forged rollback are rejected without altering existing slot',async p=>{await seed(p);const before=await read(p);const bad=[fixture({diceType:'6"]<img src=x>'}),fixture({diceHistory:[{type:'D6',result:99}]}),fixture({log:[null]}),fixture({woundTask:{value:'<img>',source:'rest',stage:'fatigue',fatigue:[],deck:[]}}),fixture({combat:{base:10,wound:1,attempt:0,stage:'choose',modifier:null,adjusted:false,rollback:'{}'}}),fixture({challenge:{base:10,stage:'choose',modifier:null,adjusted:false,allowed:['H','D'],rollback:JSON.stringify(fixture({zones:{deck:['C13'],hand:[],fatigue:[],wound:[]}}))}})];for(const s of bad){await importData(p,s);assert.match(await p.locator('#status').innerText(),/Import failed/);assert.equal(await p.locator('[data-continue]').count(),1);assert.deepEqual(await read(p),before);}});
test('61 legacy missing pool and budget fields are derived without losing cards',async p=>{await seed(p);const s=fixture();delete s.pool;delete s.pointLimit;delete s.upgradePoints;delete s.inventory;delete s.diceType;delete s.diceHistory;await importData(p,s);assert.match(await p.locator('#status').innerText(),/imported successfully/);const id=await p.locator('[data-continue]').last().getAttribute('data-continue');const restored=await read(p,id);invariant(restored);assert.deepEqual(restored.zones,s.zones);assert.equal(restored.pointLimit,50);assert.equal(restored.upgradePoints,23);});
test('62 storage write failure stays visible across actions and retry saves unsaved state',async p=>{await load(p);await p.evaluate(()=>{window.originalSetItem=Storage.prototype.setItem;Storage.prototype.setItem=function(){throw Error('quota')}});await click(p,'[data-resource="Coin"][data-delta="1"]');assert.equal((await read(p)).res.Coin,8);await action(p,'heal');assert.equal(await p.locator('#storageNotice').isVisible(),true);const download=p.waitForEvent('download');await click(p,'#storageBackup');const d=await download;const backup=JSON.parse(fs.readFileSync(await d.path(),'utf8'));assert.equal(backup.slots[0].state.res.Coin,9);await p.evaluate(()=>Storage.prototype.setItem=window.originalSetItem);await click(p,'#storageRetry');assert.equal((await read(p)).res.Coin,9);assert.equal(await p.locator('#storageNotice').isVisible(),false);assert.match(await p.locator('#status').innerText(),/Progress saved/);});
test('63 exact-match optional recovery covers zero and one card in both encounter types',async p=>{for(const combatMode of [false,true])for(const count of [0,1]){await load(p);await random(p);if(combatMode){await combat(p,['H2','H3'],5);await resolveCombat(p)}else{await challenge(p,['H2','H3'],5);await click(p,'#resolve')}if(count)await pick(p,['H2']);await click(p,combatMode?'#combatExact':'#finishExact');const s=await read(p);assert.equal(s.zones.fatigue.length,2-count);assert.equal(s.zones.hand.length,0);assert.equal(s.combat,null);assert.equal(s.challenge,null);invariant(s);}});
test('64 no-Supply Rest resumes through menu and persisted cancellation starts a fresh Rest',async p=>{await load(p,fixture({res:{Coin:8,Fate:4,Supply:0},zones:{deck:['H3'],hand:[],fatigue:['C5','H2'],wound:[]}}));await action(p,'rest');await click(p,'#restWoundStart');await pick(p,['C5']);await click(p,'#woundNext');await click(p,'#newGameTop');await click(p,'[data-continue="one"]');assert.equal(await p.locator('#target').count(),1);assert.equal(await p.locator('#restWoundStart').count(),0);await click(p,'#cancel');assert.equal((await read(p)).restWoundResolved,false);await p.reload();await click(p,'[data-continue="one"]');await action(p,'rest');assert.equal(await p.locator('#restWoundStart').count(),1);});
test('65 active combat and allocated wounds survive reload and retain safe Cancel',async p=>{await load(p);const before=await read(p);await random(p);await combat(p,['H1'],20,2);await resolveCombat(p);await click(p,'#woundNext');const committed=await read(p);assert.equal(committed.woundTask.stage,'deck');await p.reload();await click(p,'[data-continue="one"]');assert.equal(await p.locator('#finishWound').count(),1);await click(p,'#cancelEncounter');assert.deepEqual(await read(p),before);});
test('66 v9 and v10 slot migrations preserve independent characters',async p=>{for(const key of ['quest-for-glory-v9-slots','quest-for-glory-v10-slots']){const original=fixture();await seed(p,[slot(original)],key);await click(p,'[data-continue="one"]');assert.deepEqual(await read(p),original);}});
test('67 numeric overflow is blocked for resource increments and Fate upgrades',async p=>{await load(p,fixture({res:{Coin:Number.MAX_SAFE_INTEGER,Fate:1,Supply:0},pointLimit:Number.MAX_SAFE_INTEGER,upgradePoints:Number.MAX_SAFE_INTEGER-27}));await click(p,'[data-resource="Coin"][data-delta="1"]');assert.equal((await read(p)).res.Coin,Number.MAX_SAFE_INTEGER);await action(p,'upgrade');await click(p,'#buyUpgrade');assert.equal((await read(p)).res.Fate,1);assert.equal((await read(p)).pointLimit,Number.MAX_SAFE_INTEGER);});
test('68 a dice label starts one 2D6 roll rather than a duplicate synthetic click',async p=>{await load(p);await p.evaluate(()=>{window.draws=0;Math.random=()=>{window.draws++;return .4}});await click(p,'#diceToggle');await click(p,'label:has(input[value="2d6"]) span');assert.equal(await p.evaluate(()=>window.draws),2);await p.waitForTimeout(750);assert.equal((await read(p)).diceHistory.length,1);});
test('69 character collapse defaults include Roll History and Inventory',async p=>{await seed(p,[slot(fixture(),'one'),slot(fixture(),'two')]);await click(p,'[data-continue="one"]');await click(p,'#inventoryToggle');await click(p,'#diceToggle');await click(p,'#diceHistoryToggle');await click(p,'#activityToggle');await click(p,'#newGameTop');await click(p,'[data-continue="two"]');for(const id of ['inventoryBody','diceBody','diceHistoryContent','activityBody'])assert.equal(await p.locator('#'+id).isVisible(),false);});

test('70 live add previews update failure, exact match and success without spending Fate',async p=>{for(const isCombat of [false,true]){await load(p);await random(p);if(isCombat)await combat(p,['H3'],5);else await challenge(p,['H3'],5);await click(p,isCombat?'#combatAdd':'#add');const before=await read(p);assert.match(await p.locator('#handAdjustmentPreview').innerText(),/Select a card/);for(const [id,total,outcome]of [['H1',4,'Failure'],['H2',5,'Success · Exact match'],['C5',8,'Success']]){await pick(p,[id]);const text=await p.locator('#handAdjustmentPreview').innerText();assert.ok(text.includes(`3 → ${total}`),text);assert.ok(text.includes(outcome),text);assert.match(text,/Total Challenge Value: 5/);assert.deepEqual(await read(p),before,'preview must not change saved cards, resources or logs');}await click(p,isCombat?'#combatApply':'#apply');const s=await read(p);assert.equal(s.zones.hand.reduce((n,id)=>n+Number(id.slice(1)),0),8);assert.equal(s.res.Fate,3);invariant(s);}});
test('71 live remove previews update success, exact match and failure before confirmation',async p=>{for(const isCombat of [false,true]){await load(p);await random(p);if(isCombat)await combat(p,['H2','H3','C5'],7);else await challenge(p,['H2','H3','C5'],7);await click(p,isCombat?'#combatRemove':'#remove');const before=await read(p);for(const [id,total,outcome]of [['H2',8,'Success'],['H3',7,'Success · Exact match'],['C5',5,'Failure']]){await pick(p,[id]);const text=await p.locator('#handAdjustmentPreview').innerText();assert.ok(text.includes(`10 → ${total}`),text);assert.match(text,/Total Challenge Value: 7/);assert.ok(text.includes(outcome),text);assert.deepEqual(await read(p),before);}await click(p,isCombat?'#combatApply':'#apply');const s=await read(p);assert.deepEqual(s.zones.hand,['H2','H3']);assert.equal(s.res.Fate,3);invariant(s);}});
test('72 preview respects Luck eligibility and face value; Back discards the preview',async p=>{await load(p,fixture({zones:{deck:['D1','D6','H3'],hand:[],fatigue:[],wound:[]}}));await random(p);await action(p,'challenge');await p.locator('#difficulty').fill('7');for(const suit of ['H','S','C'])await click(p,`[data-suit="${suit}"]`);await click(p,'#begin');await pick(p,['D1']);await click(p,'#commitChallenge');await click(p,'#add');assert.equal(await p.locator('#operation [data-card="H3"]').count(),0);const before=await read(p);await pick(p,['D6']);assert.match(await p.locator('#handAdjustmentPreview').innerText(),/1 → 7/);assert.match(await p.locator('#handAdjustmentPreview').innerText(),/\(\+6\)/);assert.match(await p.locator('#handAdjustmentPreview').innerText(),/Exact match/);await click(p,'#back');assert.equal(await p.locator('#handAdjustmentPreview').count(),0);assert.deepEqual(await read(p),before);await click(p,'#add');assert.match(await p.locator('#handAdjustmentPreview').innerText(),/Select a card/);});
test('73 combat retry preview uses reduced difficulty plus the revealed modifier',async p=>{await load(p);await random(p);await combat(p,['H1'],9);await resolveCombat(p);await pick(p,['H1']);await click(p,'#woundNext');await click(p,'#combatRetry');await random(p,0);await pick(p,['H3']);await click(p,'#combatCommit');await click(p,'#combatRemove');await pick(p,['H3']);const text=await p.locator('#handAdjustmentPreview').innerText();assert.match(text,/3 → 0/);assert.match(text,/Total Challenge Value: 1/);assert.match(text,/Failure/);});
test('74 mobile touch selection updates the live preview without horizontal overflow',async(p,ctx,browser)=>{const c=await browser.newContext({viewport:{width:390,height:844},isMobile:true,hasTouch:true});try{const q=await c.newPage();await q.goto(p.url());await load(q);await random(q);await challenge(q,['H3'],5);await click(q,'#add');await q.locator('#operation [data-card="H2"]').tap();assert.match(await q.locator('#handAdjustmentPreview').innerText(),/3 → 5/);assert.match(await q.locator('#handAdjustmentPreview').innerText(),/Success · Exact match/);assert.ok(await q.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await q.screenshot({path:path.join(OUT,'v27-live-preview-mobile.png'),fullPage:true});}finally{await c.close()}});

test('75 purchase tip is one-time per character and remembered after cancel/reload',async p=>{await seed(p,[slot(fixture(),'one'),slot(fixture({characterName:'Other'}),'two')]);await click(p,'[data-continue="one"]');await click(p,'#inventoryToggle');await click(p,'#inventoryAdd');await p.locator('#inventoryName').fill('Test Item');await p.locator('#inventoryPurchased').check();assert.equal(await p.locator('#inventoryPurchaseTip').isVisible(),true);assert.match(await p.locator('#inventoryPurchaseTip').innerText(),/deducted.*total Coin.*confirm/);assert.equal((await read(p)).res.Coin,8);await p.locator('#inventoryPurchased').uncheck();await p.locator('#inventoryPurchased').check();assert.equal(await p.locator('#inventoryPurchaseTip').isVisible(),false);await click(p,'#inventoryModalCancel');await p.reload();await click(p,'[data-continue="one"]');await click(p,'#inventoryToggle');await click(p,'#inventoryAdd');await p.locator('#inventoryName').fill('Test Item');await p.locator('#inventoryPurchased').check();assert.equal(await p.locator('#inventoryPurchaseTip').isVisible(),false);await click(p,'#inventoryModalCancel');await click(p,'#newGameTop');await click(p,'[data-continue="two"]');await click(p,'#inventoryToggle');await click(p,'#inventoryAdd');await p.locator('#inventoryName').fill('Test Item');await p.locator('#inventoryPurchased').check();assert.equal(await p.locator('#inventoryPurchaseTip').isVisible(),true);});
test('76 sale tip is independent and appears only for the first Sold checkbox',async p=>{await load(p,fixture({inventory:[{name:'Rope',description:'Rope',keywords:'',baseValue:3},{name:'Torch',description:'Torch',keywords:'',baseValue:1}],inventoryTipsSeen:{purchase:true}}));await click(p,'#inventoryToggle');await click(p,'[data-remove-item="0"]');await p.locator('#inventorySold').check();assert.equal(await p.locator('#inventorySaleTip').isVisible(),true);assert.match(await p.locator('#inventorySaleTip').innerText(),/added.*total Coin.*confirm/);assert.equal((await read(p)).res.Coin,8);await click(p,'#inventoryRemoveConfirm');assert.equal((await read(p)).res.Coin,11);await p.reload();await click(p,'[data-continue="one"]');await click(p,'#inventoryToggle');await click(p,'[data-remove-item="0"]');await p.locator('#inventorySold').check();assert.equal(await p.locator('#inventorySaleTip').isVisible(),false);assert.deepEqual((await read(p)).inventoryTipsSeen,{purchase:true,sale:true});});
test('77 Undo and encounter cancellation do not repeat already-seen inventory tips',async p=>{await load(p,fixture({inventory:[{name:'Rope',description:'Rope',keywords:'',baseValue:1}]}));await click(p,'[data-resource="Coin"][data-delta="1"]');await click(p,'#inventoryToggle');await click(p,'#inventoryAdd');await p.locator('#inventoryName').fill('Test Item');await p.locator('#inventoryPurchased').check();await click(p,'#inventoryModalCancel');await click(p,'#undo');assert.equal((await read(p)).res.Coin,8);assert.equal((await read(p)).inventoryTipsSeen.purchase,true);await random(p);await challenge(p);await click(p,'[data-remove-item="0"]');await p.locator('#inventorySold').check();assert.equal(await p.locator('#inventorySaleTip').isVisible(),true);await click(p,'#inventoryRemoveForm .secondary');await click(p,'#cancelEncounter');assert.deepEqual((await read(p)).inventoryTipsSeen,{purchase:true,sale:true});await click(p,'[data-remove-item="0"]');await p.locator('#inventorySold').check();assert.equal(await p.locator('#inventorySaleTip').isVisible(),false);});
test('78 inventory tips persist through JSON export/import and malformed preferences are rejected',async p=>{await seed(p,[slot(fixture({inventoryTipsSeen:{purchase:true,sale:true}}))]);const pending=p.waitForEvent('download');await click(p,'[data-export="one"]');const d=await pending;const raw=JSON.parse(fs.readFileSync(await d.path(),'utf8'));await importData(p,raw);const id=await p.locator('[data-continue]').last().getAttribute('data-continue');assert.deepEqual((await read(p,id)).inventoryTipsSeen,{purchase:true,sale:true});await importData(p,fixture({inventoryTipsSeen:{purchase:'yes'}}));assert.match(await p.locator('#status').innerText(),/Import failed/);assert.equal(await p.locator('[data-continue]').count(),2);await click(p,`[data-continue="${id}"]`);await click(p,'#inventoryToggle');await click(p,'#inventoryAdd');await p.locator('#inventoryName').fill('Test Item');await p.locator('#inventoryPurchased').check();assert.equal(await p.locator('#inventoryPurchaseTip').isVisible(),false);});

async function defineEnemy(p,{name='Enemy',description='',keywords=[],base=5,woundValue=1,fate=1,coin=0,item=null}={}){
 await beginCustomCombat(p);await p.locator('#enemyName').fill(name);await p.locator('#enemyDescription').fill(description);await p.locator('#enemyKeywords').fill(Array.isArray(keywords)?keywords.join(' - '):keywords);await p.locator('#combatDifficulty').fill(String(base));await p.locator('#combatWound').fill(String(woundValue));await p.locator('#enemyFateReward').fill(String(fate));await p.locator('#enemyCoinReward').fill(String(coin));
 if(item){await p.locator('#enemyHasItem').check();await p.locator('#enemyItemName').fill('Reward item');await p.locator('#enemyItemName').fill(item.name||item.description);await p.locator('#enemyItemDescription').fill(item.description);await p.locator('#enemyItemKeywords').fill(Array.isArray(item.keywords)?item.keywords.join(' - '):(item.keywords||''));await p.locator('#enemyItemValue').fill(String(item.baseValue))}await click(p,'#startCombat');
}
async function adjust(p,isCombat,adding,id){await click(p,isCombat?(adding?'#combatAdd':'#combatRemove'):(adding?'#add':'#remove'));await pick(p,[id]);await click(p,isCombat?'#combatApply':'#apply');}
const inventoryEight=()=>Array.from({length:8},(_,i)=>({name:'Item '+i,description:'Item '+i,keywords:['original'],baseValue:i+1}));
const rewardItem={name:'Enchanted Sword',description:'Enchanted Sword',keywords:['weapon','magic'],baseValue:12};

test('79 repeated Fate additions/removals share costs 1, 2, 4, 8 in each action',async p=>{for(const isCombat of [false,true]){await load(p,fixture({res:{Coin:8,Fate:15,Supply:2}}));await random(p);if(isCombat)await combat(p,['H3'],30);else await challenge(p,['H3'],30);for(const [adding,id,remaining,next]of [[true,'H2',14,2],[false,'H2',12,4],[true,'H1',8,8],[false,'H1',0,16]]){await adjust(p,isCombat,adding,id);const s=await read(p);assert.equal(s.res.Fate,remaining);assert.match(await p.locator(isCombat?'#combatAdd':'#add').innerText(),new RegExp(next+' Fate'));invariant(s);}const s=await read(p);assert.equal((isCombat?s.combat:s.challenge).adjustmentsUsed,4);assert.equal(await p.locator(isCombat?'#combatAdd':'#add').isDisabled(),true);assert.equal(await p.locator(isCombat?'#combatRemove':'#remove').isDisabled(),true);}});
test('80 initial hand has at most five cards; paid additions can exceed five',async p=>{for(const isCombat of [false,true]){await load(p);await random(p);if(isCombat){await defineEnemy(p,{base:30})}else{await action(p,'challenge');await click(p,'#begin')}const first=['H1','H2','H3','S4','C5'];await pick(p,first);assert.equal(await p.locator('#operation [data-card="D6"]').isDisabled(),true);await pick(p,['H1']);assert.equal(await p.locator('#operation [data-card="D6"]').isEnabled(),true);await pick(p,['H1']);await click(p,isCombat?'#combatCommit':'#commitChallenge');assert.equal((await read(p)).zones.hand.length,5);await adjust(p,isCombat,true,'D6');const s=await read(p);assert.equal(s.zones.hand.length,6);assert.equal(s.res.Fate,3);invariant(s);}});
test('81 doubling cost survives reload, Back does not charge, Cancel restores the complete state',async p=>{for(const isCombat of [false,true]){await load(p,fixture({res:{Coin:8,Fate:12,Supply:2}}));const before=await read(p);await random(p);if(isCombat)await combat(p);else await challenge(p);await adjust(p,isCombat,true,'H2');await p.reload();await click(p,'[data-continue="one"]');assert.match(await p.locator(isCombat?'#combatAdd':'#add').innerText(),/2 Fate/);await click(p,isCombat?'#combatAdd':'#add');await pick(p,['D6']);await click(p,isCombat?'#combatBack':'#back');assert.equal((await read(p)).res.Fate,11);await adjust(p,isCombat,false,'H2');assert.equal((await read(p)).res.Fate,9);await click(p,'#cancelEncounter');assert.deepEqual(await read(p),before);}});
test('82 combat retry resets the next adjustment cost to one and preserves enemy rewards',async p=>{await load(p,fixture({res:{Coin:8,Fate:20,Supply:2}}));await random(p);await defineEnemy(p,{name:'Troll',base:30,fate:3,coin:2});await pick(p,['H3']);await click(p,'#combatCommit');await adjust(p,true,true,'H2');await adjust(p,true,false,'H2');await resolveCombat(p);await pick(p,['H3']);await click(p,'#woundNext');await click(p,'#combatRetry');assert.equal((await read(p)).combat.adjustmentsUsed,0);assert.equal((await read(p)).combat.enemy.name,'Troll');assert.equal((await read(p)).combat.enemy.F,3);await pick(p,['H1']);await click(p,'#combatCommit');assert.match(await p.locator('#combatAdd').innerText(),/1 Fate/);assert.match(await p.locator('#operation').innerText(),/Base challenge 28/);});
test('83 enemy prompt defaults and cancellation leave the character unchanged',async p=>{await load(p);const before=await read(p);await beginCustomCombat(p);assert.equal(await p.locator('#enemySetupModal').isVisible(),true);for(const [id,value]of Object.entries({enemyName:'Enemy',combatDifficulty:'5',combatWound:'1',enemyFateReward:'1',enemyCoinReward:'0'}))assert.equal(await p.locator('#'+id).inputValue(),value);assert.equal(await p.locator('#enemyHasItem').isChecked(),false);await click(p,'#enemySetupCancel');assert.deepEqual(await read(p),before);await beginCustomCombat(p);await click(p,'#startCombat');assert.deepEqual((await read(p)).combat.enemy,{id:'Enemy',name:'Enemy',boss:false,description:'',CV:5,WV:1,F:1,C:0,KW:[],Item:null});});
test('84 ordinary victory adds configured Fate, Coin and inventory item exactly once',async p=>{await load(p);await random(p);await defineEnemy(p,{name:'Goblin',base:4,fate:3,coin:7,item:rewardItem});await pick(p,['C5']);await click(p,'#combatCommit');await resolveCombat(p);let s=await read(p);assert.equal(s.combat,null);assert.equal(s.res.Fate,7);assert.equal(s.res.Coin,15);assert.deepEqual(s.inventory,[rewardItem]);invariant(s);await p.reload();await click(p,'[data-continue="one"]');s=await read(p);assert.equal(s.res.Fate,7);assert.equal(s.res.Coin,15);assert.deepEqual(s.inventory,[rewardItem]);assert.equal(s.log.filter(e=>e.message.includes('Defeated Goblin')).length,1);});
test('85 exact-match victory grants rewards only after the recovery choice',async p=>{await load(p);await random(p);await defineEnemy(p,{base:5,fate:2,coin:4,item:rewardItem});await pick(p,['H2','H3']);await click(p,'#combatCommit');await resolveCombat(p);assert.equal((await read(p)).res.Fate,4);assert.equal((await read(p)).inventory.length,0);await pick(p,['H2']);await resolveCombat(p,'#combatExact');const s=await read(p);assert.equal(s.res.Fate,6);assert.equal(s.res.Coin,12);assert.deepEqual(s.inventory,[rewardItem]);assert.ok(s.zones.deck.includes('H2'));invariant(s);});
test('86 failed combat and fleeing do not grant configured rewards',async p=>{await load(p);await random(p);await defineEnemy(p,{base:30,fate:10,coin:10,item:rewardItem});await pick(p,['H1']);await click(p,'#combatCommit');await resolveCombat(p);await pick(p,['H1']);await click(p,'#woundNext');let s=await read(p);assert.equal(s.res.Fate,4);assert.equal(s.res.Coin,8);assert.equal(s.inventory.length,0);await click(p,'#combatFlee');s=await read(p);assert.equal(s.res.Fate,2);assert.equal(s.res.Coin,8);assert.equal(s.inventory.length,0);});
test('87 full inventory decline retains all existing items and resource rewards',async p=>{await load(p,fixture({inventory:inventoryEight()}));await random(p);await defineEnemy(p,{base:4,fate:2,coin:3,item:rewardItem});await pick(p,['C5']);await click(p,'#combatCommit');await resolveCombat(p);assert.equal(await p.locator('#combatRewardModal').isVisible(),true);assert.equal((await read(p)).combat.rewardsGranted,true);assert.equal((await read(p)).res.Coin,11);await click(p,'#rewardDiscard');const s=await read(p);assert.equal(s.combat,null);assert.deepEqual(s.inventory,inventoryEight());assert.equal(s.res.Coin,11);assert.equal(s.res.Fate,6);});
test('88 full inventory replacement lists all items and discards only the selected item without sale proceeds',async p=>{await load(p,fixture({inventory:inventoryEight()}));await random(p);await defineEnemy(p,{base:4,coin:2,item:rewardItem});await pick(p,['C5']);await click(p,'#combatCommit');await resolveCombat(p);await click(p,'#rewardKeep');assert.equal(await p.locator('#rewardChoiceList input').count(),8);assert.equal(await p.locator('#rewardReplaceConfirm').isDisabled(),true);await p.locator('input[name="rewardDiscard"][value="3"]').check();await click(p,'#rewardReplaceConfirm');const s=await read(p);assert.equal(s.inventory.length,8);assert.deepEqual(s.inventory[3],rewardItem);assert.deepEqual(s.inventory.filter((_,i)=>i!==3),inventoryEight().filter((_,i)=>i!==3));assert.equal(s.res.Coin,10);assert.equal(s.res.Fate,5);assert.equal(s.combat,null);});
test('89 pending reward survives reload and JSON transfer without duplicating resources',async p=>{await load(p,fixture({inventory:inventoryEight()}));await random(p);await defineEnemy(p,{name:'Dragon',base:4,fate:3,coin:5,item:rewardItem});await pick(p,['C5']);await click(p,'#combatCommit');await resolveCombat(p);await p.reload();await click(p,'[data-continue="one"]');assert.equal((await read(p)).res.Fate,7);assert.equal((await read(p)).res.Coin,13);assert.equal(await p.locator('#combatRewardModal').isVisible(),true);await click(p,'#rewardKeep');await p.reload();const pending=p.waitForEvent('download');await click(p,'[data-export="one"]');const d=await pending;const raw=JSON.parse(fs.readFileSync(await d.path(),'utf8'));await importData(p,raw);assert.match(await p.locator('#status').innerText(),/imported successfully/);const id=await p.locator('[data-continue]').last().getAttribute('data-continue');await click(p,`[data-continue="${id}"]`);assert.equal(await p.locator('#rewardReplacement').isVisible(),true);await p.locator('input[name="rewardDiscard"][value="0"]').check();await click(p,'#rewardReplaceConfirm');const s=await read(p,id);assert.equal(s.res.Fate,7);assert.equal(s.res.Coin,13);assert.deepEqual(s.inventory[0],rewardItem);assert.equal(s.log.filter(e=>e.message.includes('Defeated Dragon')).length,1);});
test('90 Undo of victory/replacement restores awards consistently without duplication',async p=>{await load(p,fixture({inventory:inventoryEight()}));await random(p);await defineEnemy(p,{base:4,fate:2,coin:3,item:rewardItem});await pick(p,['C5']);await click(p,'#combatCommit');await resolveCombat(p);await click(p,'#rewardKeep');await p.locator('input[name="rewardDiscard"][value="0"]').check();await click(p,'#rewardReplaceConfirm');await click(p,'#undo');let s=await read(p);assert.equal(s.combat.stage,'reward');assert.equal(s.res.Fate,6);assert.equal(s.res.Coin,11);assert.deepEqual(s.inventory,inventoryEight());await click(p,'#rewardReplacementBack');await click(p,'#rewardDiscard');s=await read(p);assert.equal(s.res.Coin,11);assert.equal(s.res.Fate,6);});
test('91 enemy and reward fields reject invalid values and enforce combined text length',async p=>{await load(p);await beginCustomCombat(p);const before=await read(p);for(const [id,value]of [['combatWound','-1'],['enemyFateReward','-1'],['enemyCoinReward','1.5']]){await p.locator('#'+id).fill(value);await click(p,'#startCombat');assert.equal(await p.locator('#enemySetupModal').isVisible(),true);assert.ok((await p.locator('#enemySetupError').innerText()).length>0);await p.locator('#'+id).fill(id==='combatWound'?'1':'0')}await p.locator('#enemyHasItem').check();await p.locator('#enemyItemName').fill('');await click(p,'#startCombat');assert.equal(await p.locator('#enemySetupModal').isVisible(),true);await p.locator('#enemyItemName').fill('Reward item');await p.locator('#enemyItemDescription').fill('a'.repeat(290));await p.locator('#enemyItemKeywords').fill('b'.repeat(30));assert.equal((await p.locator('#enemyItemDescription').inputValue()).length+(await p.locator('#enemyItemKeywords').inputValue()).length,300);assert.deepEqual(await read(p),before);await click(p,'#startCombat');assert.equal((await read(p)).combat.enemy.Item.description.length,290);});
test('92 malformed enemy rewards and adjustment counters are rejected on import',async p=>{await seed(p);const oldCombat={base:5,wound:1,attempt:0,stage:'choose',modifier:null,adjusted:false};for(const patch of [{enemy:{name:'Bad',fateReward:-1,coinReward:0,itemReward:null}},{enemy:{name:'Bad',fateReward:1,coinReward:0,itemReward:{name:'x',description:'x',keywords:'',baseValue:-1}}},{adjustmentsUsed:54},{adjustmentsUsed:1},{rewardsGranted:true}]){await importData(p,fixture({combat:{...oldCombat,...patch}}));assert.match(await p.locator('#status').innerText(),/Import failed/);assert.equal(await p.locator('[data-continue]').count(),1);}});
test('93 V18 encounters migrate previous Fate usage without retroactive enemy rewards',async p=>{const s=fixture({zones:{deck:['H1','H2','S4','C5','D6'],hand:['H3'],fatigue:[],wound:[]},combat:{base:2,wound:1,attempt:0,stage:'decide',modifier:0,adjusted:true}});await load(p,s);assert.match(await p.locator('#combatAdd').innerText(),/2 Fate/);await resolveCombat(p);const restored=await read(p);assert.equal(restored.combat,null);assert.equal(restored.res.Fate,4);assert.equal(restored.res.Coin,8);invariant(restored);});
test('94 rewards that overflow resources remain pending until safely collectible',async p=>{await load(p,fixture({res:{Coin:Number.MAX_SAFE_INTEGER,Fate:4,Supply:2}}));await random(p);await defineEnemy(p,{base:4,fate:3,coin:1});await pick(p,['C5']);await click(p,'#combatCommit');await resolveCombat(p);let s=await read(p);assert.equal(s.combat.stage,'reward');assert.equal(s.combat.rewardsGranted,false);assert.equal(s.res.Fate,4);await click(p,'[data-resource="Coin"][data-delta="-1"]');await click(p,'#collectCombatRewards');s=await read(p);assert.equal(s.res.Coin,Number.MAX_SAFE_INTEGER);assert.equal(s.res.Fate,7);assert.equal(s.combat,null);});
test('95 low Fate during adjustment disables confirmation and does not move cards',async p=>{await load(p);await random(p);await challenge(p);await click(p,'#add');await pick(p,['H2']);for(let i=0;i<4;i++)await click(p,'[data-resource="Fate"][data-delta="-1"]');assert.equal(await p.locator('#apply').isDisabled(),true);assert.deepEqual((await read(p)).zones.hand,['H3']);});
test('96 the five-card cap also applies to eligible Fatigue hands during an ongoing action',async p=>{const s=fixture({res:{Coin:8,Fate:12,Supply:2},zones:{deck:[],hand:[],fatigue:['H1','H2','H3','S4','C5','D6'],wound:[]},challenge:{base:5,modifier:null,stage:'choose',adjusted:false,allowed:['H','S','C','D']}});await load(p,s);await pick(p,['H1','H2','H3','S4','C5']);assert.equal(await p.locator('#operation [data-card="D6"]').isDisabled(),true);await click(p,'#commitChallenge');assert.equal((await read(p)).zones.hand.length,5);assert.equal((await read(p)).res.Fate,2);});
test('97 mobile enemy and full-inventory reward dialogs remain usable and text is escaped',async(p,ctx,browser)=>{const c=await browser.newContext({viewport:{width:320,height:844},isMobile:true,hasTouch:true});try{const q=await c.newPage();await q.goto(p.url());await load(q,fixture({inventory:inventoryEight()}));await random(q);await beginCustomCombat(q);assert.ok(await q.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));const cancel=await q.locator('#enemySetupCancel').boundingBox(),begin=await q.locator('#startCombat').boundingBox();assert.ok(Math.abs(cancel.y-begin.y)<1,'enemy setup buttons must align');await q.screenshot({path:path.join(OUT,'v27-enemy-setup-mobile.png')});await q.locator('#enemyName').fill('<img src=x onerror="window.injected=true">'+'X'.repeat(40));await q.locator('#combatDifficulty').fill('4');await q.locator('#enemyHasItem').check();await q.locator('#enemyItemName').fill('Reward item');await q.locator('#enemyItemDescription').fill('Treasure');await click(q,'#startCombat');await pick(q,['C5']);await click(q,'#combatCommit');await resolveCombat(q);assert.equal(await q.locator('#combatRewardModal').isVisible(),true);assert.equal(await q.evaluate(()=>!!window.injected),false);await q.locator('#rewardKeep').tap();await q.locator('input[name="rewardDiscard"][value="7"]').check();await q.screenshot({path:path.join(OUT,'v27-reward-mobile.png')});assert.ok(await q.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await q.locator('#rewardReplaceConfirm').tap();assert.equal((await read(q)).inventory[7].description,'Treasure');}finally{await c.close()}});
test('98 full inventory without an item reward finishes normally and Game Over grants no reward',async p=>{await load(p,fixture({inventory:inventoryEight()}));await random(p);await combat(p,['C5'],4);await resolveCombat(p);assert.equal((await read(p)).combat,null);assert.equal(await p.locator('#combatRewardModal').isVisible(),false);await load(p,fixture({zones:{deck:['H1'],hand:[],fatigue:[],wound:[]}}));await random(p);await defineEnemy(p,{base:30,fate:10,coin:10,item:rewardItem});await pick(p,['H1']);await click(p,'#combatCommit');await resolveCombat(p);await pick(p,['H1']);await click(p,'#woundNext');const s=await read(p);assert.equal(s.dead,true);assert.equal(s.res.Fate,4);assert.equal(s.res.Coin,8);assert.equal(s.inventory.length,0);});

test('99 extreme or blank initial difficulty is rejected before an unsafe modifier calculation',async p=>{await load(p);await beginCustomCombat(p);for(const value of ['',String(Number.MAX_SAFE_INTEGER)]){await p.locator('#combatDifficulty').fill(value);await click(p,'#startCombat');assert.equal(await p.locator('#enemySetupModal').isVisible(),true);assert.equal((await read(p)).combat,null);}await click(p,'#enemySetupCancel');await action(p,'challenge');await p.locator('#difficulty').fill(String(Number.MAX_SAFE_INTEGER));await click(p,'#begin');assert.equal((await read(p)).challenge,null);assert.match(await p.locator('#actionStatus').innerText(),/supported/);});
test('100 restored pending reward asks before using a free inventory slot without re-awarding resources',async p=>{const s=fixture({res:{Coin:13,Fate:7,Supply:2},combat:{base:4,wound:1,attempt:0,stage:'reward',modifier:0,adjusted:false,rewardsGranted:true,enemy:{name:'Dragon',fateReward:3,coinReward:5,itemReward:rewardItem}}});await load(p,s);assert.equal(await p.locator('#combatRewardModal').isVisible(),true);await click(p,'#rewardKeep');const restored=await read(p);assert.equal(restored.res.Coin,13);assert.equal(restored.res.Fate,7);assert.deepEqual(restored.inventory,[rewardItem]);assert.equal(restored.combat,null);});
test('101 cancellation after escalating Fate costs and multiple retries restores the original character',async p=>{await load(p,fixture({res:{Coin:8,Fate:20,Supply:2}}));const before=await read(p);await random(p);await defineEnemy(p,{name:'Persistent Enemy',base:30,fate:5,coin:5,item:rewardItem});await pick(p,['H3']);await click(p,'#combatCommit');await adjust(p,true,true,'H2');await adjust(p,true,false,'H2');await resolveCombat(p);await pick(p,['H3']);await click(p,'#woundNext');await click(p,'#combatRetry');await pick(p,['H1']);await click(p,'#combatCommit');await adjust(p,true,true,'H2');await resolveCombat(p);await pick(p,['H1']);await click(p,'#woundNext');await click(p,'#combatRetry');await click(p,'#cancelEncounter');assert.deepEqual(await read(p),{...before,customKeywords:[{keyword:'weapon',category:'custom',origin:'custom'},{keyword:'magic',category:'custom',origin:'custom'}]});});
test('102 an expanded paid hand and the next Fate cost survive reload',async p=>{await load(p,fixture({zones:{deck:['H1','H2','H3','H4','H5','H6','H7'],hand:[],fatigue:[],wound:[]}}));await random(p);await challenge(p,['H1','H2','H3','H4','H5'],30);await adjust(p,false,true,'H6');await p.reload();await click(p,'[data-continue="one"]');assert.equal((await read(p)).zones.hand.length,6);assert.match(await p.locator('#add').innerText(),/2 Fate/);await adjust(p,false,true,'H7');const s=await read(p);assert.equal(s.zones.hand.length,7);assert.equal(s.res.Fate,1);assert.equal(s.challenge.adjustmentsUsed,2);invariant(s);});
test('103 exponential adjustment costs stop safely at the numeric limit',async p=>{const s=fixture({res:{Coin:8,Fate:Number.MAX_SAFE_INTEGER,Supply:2},zones:{deck:['H1','H2','S4','C5','D6'],hand:['H3'],fatigue:[],wound:[]},challenge:{base:5,modifier:0,stage:'decide',adjusted:true,adjustmentsUsed:52,allowed:['H','S','C','D']}});await load(p,s);await adjust(p,false,true,'H2');const restored=await read(p);assert.equal(restored.res.Fate,Number.MAX_SAFE_INTEGER-2**52);assert.equal(restored.challenge.adjustmentsUsed,53);assert.equal(await p.locator('#add').isDisabled(),true);assert.equal(await p.locator('#remove').isDisabled(),true);assert.doesNotMatch(await p.locator('#operation').innerText(),/Next adjustment costs/);});
test('104 combat retries cannot create an unsafe difficulty from a boundary save',async p=>{const s=fixture({combat:{base:0,wound:1,attempt:Number.MAX_SAFE_INTEGER,stage:'afterFail',modifier:0,adjusted:false}});await load(p,s);const before=await read(p);await click(p,'#combatRetry');assert.deepEqual(await read(p),before);assert.match(await p.locator('#actionStatus').innerText(),/supported whole-number range/);});

test('105 new dialogs keep keyboard focus inside and Escape never silently discards a reward',async p=>{await load(p,fixture({inventory:inventoryEight()}));const before=await read(p);await beginCustomCombat(p);assert.equal(await p.locator(':focus').getAttribute('id'),'enemyName');await p.keyboard.press('Shift+Tab');assert.equal(await p.locator(':focus').getAttribute('id'),'startCombat');await p.keyboard.press('Tab');assert.equal(await p.locator(':focus').getAttribute('id'),'enemyName');await p.keyboard.press('Escape');assert.equal(await p.locator('#enemySetupModal').isVisible(),false);assert.deepEqual(await read(p),before);await random(p);await defineEnemy(p,{base:4,item:rewardItem});await pick(p,['C5']);await click(p,'#combatCommit');await resolveCombat(p);assert.equal(await p.locator(':focus').getAttribute('id'),'rewardKeep');await p.keyboard.press('Shift+Tab');assert.equal(await p.locator(':focus').getAttribute('id'),'rewardDiscard');await click(p,'#rewardKeep');await p.keyboard.press('Escape');assert.equal(await p.locator('#rewardQuestion').isVisible(),true);await p.keyboard.press('Escape');assert.equal(await p.locator('#combatRewardModal').isVisible(),true);assert.equal((await read(p)).combat.stage,'reward');await click(p,'#rewardDiscard');});
test('106 the V19 enemy, paid adjustment and victory reward flow works fully offline',async(p,ctx,browser)=>{const c=await browser.newContext({offline:true});try{const q=await c.newPage(),origin=new URL(p.url()).origin,external=[];q.setDefaultTimeout(10000);await c.route('**/*',r=>{if(new URL(r.request().url()).origin===origin)return r.fulfill({status:200,contentType:'text/html',body:fs.readFileSync(APP_FILE)});external.push(r.request().url());return r.abort()});await q.goto(origin);await load(q);await random(q);await defineEnemy(q,{name:'Offline Foe',base:4,fate:2,coin:3,item:rewardItem});await pick(q,['H3']);await click(q,'#combatCommit');await adjust(q,true,true,'C5');await resolveCombat(q);const s=await read(q);assert.equal(s.res.Fate,5);assert.equal(s.res.Coin,11);assert.deepEqual(s.inventory,[rewardItem]);assert.equal(s.combat,null);await q.evaluate(()=>document.fonts.ready);assert.equal(await q.evaluate(()=>[...document.fonts].find(f=>f.family==='RighteousEmbedded').status),'loaded');assert.deepEqual(external,[]);invariant(s);}finally{await c.close()}});

async function manualAmount(p,key,amount,{remove=false,confirm=true}={}){await click(p,key==='Round'?'#roundDisplay':`[data-adjust-resource="${key}"]`);if(remove)await click(p,'#adjustRemove');await p.locator('#adjustAmount').fill(String(amount));if(confirm)await click(p,'#adjustConfirm');}

test('107 modifier-adjusted Challenge Value floors at one in both action types and previews',async p=>{for(const isCombat of [false,true]){await load(p);await random(p,0);if(isCombat)await combat(p,['H1'],3);else await challenge(p,['H1'],3);await click(p,isCombat?'#combatAdd':'#add');await pick(p,['H2']);assert.match(await p.locator('#handAdjustmentPreview').innerText(),/Total Challenge Value: 1/);await click(p,isCombat?'#combatBack':'#back');await click(p,isCombat?'#combatResolve':'#resolve');assert.equal(await p.locator(isCombat?'#combatExact':'#finishExact').count(),1);await click(p,isCombat?'#combatExact':'#finishExact');assert.equal((await read(p)).dead,false);}});
test('108 setup minimum and combat retry base both remain one or higher',async p=>{await load(p);await action(p,'challenge');await p.locator('#difficulty').fill('0');await click(p,'#begin');assert.equal((await read(p)).challenge,null);assert.equal(await p.locator('#difficulty').getAttribute('min'),'1');await beginCustomCombat(p);await p.locator('#combatDifficulty').fill('0');await click(p,'#startCombat');assert.equal(await p.locator('#enemySetupModal').isVisible(),true);assert.equal((await read(p)).combat,null);await click(p,'#enemySetupCancel');await load(p,fixture({combat:{base:2,wound:1,attempt:5,stage:'afterFail',modifier:0,adjusted:false}}));assert.match(await p.locator('#operation').innerText(),/Base challenge 1/);assert.match(await p.locator('#combatRetry').innerText(),/difficulty 1/);await click(p,'#combatRetry');assert.match(await p.locator('#operation').innerText(),/Base challenge 1/);await random(p,0);await pick(p,['H1']);await click(p,'#combatCommit');await resolveCombat(p);assert.equal(await p.locator('#combatExact').count(),1);});
test('109 legacy zero base and unfinished zero-value exact matches migrate without granting a false success',async p=>{await load(p,fixture({challenge:{base:0,modifier:-6,stage:'decide',adjusted:false,allowed:['H','S','C','D']}}));assert.match(await p.locator('#operation').innerText(),/Final challenge 1/);await load(p,fixture({challenge:{base:6,modifier:-6,stage:'exact',adjusted:true,allowed:['H','S','C','D']}}));assert.equal(await p.locator('#finishExact').count(),0);assert.match(await p.locator('#operation').innerText(),/Currently unsuccessful/);});
test('110 initial hand text is removed while the five-card limit and paid additions remain',async p=>{for(const combatMode of [false,true]){await load(p);if(combatMode)await defineEnemy(p);else{await action(p,'challenge');await click(p,'#begin')}assert.doesNotMatch(await p.locator('#operation').innerText(),/Paid Fate additions after the modifier may exceed 5/);await pick(p,['H1','H2','H3','S4','C5']);assert.equal(await p.locator('#operation [data-card="D6"]').isDisabled(),true);await random(p);await click(p,combatMode?'#combatCommit':'#commitChallenge');await adjust(p,combatMode,true,'D6');assert.equal((await read(p)).zones.hand.length,6);}});
test('111 Round begins at zero and sits between the character banner and Resources',async p=>{await click(p,'#createCharacter');await click(p,'#setupCards [data-card="H3"]');await click(p,'#startGame');assert.equal(await p.locator('#roundNumber').innerText(),'0');const order=await p.evaluate(()=>document.querySelector('.character-banner').getBoundingClientRect().bottom<=document.querySelector('#roundDisplay').getBoundingClientRect().top&&document.querySelector('#roundDisplay').getBoundingClientRect().bottom<document.querySelector('#resourcesPanel').getBoundingClientRect().top);assert.equal(order,true);const all=await p.evaluate(STORE=>JSON.parse(localStorage.getItem(STORE)).slots,STORE);assert.equal(all[0].state.round,0);});
test('112 each completed Rest advances Round once and Undo restores cards, Supply and Round',async p=>{await load(p,fixture({zones:{deck:['H3'],hand:[],fatigue:['H1','H2'],wound:[]}}));for(const [id,n]of [['H1',1],['H2',2]]){await action(p,'rest');await p.locator('#target').fill(String(n));await pick(p,[id]);await click(p,'#commit');assert.equal((await read(p)).round,n)}assert.equal((await read(p)).res.Supply,0);await click(p,'#undo');const s=await read(p);assert.equal(s.round,1);assert.equal(s.res.Supply,1);assert.deepEqual(s.zones.fatigue,['H2']);await p.reload();await click(p,'[data-continue="one"]');assert.equal(await p.locator('#roundNumber').innerText(),'1');});
test('113 no-Supply Rest advances Round only after recovery; cancellation and fatal wounds do not',async p=>{for(const complete of [true,false]){await load(p,fixture({res:{Coin:8,Fate:4,Supply:0},zones:{deck:['H3'],hand:[],fatigue:['C5','H2'],wound:[]}}));await action(p,'rest');await click(p,'#restWoundStart');await pick(p,['C5']);await click(p,'#woundNext');assert.equal((await read(p)).round,0);if(complete){await p.locator('#target').fill('2');await pick(p,['H2']);await click(p,'#commit');assert.equal((await read(p)).round,1)}else{await click(p,'#cancel');assert.equal((await read(p)).round,0)}}await load(p,fixture({res:{Coin:8,Fate:4,Supply:0},zones:{deck:['H1'],hand:[],fatigue:[],wound:[]}}));await action(p,'rest');await click(p,'#restWoundStart');await click(p,'#woundNext');await click(p,'#finishWound');assert.equal((await read(p)).dead,true);assert.equal((await read(p)).round,0);});
test('114 Round editor supports Add/Remove, preview, cancel, reload and nonnegative bounds',async p=>{await load(p);await manualAmount(p,'Round',5,{confirm:false});assert.equal(await p.locator('#adjustPreview').innerText(),'New total: 5');await click(p,'#adjustConfirm');assert.equal((await read(p)).round,5);await manualAmount(p,'Round',2,{remove:true});assert.equal((await read(p)).round,3);assert.match((await read(p)).log[0].message,/Round -2/);await manualAmount(p,'Round',7,{confirm:false});await click(p,'#adjustCancel');assert.equal((await read(p)).round,3);await manualAmount(p,'Round',4,{remove:true,confirm:false});assert.equal(await p.locator('#adjustConfirm').isDisabled(),true);await p.keyboard.press('Escape');await p.reload();await click(p,'[data-continue="one"]');assert.equal(await p.locator('#roundNumber').innerText(),'3');});
test('115 Round is independent per character and survives export/import; invalid counters are rejected',async p=>{await seed(p,[slot(fixture(),'one'),slot(fixture(),'two')]);await click(p,'[data-continue="one"]');await manualAmount(p,'Round',12);assert.equal((await read(p,'two')).round,0);await click(p,'#newGameTop');const download=p.waitForEvent('download');await click(p,'[data-export="one"]');const d=await download,raw=JSON.parse(fs.readFileSync(await d.path(),'utf8'));assert.equal(raw.character.round,12);await importData(p,raw);assert.equal(await p.locator('[data-continue]').count(),3);for(const round of [-1,1.5,'2',Number.MAX_SAFE_INTEGER+1]){await importData(p,fixture({round}));assert.match(await p.locator('#status').innerText(),/Import failed/);assert.equal(await p.locator('[data-continue]').count(),3)}const legacy=fixture();delete legacy.round;await importData(p,legacy);const id=await p.locator('[data-continue]').last().getAttribute('data-continue');assert.equal((await read(p,id)).round,0);});
test('116 maximum Round blocks Rest before costs or wounds and can be decreased manually',async p=>{await load(p,fixture({round:Number.MAX_SAFE_INTEGER,res:{Coin:8,Fate:4,Supply:0},zones:{deck:['H3'],hand:[],fatigue:['C5'],wound:[]}}));const before=await read(p);await action(p,'rest');assert.match(await p.locator('#actionStatus').innerText(),/Round limit/);assert.deepEqual(await read(p),before);assert.equal(await p.locator('#restWoundStart').count(),0);await manualAmount(p,'Round',1,{remove:true});assert.equal((await read(p)).round,Number.MAX_SAFE_INTEGER-1);});
test('117 all resource totals open Add/Remove dialogs and update values and activity',async p=>{await load(p);for(const [key,start]of [['Coin',8],['Fate',4],['Supply',2]]){await manualAmount(p,key,5,{confirm:false});assert.equal(await p.locator('#adjustPreview').innerText(),'New total: '+(start+5));await click(p,'#adjustConfirm');assert.equal((await read(p)).res[key],start+5);await manualAmount(p,key,3,{remove:true});assert.equal((await read(p)).res[key],start+2);assert.match((await read(p)).log[0].message,new RegExp(key+' -3'));assert.equal(await p.locator(':focus').getAttribute('data-adjust-resource'),key)}});
test('118 custom resource changes reject empty, fractional, negative, excessive and overflow amounts without mutations',async p=>{await load(p);const before=await read(p);await click(p,'[data-adjust-resource="Coin"]');for(const amount of ['', '0','-1','1.5',String(Number.MAX_SAFE_INTEGER)]){await p.locator('#adjustAmount').fill(amount);assert.equal(await p.locator('#adjustConfirm').isDisabled(),true);assert.deepEqual(await read(p),before)}await click(p,'#adjustRemove');await p.locator('#adjustAmount').fill('9');assert.equal(await p.locator('#adjustConfirm').isDisabled(),true);await click(p,'#adjustCancel');assert.deepEqual(await read(p),before);assert.equal(await p.locator('#undo').isDisabled(),true);});
test('119 all sections collapse with expanded primary defaults and always-visible title, character and Round',async p=>{await load(p);for(const [toggle,body]of [['resourcesToggle','resourcesBody'],['cardZonesToggle','cardZonesBody'],['actionsToggle','actionsBody']]){assert.equal(await p.locator('#'+body).isVisible(),true);assert.equal(await p.locator('#'+toggle).getAttribute('aria-expanded'),'true');await click(p,'#'+toggle);assert.equal(await p.locator('#'+body).isVisible(),false);assert.equal(await p.locator('#'+toggle).getAttribute('aria-expanded'),'false')}for(const body of ['inventoryBody','diceBody','diceHistoryContent','activityBody'])assert.equal(await p.locator('#'+body).isVisible(),false);for(const selector of ['header h1','#characterHeading','#moduleHeading','#roundDisplay'])assert.equal(await p.locator(selector).isVisible(),true);await manualAmount(p,'Round',2);for(const body of ['resourcesBody','cardZonesBody','actionsBody'])assert.equal(await p.locator('#'+body).isVisible(),false);});
test('120 collapsing active Actions preserves selection and cancellation restores manual counter changes',async p=>{await load(p);const before=await read(p);await action(p,'challenge');await click(p,'#begin');await pick(p,['H3']);await click(p,'#actionsToggle');await manualAmount(p,'Round',4);await click(p,'[data-resource="Coin"][data-delta="1"]');await click(p,'#actionsToggle');assert.equal(await p.locator('#operation [data-card="H3"]').getAttribute('class').then(x=>x.includes('selected')),true);assert.equal(await p.locator('#commitChallenge').isEnabled(),true);await click(p,'#cancelEncounter');assert.deepEqual(await read(p),before);});
test('121 section defaults reset on character entry without leaking collapsed state',async p=>{await seed(p,[slot(fixture(),'one'),slot(fixture(),'two')]);await click(p,'[data-continue="one"]');for(const id of ['resourcesToggle','cardZonesToggle','actionsToggle','inventoryToggle','diceToggle','activityToggle'])await click(p,'#'+id);await click(p,'#newGameTop');await click(p,'[data-continue="two"]');for(const body of ['resourcesBody','cardZonesBody','actionsBody'])assert.equal(await p.locator('#'+body).isVisible(),true);for(const body of ['inventoryBody','diceBody','activityBody'])assert.equal(await p.locator('#'+body).isVisible(),false);});
test('122 applied manual wounds shake the screen with a red overlay for half a second without extra state changes',async p=>{await load(p,fixture({zones:{deck:['H3'],hand:[],fatigue:['C5','H2'],wound:[]}}));await action(p,'wound');await p.locator('#woundValue').fill('5');await click(p,'#beginWound');await pick(p,['C5']);assert.equal(await p.locator('#woundOverlay').evaluate(e=>e.classList.contains('active')),false);await click(p,'#woundNext');assert.equal(await p.locator('main').evaluate(e=>e.classList.contains('wound-shake')),true);assert.equal(await p.locator('#woundOverlay').evaluate(e=>getComputedStyle(e).animationDuration),'0.5s');const saved=await read(p);assert.deepEqual(saved.zones.wound,['C5']);await p.waitForTimeout(650);assert.equal(await p.locator('#woundOverlay').evaluate(e=>e.classList.contains('active')),false);assert.equal(await p.locator('main').evaluate(e=>e.classList.contains('wound-shake')),false);assert.deepEqual(await read(p),saved);});
test('123 combat and no-Supply Rest wounds trigger the same effect, which does not replay on reload',async p=>{await load(p);await random(p);await combat(p,['H1'],30);await resolveCombat(p);await pick(p,['H1']);await click(p,'#woundNext');assert.equal(await p.locator('#woundOverlay').evaluate(e=>e.classList.contains('active')),true);await p.reload();await click(p,'[data-continue="one"]');assert.equal(await p.locator('#woundOverlay').evaluate(e=>e.classList.contains('active')),false);await load(p,fixture({res:{Coin:8,Fate:4,Supply:0},zones:{deck:['H3'],hand:[],fatigue:['C5','H2'],wound:[]}}));await action(p,'rest');await click(p,'#restWoundStart');await pick(p,['C5']);await click(p,'#woundNext');assert.equal(await p.locator('#woundOverlay').evaluate(e=>e.classList.contains('active')),true);assert.equal((await read(p)).round,0);});
test('124 victory totals save immediately while Coin and Fate count up and shake visually',async p=>{await load(p);await random(p);await defineEnemy(p,{base:4,fate:20,coin:100});await pick(p,['C5']);await click(p,'#combatCommit');await resolveCombat(p);const saved=await read(p);assert.equal(saved.res.Coin,108);assert.equal(saved.res.Fate,24);assert.equal(await p.locator('.resource-reward').count(),2);assert.equal(await p.locator('[data-resource-box="Supply"]').evaluate(e=>e.classList.contains('resource-reward')),false);const shown=Number(await p.locator('[data-resource-value="Coin"]').innerText());assert.ok(shown>=8&&shown<108);assert.equal(await p.locator('[data-resource-box="Coin"]').evaluate(e=>getComputedStyle(e).animationDuration),'0.8s');await p.waitForTimeout(950);assert.equal(await p.locator('[data-resource-value="Coin"]').innerText(),'108');assert.equal(await p.locator('[data-resource-value="Fate"]').innerText(),'24');assert.equal(await p.locator('.resource-reward').count(),0);assert.deepEqual(await read(p),saved);});
test('125 hidden Resources stays collapsed on victory and reopening shows final totals without replay',async p=>{await load(p);await random(p);await defineEnemy(p,{base:4,fate:2,coin:3});await pick(p,['C5']);await click(p,'#combatCommit');await click(p,'#resourcesToggle');await resolveCombat(p);assert.equal(await p.locator('#resourcesBody').isVisible(),false);assert.equal(await p.locator('.resource-reward').count(),0);assert.equal((await read(p)).res.Coin,11);await click(p,'#resourcesToggle');assert.equal(await p.locator('[data-resource-value="Coin"]').innerText(),'11');assert.equal(await p.locator('.resource-reward').count(),0);});
test('126 animation callbacks never change another character and a pending item reward never replays resource animation',async p=>{await seed(p,[slot(fixture(),'one'),slot(fixture(),'two')]);await click(p,'[data-continue="one"]');await random(p);await defineEnemy(p,{base:4,fate:20,coin:100});await pick(p,['C5']);await click(p,'#combatCommit');await resolveCombat(p);await click(p,'#newGameTop');await click(p,'[data-continue="two"]');await p.waitForTimeout(950);assert.equal((await read(p,'one')).res.Coin,108);assert.equal((await read(p,'two')).res.Coin,8);assert.equal(await p.locator('[data-resource-value="Coin"]').innerText(),'8');assert.equal(await p.locator('.resource-reward').count(),0);await load(p,fixture({inventory:inventoryEight()}));await random(p);await defineEnemy(p,{base:4,fate:2,coin:3,item:rewardItem});await pick(p,['C5']);await click(p,'#combatCommit');await resolveCombat(p);await p.reload();await click(p,'[data-continue="one"]');assert.equal(await p.locator('.resource-reward').count(),0);assert.equal(await p.locator('[data-resource-value="Coin"]').innerText(),'11');assert.equal(await p.locator('#combatRewardModal').isVisible(),true);});
test('127 reduced motion disables shaking/count-up but retains a quiet temporary wound tint',async p=>{await p.emulateMedia({reducedMotion:'reduce'});await load(p);await random(p);await defineEnemy(p,{base:4,fate:2,coin:3});await pick(p,['C5']);await click(p,'#combatCommit');await resolveCombat(p);assert.equal(await p.locator('.resource-reward').count(),0);assert.equal(await p.locator('[data-resource-value="Coin"]').innerText(),'11');await action(p,'wound');await p.locator('#woundValue').fill('1');await click(p,'#beginWound');await pick(p,['C5']);await click(p,'#woundNext');assert.equal(await p.locator('main').evaluate(e=>e.classList.contains('wound-shake')),false);assert.equal(await p.locator('#woundOverlay').evaluate(e=>getComputedStyle(e).animationName),'none');assert.equal(await p.locator('#woundOverlay').evaluate(e=>getComputedStyle(e).opacity),'0.12');await p.waitForTimeout(600);assert.equal(await p.locator('#woundOverlay').evaluate(e=>e.classList.contains('active')),false);});
test('128 Undo cancels transient effects and restores actual resource and wound values',async p=>{await load(p);await random(p);await defineEnemy(p,{base:4,fate:2,coin:3});await pick(p,['C5']);await click(p,'#combatCommit');await resolveCombat(p);await click(p,'#undo');assert.equal((await read(p)).res.Coin,8);assert.equal(await p.locator('.resource-reward').count(),0);await p.waitForTimeout(900);assert.equal(await p.locator('[data-resource-value="Coin"]').innerText(),'8');await click(p,'#cancelEncounter');await load(p,fixture({zones:{deck:['H3'],hand:[],fatigue:['C5','H2'],wound:[]}}));await action(p,'wound');await p.locator('#woundValue').fill('5');await click(p,'#beginWound');await pick(p,['C5']);await click(p,'#woundNext');await p.locator('#undo').evaluate(e=>e.click());assert.equal(await p.locator('#woundOverlay').evaluate(e=>e.classList.contains('active')),false);assert.deepEqual((await read(p)).zones.wound,[]);});
test('129 new resource layout, large totals and adjustment dialogs fit desktop and narrow screens',async(p,ctx,browser)=>{const c=await browser.newContext({viewport:{width:320,height:844},isMobile:true,hasTouch:true});try{const q=await c.newPage();await q.goto(p.url());await load(q);assert.equal(await q.locator('#resources input').count(),0);for(const key of ['Coin','Fate','Supply']){const boxes=await q.locator(`[data-resource-box="${key}"] .resource-controls>button`).evaluateAll(es=>es.map(e=>({x:e.getBoundingClientRect().x,width:e.getBoundingClientRect().width})));assert.ok(boxes[0].x<boxes[1].x&&boxes[1].x<boxes[2].x);assert.ok(boxes[0].width>=44&&boxes[2].width>=44)}await q.locator('[data-adjust-resource="Coin"]').tap();await q.locator('#adjustAmount').fill('5');assert.equal(await q.locator('#adjustPreview').innerText(),'New total: 13');await q.screenshot({path:path.join(OUT,'v27-resource-dialog-mobile.png')});await click(q,'#adjustCancel');await load(q,fixture({round:Number.MAX_SAFE_INTEGER,res:{Coin:Number.MAX_SAFE_INTEGER,Fate:Number.MAX_SAFE_INTEGER,Supply:Number.MAX_SAFE_INTEGER}}));for(const width of [320,390,600,601,800,801,900]){await q.setViewportSize({width,height:900});assert.ok(await q.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));assert.ok(await q.locator('.resource-total').evaluateAll(es=>es.every(e=>e.scrollWidth<=e.clientWidth)))}await q.locator('#roundDisplay').tap();await q.keyboard.press('Escape');}finally{await c.close()}});
test('130 adjustment dialog keyboard focus is contained and returned to the edited total',async p=>{await load(p);await click(p,'[data-adjust-resource="Fate"]');await p.locator('#adjustAdd').focus();await p.keyboard.press('Shift+Tab');assert.equal(await p.locator(':focus').getAttribute('id'),'adjustConfirm');await p.keyboard.press('Tab');assert.equal(await p.locator(':focus').getAttribute('id'),'adjustAdd');await p.keyboard.press('Escape');assert.equal(await p.locator(':focus').getAttribute('data-adjust-resource'),'Fate');await manualAmount(p,'Fate',3);assert.equal(await p.locator(':focus').getAttribute('data-adjust-resource'),'Fate');assert.equal((await read(p)).res.Fate,7);});
test('131 V20 resource, Round, floored combat and Rest work offline without external requests',async(p,ctx,browser)=>{const c=await browser.newContext({offline:true});try{const q=await c.newPage(),origin=new URL(p.url()).origin,external=[];q.setDefaultTimeout(10000);await c.route('**/*',r=>{if(new URL(r.request().url()).origin===origin)return r.fulfill({status:200,contentType:'text/html',body:fs.readFileSync(APP_FILE)});external.push(r.request().url());return r.abort()});await q.goto(origin);await load(q);await manualAmount(q,'Coin',5);await manualAmount(q,'Round',2);await random(q,0);await defineEnemy(q,{base:1,fate:2,coin:3});await pick(q,['H1']);await click(q,'#combatCommit');await resolveCombat(q);await click(q,'#combatExact');await action(q,'rest');await q.locator('#target').fill('1');await pick(q,['H1']);await click(q,'#commit');const s=await read(q);assert.equal(s.round,3);assert.deepEqual(s.res,{Coin:16,Fate:6,Supply:1});assert.deepEqual(external,[]);invariant(s);}finally{await c.close()}});

const {execFileSync,spawnSync}=require('node:child_process'),os=require('node:os');
const actualLibrary=require('../scripts/enemy-library-v27.cjs').validateEnemyLibrary(JSON.parse(fs.readFileSync(path.join(ROOT,'data/enemies.json'),'utf8')));
async function libraryMenu(p){await action(p,'combat');await click(p,'#chooseLibraryEnemy');}
async function selectLibraryEnemy(p,name,start=true){await libraryMenu(p);await p.locator('input[name="enemyLibraryChoice"]').evaluateAll((es,name)=>{const input=es.find(e=>e.value===name);input.click()},name);if(start)await click(p,'#libraryStartCombat');}
function buildTestLibrary(data){const dir=fs.mkdtempSync(path.join(os.tmpdir(),'qfg-library-')),input=path.join(dir,'enemies.json'),output=path.join(dir,'app.html'),dungeonFile=path.join(dir,'dungeons.json');const defs=JSON.parse(fs.readFileSync(path.join(ROOT,'data/dungeons.json'),'utf8'));const ids=new Set(data.enemies.map(e=>e.id));if(!defs.dungeons.every(d=>[...d.encounters.map(e=>e.enemyId),d.boss.enemyId].every(id=>ids.has(id))))defs.dungeons=[];fs.writeFileSync(dungeonFile,JSON.stringify(defs));fs.writeFileSync(input,JSON.stringify(data));const result=spawnSync(process.execPath,[path.join(ROOT,'scripts/build-v27.cjs'),'--data',input,'--dungeons',dungeonFile,'--output',output],{encoding:'utf8'});return {dir,input,output,result,cleanup:()=>fs.rmSync(dir,{recursive:true,force:true})};}

test('132 combat chooser offers creation/library and every cancellation path leaves the character unchanged',async p=>{await load(p);const before=await read(p);await action(p,'combat');assert.equal(await p.locator('#combatChoiceModal').isVisible(),true);assert.equal(await p.locator('#enemySetupModal').isVisible(),false);assert.equal(await p.locator('#enemyLibraryModal').isVisible(),false);await click(p,'#chooseLibraryEnemy');await p.locator('input[name="enemyLibraryChoice"]').first().check();await click(p,'#libraryBack');await p.keyboard.press('Escape');assert.deepEqual(await read(p),before);assert.equal(await p.locator('#undo').isDisabled(),true);await beginCustomCombat(p);await p.locator('#enemyName').fill('Cancelled');await click(p,'#enemySetupCancel');assert.deepEqual(await read(p),before);});
test('133 library lists the JSON enemies, supports one selection and previews without starting combat',async p=>{await load(p);const before=await read(p);await libraryMenu(p);assert.equal(await p.locator('input[name="enemyLibraryChoice"]').count(),actualLibrary.enemies.length);assert.equal(await p.locator('#libraryStartCombat').isDisabled(),true);assert.deepEqual(await p.locator('input[name="enemyLibraryChoice"]').evaluateAll(es=>es.map(e=>e.value)),actualLibrary.enemies.map(e=>e.id));await p.locator('input[value="Skeleton"]').check();assert.match(await p.locator('#libraryEnemyPreview').innerText(),/resistant slash/);await p.locator('input[value="Thief"]').check();assert.equal(await p.locator('input[name="enemyLibraryChoice"]:checked').count(),1);assert.match(await p.locator('#libraryEnemyPreview').innerText(),/A human Thief/);assert.match(await p.locator('#libraryEnemyPreview').innerText(),/A dagger/);assert.equal(await p.locator('#libraryEnemyPreview em').innerText(),'weapon');assert.deepEqual(await read(p),before);});
test('134 starting the selected library enemy snapshots the canonical card and raised enemy details',async p=>{await load(p);await selectLibraryEnemy(p,'Thief');const s=await read(p),thief=actualLibrary.enemies.find(e=>e.id==='Thief');assert.deepEqual(s.combat.enemy,thief);assert.equal(s.combat.base,9);assert.equal(s.combat.wound,1);assert.equal(await p.locator('#enemyLibraryModal').isVisible(),false);assert.equal(await p.locator('#activeEnemyInfo').count(),1);assert.match(await p.locator('#activeEnemyInfo').innerText(),/A human Thief/);assert.match(await p.locator('#activeEnemyInfo').innerText(),/Base Value: 5 Coin/);assert.notEqual(await p.locator('#activeEnemyInfo').evaluate(e=>getComputedStyle(e).boxShadow),'none');assert.equal(s.res.Coin,8);invariant(s);});
test('135 custom enemy entry stores description, italic keyword arrays, WV zero and array-based item reward',async p=>{await load(p);await defineEnemy(p,{name:'Wraith',description:'A spectral guardian',keywords:['Undead','resistant slash'],base:5,woundValue:0,fate:3,coin:2,item:{name:'Spirit Blade',description:'Spirit blade',keywords:['weapon','magic'],baseValue:7}});const e=(await read(p)).combat.enemy;assert.deepEqual(e,{id:'Wraith',name:'Wraith',boss:false,description:'A spectral guardian',CV:5,WV:0,F:3,C:2,KW:['Undead','resistant slash'],Item:{name:'Spirit Blade',description:'Spirit blade',keywords:['weapon','magic'],baseValue:7}});assert.equal(await p.locator('#activeEnemyInfo .enemy-keywords em').innerText(),'Undead - resistant slash');assert.equal(await p.locator('#activeEnemyInfo .enemy-keywords em').evaluate(e=>getComputedStyle(e).fontStyle),'italic');assert.equal(await p.locator('#activeEnemyInfo .enemy-info-item em').innerText(),'weapon - magic');});
test('136 raised enemy details remain through adjustments, wounds, retries and reload',async p=>{await load(p);await random(p);await defineEnemy(p,{name:'Troll',description:'Bridge guardian',keywords:['Large','Strong'],base:30,fate:7});for(const stage of ['choose','decide','adjust']){assert.equal(await p.locator('#activeEnemyInfo').count(),1);if(stage==='choose'){await pick(p,['H1']);await click(p,'#combatCommit')}if(stage==='decide')await click(p,'#combatAdd')}await pick(p,['H2']);await click(p,'#combatApply');await resolveCombat(p);assert.equal(await p.locator('#activeEnemyInfo').count(),1);await pick(p,['H1']);await click(p,'#woundNext');await click(p,'#combatRetry');assert.match(await p.locator('#operation').innerText(),/Base challenge 28/);assert.equal((await read(p)).combat.enemy.CV,30);await p.reload();await click(p,'[data-continue="one"]');assert.match(await p.locator('#activeEnemyInfo').innerText(),/Bridge guardian/);assert.equal(await p.locator('#activeEnemyInfo .enemy-keywords em').innerText(),'Large - Strong');});
test('137 WV zero failure skips wound selection and wound animation while retaining retry/flee',async p=>{await load(p);await random(p);await defineEnemy(p,{base:30,woundValue:0,fate:10,coin:10});await pick(p,['H1']);await click(p,'#combatCommit');await resolveCombat(p);const s=await read(p);assert.equal(s.combat.stage,'afterFail');assert.equal(s.woundTask,null);assert.deepEqual(s.zones.wound,[]);assert.equal(s.dead,false);assert.equal(await p.locator('#woundNext').count(),0);assert.equal(await p.locator('#woundOverlay').evaluate(e=>e.classList.contains('active')),false);await click(p,'#combatFlee');assert.equal((await read(p)).res.Fate,2);assert.equal((await read(p)).res.Coin,8);});
test('138 library victory awards array-keyword items and edits never mutate the library definition',async p=>{await load(p);await random(p);await selectLibraryEnemy(p,'Thief');await pick(p,['C5','D6']);await click(p,'#combatCommit');await resolveCombat(p);let s=await read(p);assert.equal(s.res.Fate,5);assert.equal(s.res.Coin,10);assert.deepEqual(s.inventory,[{name:'A dagger',description:'A dagger',keywords:['weapon'],baseValue:5}]);assert.equal(await p.locator('#activeEnemyInfo').count(),0);await click(p,'#inventoryToggle');assert.equal(await p.locator('.inventory-item-keywords em').innerText(),'weapon');await click(p,'[data-edit-item="0"]');await p.locator('#inventoryKeywords').fill('magic - relic');await click(p,'#inventoryItemConfirm');await selectLibraryEnemy(p,'Thief');s=await read(p);assert.deepEqual(s.combat.enemy.Item.keywords,['weapon']);assert.deepEqual(s.inventory[0].keywords,['magic','relic']);});
test('139 old keyword text and old combat reward fields migrate without losing phrases or hyphenated words',async p=>{const s=fixture();s.inventory=[{name:'Blade',description:'Blade',keywords:'weapon - two-handed - ancient relic',baseValue:5}];s.combat={base:5,wound:1,attempt:0,stage:'choose',modifier:null,adjusted:false,enemy:{name:'Old foe',description:'Legacy',keywords:'Undead - Slow',fateReward:2,coinReward:3,itemReward:{name:'Old reward',description:'Old reward',keywords:'magic - old relic',baseValue:2}}};await load(p,s);await click(p,'#inventoryToggle');assert.equal(await p.locator('.inventory-item-keywords em').innerText(),'weapon - two-handed - ancient relic');assert.equal(await p.locator('[data-edit-item="0"]').isDisabled(),true);await click(p,'#newGameTop');const migrated=await read(p);assert.deepEqual(migrated.inventory[0].keywords,['weapon','two-handed','ancient relic']);assert.deepEqual(migrated.combat.enemy.KW,['Undead','Slow']);assert.deepEqual(migrated.combat.enemy.Item.keywords,['magic','old relic']);assert.equal(migrated.combat.enemy.F,2);assert.equal(migrated.combat.enemy.C,3);});
test('140 inventory keyword input produces arrays, italics and a canonical 300-character budget',async p=>{await load(p);await click(p,'#inventoryToggle');await click(p,'#inventoryAdd');await p.locator('#inventoryName').fill('Test Item');await p.locator('#inventoryDescription').fill('x'.repeat(295));await p.locator('#inventoryKeywords').fill('A - B');assert.match(await p.locator('#inventoryCharacterCount').innerText(),/^0 /);await p.locator('#inventoryKeywords').press('End');await p.locator('#inventoryKeywords').press('C');assert.equal(await p.locator('#inventoryKeywords').inputValue(),'A - B');await click(p,'#inventoryItemConfirm');assert.deepEqual((await read(p)).inventory[0].keywords,['A','B']);assert.equal(await p.locator('.inventory-item-keywords em').innerText(),'A - B');assert.equal(await p.locator('.inventory-item-keywords em').evaluate(e=>getComputedStyle(e).fontStyle),'italic');await click(p,'#inventoryAdd');await p.locator('#inventoryName').fill('Test Item');await p.locator('#inventoryDescription').fill('Another item');await p.locator('#inventoryKeywords').fill('weapon - two-handed');await click(p,'#inventoryItemConfirm');assert.deepEqual((await read(p)).inventory[1].keywords,['weapon','two','handed']);});
test('141 purchases save Coin deductions atomically while the Coin display counts down',async p=>{await load(p);await click(p,'#inventoryToggle');await addItem(p,{desc:'Paid item',purchased:true,price:5});const saved=await read(p);assert.equal(saved.res.Coin,3);assert.equal(saved.inventory.length,1);assert.equal(await p.locator('[data-resource-box="Coin"]').evaluate(e=>e.classList.contains('resource-reward')),true);assert.equal(await p.locator('[data-resource-box="Fate"]').evaluate(e=>e.classList.contains('resource-reward')),false);const displayed=Number(await p.locator('[data-resource-value="Coin"]').innerText());assert.ok(displayed>3&&displayed<=8);await p.waitForTimeout(950);assert.equal(await p.locator('[data-resource-value="Coin"]').innerText(),'3');assert.deepEqual(await read(p),saved);});
test('142 selling an item counts Coin up without animating Fate or repeating proceeds',async p=>{await load(p,fixture({inventory:[{name:'Rope',description:'Rope',keywords:['tool'],baseValue:5}]}));await click(p,'#inventoryToggle');await click(p,'[data-remove-item="0"]');await p.locator('#inventorySold').check();await click(p,'#inventoryRemoveConfirm');const saved=await read(p);assert.equal(saved.res.Coin,13);assert.equal(saved.inventory.length,0);assert.equal(await p.locator('.resource-reward').count(),1);const shown=Number(await p.locator('[data-resource-value="Coin"]').innerText());assert.ok(shown>=8&&shown<13);await p.waitForTimeout(950);assert.equal(await p.locator('[data-resource-value="Coin"]').innerText(),'13');assert.deepEqual(await read(p),saved);});
test('143 free/zero-price transactions, unsold removals and failed purchases do not animate or change Coin',async p=>{await load(p);await click(p,'#inventoryToggle');await addItem(p,{desc:'Free purchase',purchased:true,price:0});assert.equal(await p.locator('.resource-reward').count(),0);await click(p,'[data-remove-item="0"]');await p.locator('#inventorySold').check();await p.locator('#inventorySalePrice').fill('0');await click(p,'#inventoryRemoveConfirm');assert.equal(await p.locator('.resource-reward').count(),0);await addItem(p,{desc:'Found item'});await click(p,'[data-remove-item="0"]');await click(p,'#inventoryRemoveConfirm');assert.equal(await p.locator('.resource-reward').count(),0);await addItem(p,{desc:'Too expensive',purchased:true,price:9});assert.match(await p.locator('#inventoryError').innerText(),/Not enough/);assert.equal((await read(p)).res.Coin,8);assert.equal(await p.locator('.resource-reward').count(),0);});
test('144 purchase animation respects Undo, character switching and reduced motion',async p=>{await seed(p,[slot(fixture(),'one'),slot(fixture(),'two')]);await click(p,'[data-continue="one"]');await click(p,'#inventoryToggle');await addItem(p,{purchased:true,price:5});await click(p,'#undo');assert.equal((await read(p)).res.Coin,8);assert.equal(await p.locator('.resource-reward').count(),0);await addItem(p,{purchased:true,price:5});await click(p,'#newGameTop');await click(p,'[data-continue="two"]');await p.waitForTimeout(900);assert.equal(await p.locator('[data-resource-value="Coin"]').innerText(),'8');assert.equal((await read(p,'one')).res.Coin,3);await p.emulateMedia({reducedMotion:'reduce'});await click(p,'#inventoryToggle');await addItem(p,{purchased:true,price:2});assert.equal(await p.locator('.resource-reward').count(),0);assert.equal(await p.locator('[data-resource-value="Coin"]').innerText(),'6');});
test('145 character exports use version 19 and reject malformed item arrays or inconsistent enemy cards',async p=>{await seed(p,[slot(fixture({inventory:[{name:'Blade',description:'Blade',keywords:['weapon'],baseValue:1}]}))]);const pending=p.waitForEvent('download');await click(p,'[data-export="one"]');const d=await pending,raw=JSON.parse(fs.readFileSync(await d.path(),'utf8'));assert.equal(raw.version,19);assert.deepEqual(raw.character.inventory[0].keywords,['weapon']);for(const keywords of [[1],[''],[['nested']]]){const invalid=fixture();invalid.inventory=[{description:'Bad',keywords,baseValue:1}];await importData(p,invalid);assert.match(await p.locator('#status').innerText(),/Import failed/)}const thief=actualLibrary.enemies.find(e=>e.name==='Thief');await importData(p,fixture({combat:{base:5,wound:1,attempt:0,stage:'choose',modifier:null,adjusted:false,enemy:thief}}));assert.match(await p.locator('#status').innerText(),/Import failed/);assert.equal(await p.locator('[data-continue]').count(),1);});
test('146 library build is deterministic, validates all entries and has no fixed entry count',async()=>{const original=fs.readFileSync(APP_FILE);const valid=buildTestLibrary(actualLibrary);try{assert.equal(valid.result.status,0,valid.result.stderr);assert.deepEqual(fs.readFileSync(valid.output),original)}finally{valid.cleanup()}for(const mutate of [d=>d.enemies.push({...d.enemies[0]}),d=>d.enemies[0].id='mismatch',d=>delete d.enemies[0].description,d=>d.enemies[0].WV=-1,d=>d.enemies[0].KW='not an array',d=>d.enemies.find(e=>e.Item).Item.keywords='not an array']){const data=JSON.parse(JSON.stringify(actualLibrary));mutate(data);const invalid=buildTestLibrary(data);try{assert.notEqual(invalid.result.status,0);assert.equal(fs.existsSync(invalid.output),false);assert.deepEqual(fs.readFileSync(APP_FILE),original)}finally{invalid.cleanup()}}const lots={format:actualLibrary.format,version:5,enemies:Array.from({length:1000},(_,i)=>({...actualLibrary.enemies[0],id:'Enemy '+i,name:'Enemy '+i}))};const large=buildTestLibrary(lots);try{assert.equal(large.result.status,0,large.result.stderr);assert.match(large.result.stdout,/1000 validated enemies/)}finally{large.cleanup()}});
test('147 empty embedded libraries show a recoverable message and still permit custom combat',async(p,ctx,browser)=>{const built=buildTestLibrary({format:actualLibrary.format,version:5,enemies:[]});let c;try{assert.equal(built.result.status,0);c=await browser.newContext();const q=await c.newPage();q.setDefaultTimeout(10000);await q.route('**/*',r=>r.fulfill({status:200,contentType:'text/html',body:fs.readFileSync(built.output)}));await q.goto('http://empty-library.local');await load(q);await libraryMenu(q);assert.match(await q.locator('#libraryError').innerText(),/empty/);assert.equal(await q.locator('#libraryStartCombat').isDisabled(),true);await click(q,'#libraryBack');await click(q,'#chooseCreateEnemy');await click(q,'#startCombat');assert.equal((await read(q)).combat.enemy.name,'Enemy');}finally{if(c)await c.close();built.cleanup()}});
test('148 malicious library text is escaped in both embedded JSON and rendered enemy details',async(p,ctx,browser)=>{const text='<img src=x onerror="window.bad=true">',data={format:actualLibrary.format,version:5,enemies:[{id:text,name:text,boss:false,description:'</script><script>window.bad=true</script>',CV:4,WV:0,F:1,C:0,KW:['<svg onload="window.bad=true">'],Item:null}]};const built=buildTestLibrary(data);let c;try{assert.equal(built.result.status,0);const html=fs.readFileSync(built.output,'utf8');assert.equal(html.includes('</script><script>window.bad=true</script>'),false);c=await browser.newContext();const q=await c.newPage();q.setDefaultTimeout(10000);await q.route('**/*',r=>r.fulfill({status:200,contentType:'text/html',body:html}));await q.goto('http://safe-library.local');await load(q);await libraryMenu(q);await q.locator('input[name="enemyLibraryChoice"]').first().check();await click(q,'#libraryStartCombat');assert.equal(await q.evaluate(()=>!!window.bad),false);assert.equal(await q.locator('#activeEnemyInfo img,#activeEnemyInfo svg').count(),0);assert.ok((await q.locator('#activeEnemyInfo').innerText()).includes('</script>'));}finally{if(c)await c.close();built.cleanup()}});
test('149 library selection works on mobile and new dialogs retain keyboard focus',async(p,ctx,browser)=>{await load(p);await action(p,'combat');assert.equal(await p.locator(':focus').getAttribute('id'),'chooseCreateEnemy');await p.keyboard.press('Shift+Tab');assert.equal(await p.locator(':focus').getAttribute('id'),'combatChoiceCancel');await p.keyboard.press('Escape');const c=await browser.newContext({viewport:{width:320,height:844},isMobile:true,hasTouch:true});try{const q=await c.newPage();q.setDefaultTimeout(10000);await q.goto(p.url());await load(q);await libraryMenu(q);assert.equal(await q.locator('#libraryStartCombat').isDisabled(),true);await q.locator('input[value="Thief"]').check();assert.ok(await q.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await q.screenshot({path:path.join(OUT,'v27-library-mobile.png')});await q.locator('#libraryStartCombat').tap();assert.equal(await q.locator('#activeEnemyInfo').isVisible(),true);assert.ok(await q.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await q.locator('#activeEnemyInfo').screenshot({path:path.join(OUT,'v27-enemy-card-mobile.png')});}finally{await c.close()}});
test('150 library combat and array-keyword item rewards work offline with no library fetch',async(p,ctx,browser)=>{const c=await browser.newContext({offline:true});try{const q=await c.newPage(),origin=new URL(p.url()).origin,external=[];q.setDefaultTimeout(10000);await c.route('**/*',r=>{if(new URL(r.request().url()).origin===origin&&new URL(r.request().url()).pathname==='/')return r.fulfill({status:200,contentType:'text/html',body:fs.readFileSync(APP_FILE)});external.push(r.request().url());return r.abort()});await q.goto(origin);await load(q);await random(q);await selectLibraryEnemy(q,'Thief');await pick(q,['C5','D6']);await click(q,'#combatCommit');await resolveCombat(q);assert.equal((await read(q)).res.Coin,10);assert.deepEqual((await read(q)).inventory[0].keywords,['weapon']);assert.deepEqual(external,[]);}finally{await c.close()}});
test('151 zero-WV exhaustion keeps the existing failure-death rule and Cancel restores the encounter',async p=>{await load(p,fixture({res:{Coin:8,Fate:0,Supply:2},zones:{deck:['H1'],hand:[],fatigue:[],wound:[]}}));const before=await read(p);await random(p);await defineEnemy(p,{base:30,woundValue:0});await pick(p,['H1']);await click(p,'#combatCommit');await resolveCombat(p);assert.equal((await read(p)).dead,false);assert.deepEqual((await read(p)).zones.wound,[]);assert.equal((await read(p)).combat.stage,'afterFail');await click(p,'#cancelEncounter');assert.deepEqual(await read(p),before);});
test('152 build refreshes library data without changing a saved active enemy',async(p,ctx,browser)=>{await load(p);await selectLibraryEnemy(p,'Thief');const saved=await read(p),data=JSON.parse(JSON.stringify(actualLibrary));data.enemies.find(e=>e.name==='Thief').CV=20;const built=buildTestLibrary(data);let c;try{assert.equal(built.result.status,0);c=await browser.newContext();const q=await c.newPage();q.setDefaultTimeout(10000);await q.route('**/*',r=>r.fulfill({status:200,contentType:'text/html',body:fs.readFileSync(built.output)}));await q.goto('http://updated-library.local');await load(q,saved);assert.equal((await read(q)).combat.enemy.CV,9);await click(q,'#cancelEncounter');await selectLibraryEnemy(q,'Thief');assert.equal((await read(q)).combat.enemy.CV,20);}finally{if(c)await c.close();built.cleanup()}});
test('153 legacy keyword-only inventory entries and item keyword phrases are preserved during migration',async p=>{const legacy=fixture();legacy.inventory=[{name:'',description:'',keywords:'old relic',baseValue:1},{name:'Two-handed blade',description:'Two-handed blade',keywords:'two-handed',baseValue:2}];delete legacy.inventory[0].name;delete legacy.inventory[1].name;await seed(p);await importData(p,legacy);assert.match(await p.locator('#status').innerText(),/imported successfully/);const id=await p.locator('[data-continue]').last().getAttribute('data-continue'),s=await read(p,id);assert.deepEqual(s.inventory[0],{name:'old relic',description:'',keywords:['old relic'],baseValue:1});assert.deepEqual(s.inventory[1].keywords,['two-handed']);});

// V22: raw action/resolve clicks deliberately leave the new confirmation prompts pending.
async function winPendingItem(p,{full=false,exact=false}={}){await load(p,fixture({inventory:full?inventoryEight():[]}));await random(p);await defineEnemy(p,{name:'Guardian',base:exact?5:4,fate:2,coin:3,item:{name:'Healing potion',description:'',keywords:['healing item'],baseValue:7}});await pick(p,exact?['H2','H3']:['C5']);await click(p,'#combatCommit');await p.locator('#combatResolve').click();if(exact)await p.locator('#combatExact').click();}
async function selectHealingItem(p,index=0){await click(p,'#useHealItem');await p.locator(`input[name="healItem"][value="${index}"]`).check();await click(p,'#healItemSelect');}

test('154 expanded enemy labels spell out Challenge/Wound Value while the compact list keeps abbreviations',async p=>{await load(p);await selectLibraryEnemy(p,'Giant Spiders',false);const preview=await p.locator('#libraryEnemyPreview').innerText();assert.match(preview,/Challenge Value 10/);assert.match(preview,/Wound Value 3/);assert.doesNotMatch(preview,/\bCV\b|\bWV\b/);assert.match(await p.locator('.enemy-library-row.selected').innerText(),/CV 10 · WV 3/);});
test('155 free-slot victory waits for Keep consent; reload and export preserve a single pending reward',async p=>{await winPendingItem(p);let s=await read(p);assert.equal(s.combat.stage,'reward');assert.equal(s.res.Coin,11);assert.equal(s.res.Fate,6);assert.equal(s.inventory.length,0);assert.equal(await p.locator('#combatRewardModal').isVisible(),true);await p.keyboard.press('Escape');assert.equal((await read(p)).inventory.length,0);await p.reload();await click(p,'[data-continue="one"]');assert.equal((await read(p)).res.Coin,11);await click(p,'#rewardKeep');s=await read(p);assert.equal(s.combat,null);assert.deepEqual(s.inventory,[{name:'Healing Potion',description:'',keywords:['healing item'],baseValue:7}]);await p.reload();await click(p,'[data-continue="one"]');assert.equal((await read(p)).inventory.length,1);assert.equal((await read(p)).res.Coin,11);});
test('156 declining a free-slot item retains Fate/Coin but adds no inventory item',async p=>{await winPendingItem(p,{exact:true});assert.equal((await read(p)).inventory.length,0);await click(p,'#rewardDiscard');const s=await read(p);assert.equal(s.combat,null);assert.equal(s.res.Coin,11);assert.equal(s.res.Fate,6);assert.deepEqual(s.inventory,[]);});
test('157 Keep at capacity opens single-item replacement; Back and Discard retain existing items',async p=>{await winPendingItem(p,{full:true});assert.equal(await p.locator('#rewardQuestion').isVisible(),true);await click(p,'#rewardKeep');assert.equal(await p.locator('input[name="rewardDiscard"]').count(),8);assert.equal(await p.locator('#rewardReplaceConfirm').isDisabled(),true);await click(p,'#rewardReplacementBack');await click(p,'#rewardDiscard');assert.deepEqual((await read(p)).inventory,inventoryEight());assert.equal((await read(p)).res.Coin,11);});
test('158 keyword entry rejects commas in inventory/enemy/reward fields and treats spaces as one keyword',async p=>{await load(p);await click(p,'#inventoryToggle');await p.locator('#inventoryAdd').click();await p.locator('#inventoryName').fill('Potion');await p.locator('#inventoryKeywords').fill('healing,magic');await click(p,'#inventoryItemConfirm');assert.match(await p.locator('#inventoryError').innerText(),/Commas are not allowed/);assert.equal((await read(p)).inventory.length,0);await p.locator('#inventoryKeywords').fill('healing item-magic');await click(p,'#inventoryItemConfirm');assert.deepEqual((await read(p)).inventory[0].keywords,['healing item','magic']);await beginCustomCombat(p);await p.locator('#enemyKeywords').fill('undead,large');assert.equal(await p.locator('#startCombat').isDisabled(),true);assert.equal((await read(p)).combat,null);await p.locator('#enemyKeywords').fill('resistant slash');await p.locator('#enemyHasItem').check();await p.locator('#enemyItemName').fill('Axe');await p.locator('#enemyItemKeywords').fill('weapon,metal');assert.equal(await p.locator('#startCombat').isDisabled(),true);await p.locator('#enemyItemKeywords').fill('weapon - heavy metal');await click(p,'#startCombat');const e=(await read(p)).combat.enemy;assert.deepEqual(e.KW,['resistant slash']);assert.deepEqual(e.Item.keywords,['weapon','heavy metal']);});
test('159 Rest confirmation Cancel/Escape do not alter cards, Supply, Round, log or Undo history',async p=>{await load(p,fixture({zones:{deck:['H3'],hand:[],fatigue:['H1'],wound:[]}}));const before=await read(p);await p.locator('[data-mode="rest"]').click();assert.match(await p.locator('#restConfirmModal').innerText(),/Rest will move to the next Round\./);assert.equal(await p.locator('#target').count(),0);await click(p,'#restConfirmCancel');assert.deepEqual(await read(p),before);assert.equal(await p.locator('#undo').isDisabled(),true);await p.locator('[data-mode="rest"]').click();await p.keyboard.press('Escape');assert.deepEqual(await read(p),before);await p.locator('[data-mode="rest"]').click();await click(p,'#restConfirmYes');assert.equal(await p.locator('#target').inputValue(),'5');assert.equal((await read(p)).round,0);await pick(p,['H1']);await click(p,'#commit');assert.equal((await read(p)).round,1);assert.equal((await read(p)).res.Supply,1);});
test('160 no-Supply Rest requires confirmation before wounds and retains default recovery value five',async p=>{await load(p,fixture({res:{Coin:8,Fate:4,Supply:0},zones:{deck:['H3'],hand:[],fatigue:['C5','H2'],wound:[]}}));await p.locator('[data-mode="rest"]').click();assert.equal(await p.locator('#restWoundStart').count(),0);await click(p,'#restConfirmYes');await click(p,'#restWoundStart');await pick(p,['C5']);await click(p,'#woundNext');assert.equal(await p.locator('#target').inputValue(),'5');assert.equal((await read(p)).round,0);});
test('161 Heal defaults to five and Use item sits to the right of Healing value',async p=>{await load(p,fixture({zones:{deck:['H3'],hand:[],fatigue:[],wound:['H1']}}));await action(p,'heal');assert.equal(await p.locator('#target').inputValue(),'5');const value=await p.locator('#target').boundingBox(),button=await p.locator('#useHealItem').boundingBox();assert.ok(button.x>=value.x+value.width);assert.ok(Math.abs((button.y+button.height)-(value.y+value.height))<15);});
test('162 selecting an item changes only Heal presentation; confirmation consumes exactly one item with no Coin change',async p=>{const items=[{name:'Potion',description:'Restore health',keywords:['heal'],baseValue:7},{name:'Potion',description:'Second bottle',keywords:['heal'],baseValue:9}];await load(p,fixture({inventory:items,zones:{deck:['H3'],hand:[],fatigue:[],wound:['H1','H2']}}));const before=await read(p);await action(p,'heal');await selectHealingItem(p,1);assert.deepEqual(await read(p),before);assert.equal(await p.locator('#healItemModal').isVisible(),false);assert.equal(await p.locator('#useHealItem').count(),0);assert.equal(await p.locator('#healItemNotice').innerText(),'Heal will consume item: Potion');await pick(p,['H1']);assert.equal(await p.locator('#healItemNotice').count(),1);await click(p,'#commit');let s=await read(p);assert.deepEqual(s.inventory,[items[0]]);assert.deepEqual(s.res,before.res);assert.deepEqual(s.zones.wound,['H2']);assert.match(s.log.map(x=>x.message).join('\n'),/Heal consumed item: Potion/);invariant(s);await click(p,'#undo');assert.deepEqual(await read(p),before);});
test('163 cancelled Heal, picker cancellation, invalid healing and reload never consume the chosen item',async p=>{const item={name:'Salve',description:'',keywords:['heal'],baseValue:2};await load(p,fixture({inventory:[item],zones:{deck:['H3'],hand:[],fatigue:[],wound:['H2']}}));const before=await read(p);await action(p,'heal');await click(p,'#useHealItem');await p.keyboard.press('Escape');assert.equal(await p.locator('#useHealItem').count(),1);await selectHealingItem(p);await p.locator('#target').fill('1');await pick(p,['H2']);assert.equal(await p.locator('#commit').isDisabled(),true);assert.deepEqual(await read(p),before);await click(p,'#cancel');assert.deepEqual(await read(p),before);await action(p,'heal');await selectHealingItem(p);await p.reload();await click(p,'[data-continue="one"]');assert.deepEqual(await read(p),before);await action(p,'heal');assert.equal(await p.locator('#useHealItem').count(),1);});
test('164 empty inventory picker is recoverable; Heal without an item remains available',async p=>{await load(p,fixture({zones:{deck:['H3'],hand:[],fatigue:[],wound:['H1']}}));await action(p,'heal');await click(p,'#useHealItem');assert.match(await p.locator('#healItemChoices').innerText(),/No items with the heal keyword/);assert.equal(await p.locator('#healItemSelect').isDisabled(),true);await click(p,'#healItemCancel');await pick(p,['H1']);await click(p,'#commit');assert.deepEqual((await read(p)).zones.wound,[]);assert.deepEqual((await read(p)).inventory,[]);});
test('165 changed or removed inventory selection cannot consume a different item during Heal',async p=>{await load(p,fixture({inventory:[{name:'Potion',description:'',keywords:['heal'],baseValue:7},{name:'Shield',description:'',keywords:['heal'],baseValue:5}],zones:{deck:['H3'],hand:[],fatigue:[],wound:['H1']}}));await action(p,'heal');await selectHealingItem(p);await click(p,'#inventoryToggle');await click(p,'[data-remove-item="0"]');await click(p,'#inventoryRemoveConfirm');assert.equal(await p.locator('#healItemNotice').count(),0);assert.equal(await p.locator('#useHealItem').count(),1);await pick(p,['H1']);await click(p,'#commit');assert.deepEqual((await read(p)).inventory.map(x=>x.name),['Shield']);});
test('166 required item name and optional description work across add/edit/remove/reward screens',async p=>{await load(p);await click(p,'#inventoryToggle');await p.locator('#inventoryAdd').click();await p.locator('#inventoryDescription').fill('Description only');await click(p,'#inventoryItemConfirm');assert.match(await p.locator('#inventoryError').innerText(),/Name is required/);await p.locator('#inventoryName').fill('Rope');await p.locator('#inventoryDescription').fill('');await click(p,'#inventoryItemConfirm');assert.deepEqual((await read(p)).inventory[0],{name:'Rope',description:'',keywords:[],baseValue:1});assert.equal(await p.locator('.inventory-item-name').innerText(),'Rope');await click(p,'[data-edit-item="0"]');assert.equal(await p.locator('#inventoryName').inputValue(),'Rope');await p.locator('#inventoryName').fill('Long rope');await click(p,'#inventoryItemConfirm');await click(p,'[data-remove-item="0"]');assert.equal(await p.locator('#inventoryRemoveName').innerText(),'Long Rope');await click(p,'#inventoryRemoveForm button.secondary');await defineEnemy(p,{item:{name:'Reward',description:'',keywords:[],baseValue:0}});assert.equal((await read(p)).combat.enemy.Item.name,'Reward');assert.match(await p.locator('#activeEnemyInfo').innerText(),/Item reward: Reward/);});
test('167 V21 item and active enemy reward migration creates names without losing descriptions or old keyword phrases',async p=>{const old=fixture();old.inventory=[{description:'Old potion',keywords:['healing item'],baseValue:3},{description:'',keywords:'old relic',baseValue:1}];old.combat={base:4,wound:1,attempt:0,stage:'choose',modifier:null,adjusted:false,enemy:{id:'Old enemy',name:'Old enemy',description:'Legacy',CV:4,WV:1,F:1,C:2,KW:['resistant slash'],Item:{description:'Old sword',keywords:['two-handed'],baseValue:4}}};await load(p,old);await click(p,'#newGameTop');await click(p,'[data-continue="one"]');const s=await read(p);assert.deepEqual(s.inventory,[{name:'Old potion',description:'Old potion',keywords:['healing item'],baseValue:3},{name:'old relic',description:'',keywords:['old relic'],baseValue:1}]);assert.deepEqual(s.combat.enemy.Item,{name:'Old sword',description:'Old sword',keywords:['two-handed'],baseValue:4});await click(p,'#newGameTop');const download=p.waitForEvent('download');await click(p,'[data-export="one"]');const d=await download,raw=JSON.parse(fs.readFileSync(await d.path(),'utf8'));assert.equal(raw.version,19);await importData(p,raw);const id=await p.locator('[data-continue]').last().getAttribute('data-continue');assert.deepEqual(await read(p,id),s);});
test('168 V22 library data/template require item names, optional descriptions, and comma-free keyword arrays',async()=>{const {validateEnemyLibrary}=require('../scripts/enemy-library-v27.cjs');assert.equal(actualLibrary.version,5);assert.equal(validateEnemyLibrary(JSON.parse(fs.readFileSync(path.join(ROOT,'data/enemies.template.json'),'utf8'))).version,5);assert.equal(actualLibrary.enemies.find(e=>e.name==='Thief').Item.name,'A dagger');for(const mutate of [d=>delete d.enemies.find(e=>e.Item).Item.name,d=>d.enemies.find(e=>e.Item).Item.name='',d=>d.enemies[0].KW=['large, undead'],d=>d.enemies.find(e=>e.Item).Item.keywords=['weapon, magic']]){const d=structuredClone(actualLibrary);mutate(d);assert.throws(()=>validateEnemyLibrary(d))}const d=structuredClone(actualLibrary);delete d.enemies.find(e=>e.Item).Item.description;assert.equal(validateEnemyLibrary(d).enemies.find(e=>e.Item).Item.description,'');});
test('169 Round hover matches resource-total hover and wound buttons use their new labels',async p=>{await load(p);await p.mouse.move(0,0);const before=await p.locator('#roundDisplay').evaluate(e=>getComputedStyle(e).backgroundColor);await p.locator('#roundDisplay').hover();const hover=await p.locator('#roundDisplay').evaluate(e=>getComputedStyle(e).backgroundColor);assert.notEqual(before,hover);await p.locator('[data-adjust-resource="Coin"]').hover();assert.equal(hover,await p.locator('[data-adjust-resource="Coin"]').evaluate(e=>getComputedStyle(e).backgroundColor));assert.equal(await p.locator('[data-mode="wound"]').innerText(),'Wound');await action(p,'wound');assert.equal(await p.locator('#beginWound').innerText(),'Select Cards');});
test('170 Combat and Challenge omit adjustment explanations at every cost but retain button costs',async p=>{for(const combatMode of [false,true]){await load(p);await random(p);if(combatMode)await combat(p,['H3'],30);else await challenge(p,['H3'],30);for(const [cost,id]of [[1,'H2'],[2,'H1']]){assert.doesNotMatch(await p.locator('#operation').innerText(),/Next adjustment costs|each confirmed adjustment doubles/);assert.match(await p.locator(combatMode?'#combatAdd':'#add').innerText(),new RegExp(cost+' Fate'));await adjust(p,combatMode,true,id)}}});
test('171 Heal picker keyboard trap and mobile value/item layout remain usable',async(p,ctx,browser)=>{await load(p,fixture({inventory:[{name:'Potion',description:'',keywords:['heal'],baseValue:0}],zones:{deck:['H3'],hand:[],fatigue:[],wound:['H1']}}));await action(p,'heal');await click(p,'#useHealItem');await p.keyboard.press('Shift+Tab');assert.equal(await p.locator(':focus').getAttribute('id'),'healItemCancel');await p.keyboard.press('Escape');const c=await browser.newContext({viewport:{width:320,height:844},isMobile:true,hasTouch:true});try{const q=await c.newPage();q.setDefaultTimeout(10000);await q.goto(p.url());await load(q,fixture({inventory:[{name:'Potion',description:'Optional details',keywords:['heal'],baseValue:0}],zones:{deck:['H3'],hand:[],fatigue:[],wound:['H1']}}));await action(q,'heal');const v=await q.locator('#target').boundingBox(),b=await q.locator('#useHealItem').boundingBox();assert.ok(b.x>=v.x+v.width);assert.ok(await q.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await q.locator('#operation').screenshot({path:path.join(OUT,'v27-heal-mobile.png')});await selectHealingItem(q);await pick(q,['H1']);await click(q,'#commit');assert.equal((await read(q)).inventory.length,0);}finally{await c.close()}});
test('172 V22 offline named reward consent and item-powered healing preserve resources and card partition',async(p,ctx,browser)=>{const c=await browser.newContext({offline:true});try{const q=await c.newPage(),origin=new URL(p.url()).origin;q.setDefaultTimeout(10000);await c.route('**/*',r=>r.fulfill({status:200,contentType:'text/html',body:fs.readFileSync(APP_FILE)}));await q.goto(origin);await load(q,fixture({zones:{deck:['C5','D6','H3'],hand:[],fatigue:[],wound:['H1']}}));await random(q);await selectLibraryEnemy(q,'Thief');await pick(q,['C5','D6']);await click(q,'#combatCommit');await q.locator('#combatResolve').click();assert.equal((await read(q)).inventory.length,0);await click(q,'#rewardKeep');assert.equal((await read(q)).inventory[0].name,'A dagger');await click(q,'#inventoryToggle');await click(q,'[data-edit-item="0"]');await q.locator('#inventoryKeywords').fill('heal');await click(q,'#inventoryItemConfirm');await action(q,'heal');await selectHealingItem(q);await pick(q,['H1']);await click(q,'#commit');const s=await read(q);assert.equal(s.inventory.length,0);assert.equal(s.res.Coin,10);assert.equal(s.res.Fate,5);invariant(s);}finally{await c.close()}});
test('173 explicit blank item names are rejected on import without discarding or overwriting items',async p=>{await seed(p);const before=await read(p);await importData(p,fixture({inventory:[{name:'',description:'',keywords:[],baseValue:1}]}));assert.match(await p.locator('#status').innerText(),/Import failed/);assert.deepEqual(await read(p),before);});

// V23 equipment and starting loadout coverage.
function gear(name='Sword',type='weapon',modifier=2,points=4,enabled=true){return {name,description:'Optional detail',keywords:[type],baseValue:3,equipment:{type,modifier,usage:Array.from({length:4},(_,i)=>i<points)}}}
async function showGear(p){if(await p.locator('#equipmentToggle').getAttribute('aria-expanded')==='false')await click(p,'#equipmentToggle')}
async function chooseGearFields(p,prefix,{type='weapon',modifier=2}={}){await p.locator('#'+prefix+'IsEquipment').check();await p.locator('#'+prefix+'EquipmentType').selectOption(type);await p.locator('#'+prefix+'EquipmentModifier').fill(String(modifier))}
async function newGearItem(p,item){await click(p,'#inventoryAdd');await p.locator('#inventoryName').fill(item.name);await p.locator('#inventoryDescription').fill(item.description||'');await chooseGearFields(p,'inventory',item.equipment);await click(p,'#inventoryItemConfirm')}

test('174 Inventory typography and Heal inline label, close button and bold red consumption name match V23',async p=>{await load(p,fixture({inventory:[{name:'Potion',description:'A smaller description',keywords:['heal'],baseValue:1}],zones:{deck:['H3'],hand:[],fatigue:[],wound:['H1']}}));await click(p,'#inventoryToggle');const styles=await p.evaluate(()=>{const n=getComputedStyle(document.querySelector('.inventory-item-name')),d=getComputedStyle(document.querySelector('.inventory-item-description'));return {nw:n.fontWeight,dw:d.fontWeight,ns:parseFloat(n.fontSize),ds:parseFloat(d.fontSize)}});assert.ok(Number(styles.nw)>=700);assert.equal(styles.dw,'400');assert.ok(styles.ds<styles.ns);await action(p,'heal');const label=await p.locator('.heal-inline label').boundingBox(),input=await p.locator('#target').boundingBox(),button=await p.locator('#useHealItem').boundingBox();assert.ok(label.x<input.x);assert.ok(button.x-input.x-input.width<=10);await selectHealingItem(p);assert.equal(await p.locator('#healItemNotice').innerText(),'Heal will consume item: Potion');assert.equal(await p.locator('#healItemNotice strong').innerText(),'Potion');assert.equal(await p.locator('#healItemNotice strong').evaluate(e=>getComputedStyle(e).color),'rgb(165, 42, 42)');assert.equal(await p.locator('#healItemNotice strong').evaluate(e=>getComputedStyle(e).fontWeight),'700');});
test('175 equipment tab has one slot per type, collapses, and adds equipped gear through the shared item form',async p=>{await load(p);assert.equal(await p.locator('#equipmentBody').isVisible(),false);await showGear(p);assert.equal(await p.locator('[data-equipment-slot]').count(),2);await click(p,'[data-add-equipment="weapon"]');assert.equal(await p.locator('#inventoryIsEquipment').isChecked(),true);assert.equal(await p.locator('#inventoryIsEquipment').isDisabled(),true);assert.equal(await p.locator('#inventoryEquipmentType').inputValue(),'weapon');await p.locator('#inventoryName').fill('Sword');await p.locator('#inventoryEquipmentModifier').fill('2');await click(p,'#inventoryItemConfirm');const s=await read(p);assert.equal(s.equipment.weapon.name,'Sword');assert.equal(s.equipment.armor,null);assert.deepEqual(s.equipment.weapon.equipment.usage,[true,true,true,true]);assert.equal(await p.locator('[data-equipment-enable]').count(),0);assert.equal(await p.locator('[data-equipment-slot="weapon"] .usage-point.available').count(),4);});
test('176 item equipment flag requires both type and positive integer modifier without side effects',async p=>{await load(p);await click(p,'#inventoryToggle');await click(p,'#inventoryAdd');await p.locator('#inventoryName').fill('Equipment');await p.locator('#inventoryIsEquipment').check();const before=await read(p);for(const [type,modifier]of [['','2'],['weapon',''],['weapon','0'],['armor','-1'],['armor','1.5'],['weapon',String(Number.MAX_SAFE_INTEGER)]]){await p.locator('#inventoryEquipmentType').selectOption(type);await p.locator('#inventoryEquipmentModifier').fill(modifier);await click(p,'#inventoryItemConfirm');assert.ok((await p.locator('#inventoryError').innerText()).length>0);assert.deepEqual(await read(p),before)}await p.locator('#inventoryEquipmentType').selectOption('armor');await p.locator('#inventoryEquipmentModifier').fill('3');await click(p,'#inventoryItemConfirm');assert.deepEqual((await read(p)).inventory[0].equipment,{type:'armor',modifier:3,usage:[true,true,true,true]});});
test('177 equipping swaps exact items at full capacity and preserves all durability/enabled fields and Undo',async p=>{const current=gear('Old sword','weapon',1,2,false),next=gear('New sword','weapon',4,1),items=[next,...inventoryEight().slice(1)];await load(p,fixture({inventory:items,equipment:{weapon:current,armor:null}}));await click(p,'#inventoryToggle');await click(p,'[data-equip-item="0"]');let s=await read(p);assert.deepEqual(s.equipment.weapon,next);assert.equal(s.inventory.length,8);assert.deepEqual(s.inventory[0],current);await click(p,'#undo');s=await read(p);assert.deepEqual(s.equipment.weapon,current);assert.deepEqual(s.inventory,items);await showGear(p);assert.equal(await p.locator('[data-unequip="weapon"]').isDisabled(),true);});
test('178 weapon modifier changes victory/exact-match outcome without spending usage on success',async p=>{const item=gear();await load(p,fixture({equipment:{weapon:item,armor:null}}));await random(p);await combat(p,['H3'],5);assert.match(await p.locator('#operation').innerText(),/Weapon bonus: \+2/);assert.match(await p.locator('#operation').innerText(),/Action Hand 5 · Success/);await p.locator('#combatResolve').click();assert.equal((await read(p)).combat.stage,'exact');await pick(p,['H3']);await click(p,'#combatExact');const s=await read(p);assert.deepEqual(s.equipment.weapon,item);assert.equal(s.combat,null);assert.ok(s.zones.deck.includes('H3'));invariant(s);});
test('179 combat Fate add/remove live previews include the weapon bonus at every cost',async p=>{await load(p,fixture({equipment:{weapon:gear('Blade','weapon',4),armor:null}}));await random(p);await combat(p,['H1'],6);assert.match(await p.locator('#operation').innerText(),/Action Hand 5 · Failure/);await click(p,'#combatAdd');await pick(p,['H2']);assert.match(await p.locator('#handAdjustmentPreview').innerText(),/5 → 7/);assert.match(await p.locator('#handAdjustmentPreview').innerText(),/Success/);await click(p,'#combatApply');await click(p,'#combatRemove');await pick(p,['H1']);assert.match(await p.locator('#handAdjustmentPreview').innerText(),/7 → 6/);assert.match(await p.locator('#handAdjustmentPreview').innerText(),/Exact match/);assert.equal((await read(p)).equipment.weapon.equipment.usage.filter(Boolean).length,4);});
test('180 equipment has no effect on Challenge totals or wear and manual wounds do not use armor',async p=>{const equipment={weapon:gear('Sword','weapon',10),armor:gear('Plate','armor',5)};await load(p,fixture({equipment}));await random(p);await challenge(p,['H1'],10);assert.match(await p.locator('#operation').innerText(),/Currently unsuccessful/);await click(p,'#resolve');assert.deepEqual((await read(p)).equipment,equipment);await action(p,'wound');await click(p,'#beginWound');await pick(p,['H1']);await click(p,'#woundNext');assert.deepEqual((await read(p)).equipment,equipment);});
test('181 failed combat spends one weapon/armor usage, reduces actual wound allocation and reload never repeats wear',async p=>{await load(p,fixture({equipment:{weapon:gear('Sword','weapon',1),armor:gear('Mail','armor',2)}}));await random(p);await combat(p,['H1'],30,3);await p.locator('#combatResolve').click();let s=await read(p);assert.equal(s.combat.lastWound,1);assert.equal(s.woundTask.value,1);assert.equal(s.equipment.weapon.equipment.usage.filter(Boolean).length,3);assert.equal(s.equipment.armor.equipment.usage.filter(Boolean).length,3);await p.reload();await click(p,'[data-continue="one"]');await pick(p,['H1']);await click(p,'#woundNext');s=await read(p);assert.equal(s.equipment.weapon.equipment.usage.filter(Boolean).length,3);assert.equal(s.equipment.armor.equipment.usage.filter(Boolean).length,3);await click(p,'#combatRetry');await pick(p,['H2']);await click(p,'#combatCommit');await p.locator('#combatResolve').click();s=await read(p);assert.equal(s.equipment.weapon.equipment.usage.filter(Boolean).length,2);assert.equal(s.equipment.armor.equipment.usage.filter(Boolean).length,2);});
test('182 last usage still applies its modifier, then broken equipment turns red and stops helping on retries',async p=>{await load(p,fixture({equipment:{weapon:gear('Fragile sword','weapon',1,1),armor:gear('Fragile plate','armor',2,1)}}));await random(p);await combat(p,['H1'],30,3);await p.locator('#combatResolve').click();assert.equal((await read(p)).woundTask.value,1);await showGear(p);for(const type of ['weapon','armor']){assert.equal(await p.locator(`[data-equipment-slot="${type}"]`).evaluate(e=>e.classList.contains('equipment-broken')),true);assert.match(await p.locator(`[data-equipment-slot="${type}"]`).innerText(),/broken, can't be used/);assert.equal(await p.locator(`[data-equipment-slot="${type}"] .usage-point.available`).count(),0)}await pick(p,['H1']);await click(p,'#woundNext');await click(p,'#combatRetry');assert.match(await p.locator('#operation').innerText(),/Weapon bonus: \+0 · Armor reduction: 0/);await pick(p,['H2']);await click(p,'#combatCommit');await p.locator('#combatResolve').click();assert.equal((await read(p)).woundTask.value,3);assert.deepEqual((await read(p)).equipment.weapon.equipment.usage,[false,false,false,false]);});
test('183 armor can prevent every wound; no allocation or wound animation occurs and zero-WV failure does not wear armor',async p=>{await load(p,fixture({equipment:{weapon:null,armor:gear('Plate','armor',5)}}));await random(p);await combat(p,['H1'],30,2);await p.locator('#combatResolve').click();let s=await read(p);assert.equal(s.combat.stage,'afterFail');assert.equal(s.woundTask,null);assert.deepEqual(s.zones.wound,[]);assert.equal(s.equipment.armor.equipment.usage.filter(Boolean).length,3);assert.equal(await p.locator('#woundOverlay').evaluate(e=>e.classList.contains('active')),false);await click(p,'#cancelEncounter');await combat(p,['H1'],30,0);await p.locator('#combatResolve').click();s=await read(p);assert.equal(s.equipment.armor.equipment.usage.filter(Boolean).length,4);});
test('184 broken equipment supplies no combat bonus or reduction and loses no usage points',async p=>{const equipment={weapon:gear('Sword','weapon',20,0,false),armor:gear('Plate','armor',20,0,false)};await load(p,fixture({equipment}));await random(p);await combat(p,['H1'],10,2);assert.match(await p.locator('#operation').innerText(),/Action Hand 1 · Failure/);await p.locator('#combatResolve').click();assert.equal((await read(p)).woundTask.value,2);assert.deepEqual((await read(p)).equipment,equipment);});
test('185 exact-match/wound/reward stages lock equipped gear so changing equipment cannot invalidate a committed result',async p=>{await load(p,fixture({inventory:[gear('Alternative')],equipment:{weapon:gear(),armor:null}}));await random(p);await combat(p,['H3'],5);await p.locator('#combatResolve').click();await showGear(p);assert.equal(await p.locator('[data-equipment-enable]').count(),0);assert.equal(await p.locator('[data-edit-equipment="weapon"]').isDisabled(),true);assert.equal(await p.locator('[data-usage-type]').count(),0);await click(p,'#inventoryToggle');assert.equal(await p.locator('[data-equip-item="0"]').isDisabled(),true);await p.reload();await click(p,'[data-continue="one"]');assert.equal((await read(p)).combat.stage,'exact');});
test('186 Fix validates cost and funds; Cancel is inert; payment, four points and enablement commit together and Undo restores them',async p=>{const broken=gear('Broken sword','weapon',2,0);await load(p,fixture({equipment:{weapon:broken,armor:null}}));const before=await read(p);await showGear(p);await click(p,'[data-fix-equipment="weapon"]');for(const cost of ['','-1','1.5','9']){await p.locator('#repairCost').fill(cost);assert.equal(await p.locator('#repairConfirm').isDisabled(),true);assert.deepEqual(await read(p),before)}await p.keyboard.press('Escape');assert.deepEqual(await read(p),before);await click(p,'[data-fix-equipment="weapon"]');await p.locator('#repairCost').fill('3');await click(p,'#repairConfirm');let s=await read(p);assert.equal(s.res.Coin,5);assert.deepEqual(s.equipment.weapon.equipment.usage,[true,true,true,true]);assert.equal(s.equipment.weapon.equipment.usage.some(Boolean),true);assert.equal(await p.locator('[data-fix-equipment="weapon"]').count(),0);await click(p,'#undo');assert.deepEqual(await read(p),before);});
test('187 repair supports armor and zero cost, persists through reload/export and never pays twice',async p=>{await load(p,fixture({equipment:{weapon:null,armor:gear('Broken mail','armor',2,0)}}));await showGear(p);await click(p,'[data-fix-equipment="armor"]');await click(p,'#repairConfirm');assert.equal((await read(p)).res.Coin,8);await p.reload();await click(p,'[data-continue="one"]');assert.equal((await read(p)).equipment.armor.equipment.usage.some(Boolean),true);await click(p,'#newGameTop');const promise=p.waitForEvent('download');await click(p,'[data-export="one"]');const file=await promise,raw=JSON.parse(fs.readFileSync(await file.path(),'utf8'));assert.equal(raw.version,19);await importData(p,raw);const id=await p.locator('[data-continue]').last().getAttribute('data-continue');assert.equal((await read(p,id)).equipment.armor.equipment.usage.filter(Boolean).length,4);});
test('188 repair drafts cannot apply to another character after navigation',async p=>{await seed(p,[slot(fixture({equipment:{weapon:gear('Broken','weapon',2,0),armor:null}}),'one'),slot(fixture(),'two')]);await click(p,'[data-continue="one"]');await showGear(p);await click(p,'[data-fix-equipment="weapon"]');await p.locator('#repairCost').fill('2');await p.locator('#newGameTop').evaluate(e=>e.click());await click(p,'[data-continue="two"]');assert.equal(await p.locator('#repairModal').isVisible(),false);assert.equal((await read(p,'one')).res.Coin,8);assert.equal((await read(p,'two')).equipment.weapon,null);});
test('189 usage indicators are read-only red/gray boxes without checkmarks or an enable control',async p=>{await load(p,fixture({equipment:{weapon:gear('Sword','weapon',2,1),armor:null}}));const before=await read(p);await showGear(p);assert.equal(await p.locator('.equipment-usage input,[data-equipment-enable]').count(),0);assert.equal(await p.locator('[data-equipment-slot="weapon"] .usage-point.available').count(),1);assert.equal(await p.locator('[data-equipment-slot="weapon"] .usage-point.spent').count(),3);await p.locator('.usage-point.available').click();assert.deepEqual(await read(p),before);});
test('190 equipping into an empty slot moves the item out of inventory and unequipping moves it back',async p=>{const item=gear('Mail','armor',2,2,false);await load(p,fixture({inventory:[item]}));await click(p,'#inventoryToggle');await click(p,'[data-equip-item="0"]');assert.deepEqual((await read(p)).equipment.armor,item);assert.deepEqual((await read(p)).inventory,[]);await showGear(p);await click(p,'[data-unequip="armor"]');assert.equal((await read(p)).equipment.armor,null);assert.deepEqual((await read(p)).inventory,[item]);});
test('191 creation supports optional equipped weapon/armor plus eight starting items without Coin or card-point costs',async p=>{await click(p,'#createCharacter');for(const type of ['weapon','armor']){await click(p,`[data-start-equipment="${type}"]`);await p.locator('#inventoryName').fill('Starting '+type);await p.locator('#inventoryEquipmentModifier').fill('2');await click(p,'#inventoryItemConfirm')}for(let i=0;i<8;i++){await click(p,'#addStartingItem');await p.locator('#inventoryName').fill('Starting item '+i);if(i===0)await chooseGearFields(p,'inventory',{type:'weapon',modifier:1});await click(p,'#inventoryItemConfirm')}assert.equal(await p.locator('#addStartingItem').isDisabled(),true);await click(p,'#setupCards [data-card="H1"]');assert.match(await p.locator('#startingItems').innerText(),/Starting Item 7/);await click(p,'#startGame');const s=await p.evaluate(STORE=>JSON.parse(localStorage.getItem(STORE)).slots[0].state,STORE);assert.equal(s.inventory.length,8);assert.equal(s.inventory[0].equipment.type,'weapon');assert.equal(s.equipment.weapon.name,'Starting Weapon');assert.equal(s.equipment.armor.name,'Starting Armor');assert.deepEqual(s.equipment.weapon.equipment.usage,[true,true,true,true]);assert.equal(s.res.Coin,8);assert.equal(s.upgradePoints,49);invariant(s);});
test('192 creation item drafts support edit/remove/cancel and reset on the next character',async p=>{await click(p,'#createCharacter');await click(p,'#addStartingItem');await p.locator('#inventoryName').fill('Cancelled');await click(p,'#inventoryModalCancel');assert.equal(await p.locator('[data-edit-start-item]').count(),0);await click(p,'#addStartingItem');await p.locator('#inventoryName').fill('Rope');await click(p,'#inventoryItemConfirm');await click(p,'[data-edit-start-item="0"]');await p.locator('#inventoryName').fill('Long rope');await click(p,'#inventoryItemConfirm');assert.match(await p.locator('#startingItems').innerText(),/Long Rope/);await click(p,'[data-remove-start-item="0"]');assert.equal(await p.locator('[data-edit-start-item]').count(),0);await click(p,'[data-start-equipment="weapon"]');await p.locator('#inventoryName').fill('Sword');await p.locator('#inventoryEquipmentModifier').fill('2');await click(p,'#inventoryItemConfirm');await click(p,'#newGameTop');await click(p,'#createCharacter');assert.doesNotMatch(await p.locator('#startingItems').innerText(),/Sword|Long rope/);});
test('193 custom enemy reward equipment fields are required and the accepted reward can be equipped with preserved condition',async p=>{await load(p);await random(p);await beginCustomCombat(p);await p.locator('#combatDifficulty').fill('4');await p.locator('#enemyHasItem').check();await p.locator('#enemyItemName').fill('Reward sword');await p.locator('#enemyItemIsEquipment').check();await click(p,'#startCombat');assert.equal((await read(p)).combat,null);assert.ok((await p.locator('#enemySetupError').innerText()).length>0);await p.locator('#enemyItemEquipmentType').selectOption('weapon');await p.locator('#enemyItemEquipmentModifier').fill('3');await click(p,'#startCombat');await pick(p,['C5']);await click(p,'#combatCommit');await p.locator('#combatResolve').click();assert.equal((await read(p)).inventory.length,0);await click(p,'#rewardKeep');await click(p,'#inventoryToggle');assert.equal((await read(p)).inventory[0].equipment.modifier,3);await click(p,'[data-equip-item="0"]');assert.equal((await read(p)).equipment.weapon.equipment.usage.filter(Boolean).length,4);});
test('194 library build/schema and template support equipment rewards without inventing stats for existing enemies',async(p,ctx,browser)=>{const rules=require('../scripts/enemy-library-v27.cjs');assert.equal(actualLibrary.version,5);const template=rules.validateEnemyLibrary(JSON.parse(fs.readFileSync(path.join(ROOT,'data/enemies.template.json'),'utf8')));assert.equal(template.enemies[1].Item.equipment.type,'weapon');assert.equal(actualLibrary.enemies.find(e=>e.name==='Thief').Item.equipment,undefined);const data=structuredClone(actualLibrary);data.enemies.find(e=>e.name==='Thief').Item=gear('Library sword','weapon',3,2,false);const built=buildTestLibrary(data);let c;try{assert.equal(built.result.status,0,built.result.stderr);c=await browser.newContext();const q=await c.newPage();q.setDefaultTimeout(10000);await q.route('**/*',r=>r.fulfill({status:200,contentType:'text/html',body:fs.readFileSync(built.output)}));await q.goto('http://gear-library.local');await load(q);await random(q);await selectLibraryEnemy(q,'Thief');assert.match(await q.locator('#activeEnemyInfo').innerText(),/Weapon · Modifier \+3 · Usage 2\/4 · Active/);await pick(q,['C5','D6']);await click(q,'#combatCommit');await q.locator('#combatResolve').click();await click(q,'#rewardKeep');assert.deepEqual((await read(q)).inventory[0],data.enemies.find(e=>e.name==='Thief').Item);await action(q,'combat');await click(q,'#chooseLibraryEnemy');await q.locator('input[value="Thief"]').check();assert.match(await q.locator('#libraryEnemyPreview').innerText(),/Usage 2\/4/)}finally{if(c)await c.close();built.cleanup()}});
test('195 malformed equipment and mismatched equipped slots are rejected on import without overwriting saves',async p=>{await seed(p);const before=await read(p);for(const modify of [e=>e.type='bow',e=>e.modifier=0,e=>e.modifier=1.5,e=>e.modifier=Number.MAX_SAFE_INTEGER,e=>e.usage=[true,true,true],e=>e.usage=[1,true,true,true],e=>e.usage=null]){const item=gear();modify(item.equipment);await importData(p,fixture({inventory:[item]}));assert.match(await p.locator('#status').innerText(),/Import failed/);assert.deepEqual(await read(p),before)}await importData(p,fixture({equipment:{weapon:gear('Plate','armor'),armor:null}}));assert.match(await p.locator('#status').innerText(),/Import failed/);assert.deepEqual(await read(p),before);});
test('196 V22 saves migrate to empty equipment slots without guessing item types and new exact combat saves resume with weapon bonus',async p=>{const old=fixture({inventory:[{name:'A dagger',description:'A dagger',keywords:['weapon'],baseValue:5}]});delete old.equipment;await seed(p);await importData(p,old);let id=await p.locator('[data-continue]').last().getAttribute('data-continue');assert.deepEqual((await read(p,id)).equipment,{weapon:null,armor:null});assert.equal((await read(p,id)).inventory[0].equipment,undefined);await load(p,fixture({equipment:{weapon:gear(),armor:null}}));await random(p);await combat(p,['H3'],5);await p.locator('#combatResolve').click();await p.reload();await click(p,'[data-continue="one"]');assert.equal((await read(p)).combat.stage,'exact');});
test('197 repairs are locked during combat and Cancel restores committed wear, cards and resources',async p=>{await load(p,fixture({equipment:{weapon:gear('Sword','weapon',1,1),armor:null}}));const before=await read(p);await random(p);await combat(p,['H1'],30,0);await p.locator('#combatResolve').click();await showGear(p);assert.equal(await p.locator('[data-fix-equipment="weapon"]').isDisabled(),true);await click(p,'#cancelEncounter');assert.deepEqual(await read(p),before);});
test('198 equipment panel/forms and Fix dialog remain usable at 320px with keyboard focus trapping',async(p,ctx,browser)=>{const c=await browser.newContext({viewport:{width:320,height:844},isMobile:true,hasTouch:true});try{const q=await c.newPage();q.setDefaultTimeout(10000);await q.goto(p.url());await load(q,fixture({equipment:{weapon:gear('A very long sword name '.repeat(6),'weapon',2,0),armor:gear('Mail','armor',2)}}));await showGear(q);assert.ok(await q.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await q.locator('#equipmentBody').screenshot({path:path.join(OUT,'v27-equipment-mobile.png')});await click(q,'[data-fix-equipment="weapon"]');await q.keyboard.press('Shift+Tab');assert.equal(await q.locator(':focus').getAttribute('id'),'repairConfirm');await q.keyboard.press('Escape');await click(q,'[data-edit-equipment="armor"]');assert.equal(await q.locator('#inventoryEquipmentType').inputValue(),'armor');assert.ok(await q.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await q.screenshot({path:path.join(OUT,'v27-equipment-form-mobile.png')});}finally{await c.close()}});
test('199 equipment combat, breakage and repair work offline with saved effects',async(p,ctx,browser)=>{const c=await browser.newContext({offline:true});try{const q=await c.newPage();q.setDefaultTimeout(10000);await c.route('**/*',r=>r.fulfill({status:200,contentType:'text/html',body:fs.readFileSync(APP_FILE)}));await q.goto(new URL(p.url()).origin);await load(q,fixture({equipment:{weapon:gear('Sword','weapon',1,1),armor:gear('Plate','armor',3,1)}}));await random(q);await combat(q,['H1'],30,2);await q.locator('#combatResolve').click();assert.equal((await read(q)).combat.stage,'afterFail');assert.equal((await read(q)).equipment.weapon.equipment.usage.some(Boolean),false);await click(q,'#combatFlee');await showGear(q);await click(q,'[data-fix-equipment="weapon"]');await q.locator('#repairCost').fill('2');await click(q,'#repairConfirm');await q.reload();await click(q,'[data-continue="one"]');assert.equal((await read(q)).equipment.weapon.equipment.usage.filter(Boolean).length,4);assert.equal((await read(q)).res.Coin,6);invariant(await read(q));}finally{await c.close()}});
test('200 wearing/reward item copies are independent of library/other item durability arrays',async()=>{const {copyItem,normalizeItem}=require('../scripts/enemy-library-v27.cjs'),source=gear(),a=copyItem(source),b=copyItem(source);a.equipment.usage[0]=false;a.keywords.push('changed');assert.deepEqual(source.equipment.usage,[true,true,true,true]);assert.deepEqual(b.equipment.usage,[true,true,true,true]);assert.deepEqual(source.keywords,['weapon']);const ordinary=normalizeItem({name:'Rope',keywords:[],baseValue:1,equipment:null});assert.equal(ordinary.equipment,undefined);});

test('201 editing gear preserves condition and cannot repair it; inventory can explicitly reclassify equipment as an ordinary item',async p=>{const broken=gear('Broken sword','weapon',2,0);await load(p,fixture({inventory:[gear('Spare','armor',2,2,false)],equipment:{weapon:broken,armor:null}}));await showGear(p);await click(p,'[data-edit-equipment="weapon"]');await p.locator('#inventoryName').fill('Renamed broken sword');await p.locator('#inventoryEquipmentModifier').fill('3');await click(p,'#inventoryItemConfirm');assert.deepEqual((await read(p)).equipment.weapon.equipment.usage,[false,false,false,false]);assert.equal((await read(p)).equipment.weapon.equipment.usage.some(Boolean),false);await click(p,'#inventoryToggle');await click(p,'[data-edit-item="0"]');await p.locator('#inventoryName').fill('Edited spare');await click(p,'#inventoryItemConfirm');assert.equal((await read(p)).inventory[0].equipment.usage.filter(Boolean).length,2);assert.equal((await read(p)).inventory[0].equipment.usage.some(Boolean),true);await click(p,'[data-edit-item="0"]');await p.locator('#inventoryIsEquipment').uncheck();await click(p,'#inventoryItemConfirm');assert.equal((await read(p)).inventory[0].equipment,undefined);});
test('202 equipment is automatic with available points and is locked throughout combat decisions',async p=>{await load(p,fixture({equipment:{weapon:gear('Sword','weapon',10),armor:gear('Plate','armor',2)}}));await random(p);await combat(p,['H1'],5,3);assert.match(await p.locator('#operation').innerText(),/Action Hand 11 · Success/);await showGear(p);assert.equal(await p.locator('[data-edit-equipment="weapon"]').isDisabled(),true);assert.equal(await p.locator('[data-unequip="weapon"]').isDisabled(),true);await p.locator('#combatResolve').click();assert.equal((await read(p)).combat,null);});
test('203 equipment reward replacement at full inventory preserves the reward condition and does not auto-equip it',async p=>{const item=gear('Reward armor','armor',3,2,false);await load(p,fixture({inventory:inventoryEight(),equipment:{weapon:gear(),armor:gear('Current armor','armor',1)}}));await random(p);await beginCustomCombat(p);await p.locator('#combatDifficulty').fill('4');await p.locator('#enemyHasItem').check();await p.locator('#enemyItemName').fill(item.name);await chooseGearFields(p,'enemyItem',{type:'armor',modifier:3});await click(p,'#startCombat');await pick(p,['C5']);await click(p,'#combatCommit');await p.locator('#combatResolve').click();await click(p,'#rewardKeep');await p.locator('input[name="rewardDiscard"][value="3"]').check();await click(p,'#rewardReplaceConfirm');const s=await read(p);assert.equal(s.inventory.length,8);assert.equal(s.inventory[3].equipment.type,'armor');assert.deepEqual(s.inventory[3].equipment.usage,[true,true,true,true]);assert.equal(s.equipment.armor.name,'Current armor');await click(p,'#inventoryToggle');await click(p,'[data-equip-item="3"]');assert.equal((await read(p)).equipment.armor.name,'Reward Armor');assert.equal((await read(p)).inventory[3].name,'Current armor');});
test('204 paid gear purchase and sale retain equipment metadata and transaction Undo',async p=>{await load(p);await click(p,'#inventoryToggle');await click(p,'#inventoryAdd');await p.locator('#inventoryName').fill('Bought sword');await chooseGearFields(p,'inventory',{type:'weapon',modifier:2});await p.locator('#inventoryPurchased').check();await p.locator('#inventoryPurchasePrice').fill('2');await click(p,'#inventoryItemConfirm');assert.equal((await read(p)).res.Coin,6);const bought=(await read(p)).inventory[0];await click(p,'[data-remove-item="0"]');await p.locator('#inventorySold').check();await p.locator('#inventorySalePrice').fill('5');await click(p,'#inventoryRemoveConfirm');assert.equal((await read(p)).res.Coin,11);await click(p,'#undo');assert.equal((await read(p)).res.Coin,6);assert.deepEqual((await read(p)).inventory[0],bought);});
test('205 Undo of failed resolution restores cards, both equipment usage counts and the pre-resolution decision',async p=>{await load(p,fixture({equipment:{weapon:gear('Sword','weapon',1),armor:gear('Plate','armor',2)}}));await random(p);await combat(p,['H1'],30,3);const before=await read(p);await p.locator('#combatResolve').click();assert.equal((await read(p)).woundTask.value,1);await click(p,'#undo');assert.deepEqual(await read(p),before);assert.equal((await read(p)).combat.stage,'decide');assert.equal((await read(p)).equipment.weapon.equipment.usage.filter(Boolean).length,4);});

// V24: automatic equipment, standard associations, keyword catalog and healing filter.
function withWords(item,keywords){return {...item,keywords}}
async function keywordFight(p,{enemyWords=[],weaponWords=[],armorWords=[],base=16,woundValue=4,weaponPoints=4,armorPoints=4}={}){await load(p,fixture({equipment:{weapon:withWords(gear('Sword','weapon',1,weaponPoints),weaponWords),armor:withWords(gear('Mail','armor',1,armorPoints),armorWords)}}));await random(p);await defineEnemy(p,{name:'Keyword foe',keywords:enemyWords,base,woundValue});}
async function assertCombatLocked(p){await showGear(p);for(const selector of ['[data-edit-equipment="weapon"]','[data-unequip="weapon"]'])assert.equal(await p.locator(selector).isDisabled(),true);if(await p.locator('#inventoryToggle').getAttribute('aria-expanded')==='false')await click(p,'#inventoryToggle');for(const selector of ['#inventoryAdd','[data-edit-item="0"]','[data-remove-item="0"]','[data-equip-item="0"]'])assert.equal(await p.locator(selector).isDisabled(),true);}

test('206 comma rejection and hyphen/space rules apply to generic, weapon, armor and starting-item keyword entry',async p=>{await load(p);await click(p,'#inventoryToggle');for(const type of ['generic','weapon','armor']){await click(p,'#inventoryAdd');await p.locator('#inventoryName').fill('Test '+type);if(type!=='generic')await chooseGearFields(p,'inventory',{type,modifier:1});await p.locator('#inventoryKeywords').fill('metal, magical');await click(p,'#inventoryItemConfirm');assert.match(await p.locator('#inventoryKeywordTip').innerText(),/Commas are not allowed/);assert.equal((await read(p)).inventory.length,0);await p.locator('#inventoryKeywords').fill('Full Body - metal');await click(p,'#inventoryItemConfirm');assert.deepEqual((await read(p)).inventory[0].keywords,['Full Body','metal']);await click(p,'[data-remove-item="0"]');await click(p,'#inventoryRemoveConfirm')}await click(p,'#newGameTop');await click(p,'#createCharacter');await click(p,'#addStartingItem');await p.locator('#inventoryName').fill('Starting item');await p.locator('#inventoryKeywords').fill('heal, rest');await click(p,'#inventoryItemConfirm');assert.equal(await p.locator('#inventoryModal').isVisible(),true);assert.match(await p.locator('#inventoryError').innerText(),/Commas/);});
test('207 legacy enabled flags are discarded; remaining usage automatically activates equipment and old commas migrate out',async p=>{const item=gear('Legacy sword');item.equipment.enabled=false;item.keywords=['metal, magical'];const old=fixture({equipment:{weapon:item,armor:null},inventory:[{name:'Old item',description:'',keywords:'heal, rest - Full Body',baseValue:1}]});await load(p,old);await click(p,'#newGameTop');const migrated=await read(p);assert.equal(migrated.equipment.weapon.equipment.enabled,undefined);assert.deepEqual(migrated.equipment.weapon.keywords,['metal','magical']);assert.deepEqual(migrated.inventory[0].keywords,['heal','rest','Full Body']);await click(p,'[data-continue="one"]');await random(p);await combat(p,['H3'],4);assert.match(await p.locator('#operation').innerText(),/Action Hand 5 · Success/);});
test('208 usage indicators are noninteractive, Edit is small at top right, and Fix sits beside Move to inventory',async p=>{await load(p,fixture({equipment:{weapon:gear('Broken sword','weapon',1,0),armor:gear('Mail','armor',2,2)}}));const before=await read(p);await showGear(p);assert.equal(await p.locator('.equipment-usage input,.equipment-enabled,[data-equipment-enable]').count(),0);assert.equal(await p.locator('[data-equipment-slot="armor"] .usage-point.available').count(),2);assert.equal(await p.locator('[data-equipment-slot="armor"] .usage-point.spent').count(),2);for(const [selector,color]of [['.usage-point.available','rgb(165, 42, 42)'],['.usage-point.spent','rgb(170, 166, 161)']])assert.equal(await p.locator(selector).first().evaluate(e=>getComputedStyle(e).backgroundColor),color);await p.locator('.usage-point.available').first().click();assert.deepEqual(await read(p),before);const header=await p.locator('[data-equipment-slot="weapon"] h3').boundingBox(),edit=await p.locator('[data-edit-equipment="weapon"]').boundingBox(),move=await p.locator('[data-unequip="weapon"]').boundingBox(),fix=await p.locator('[data-fix-equipment="weapon"]').boundingBox();assert.ok(edit.x>header.x);assert.ok(edit.height<=34);assert.ok(Math.abs(move.y-fix.y)<2);assert.ok(fix.x>move.x);});
test('209 all ordinary inventory/equipment edits and moves remain locked from combat choose through failure/retry',async p=>{await load(p,fixture({inventory:[gear('Spare')],equipment:{weapon:gear(),armor:null}}));await random(p);await defineEnemy(p,{base:30,woundValue:0});await assertCombatLocked(p);await pick(p,['H1']);await click(p,'#combatCommit');await assertCombatLocked(p);await click(p,'#combatAdd');await assertCombatLocked(p);await click(p,'#combatBack');await p.locator('#combatResolve').click();assert.equal((await read(p)).combat.stage,'afterFail');await assertCombatLocked(p);await click(p,'#combatRetry');await assertCombatLocked(p);await click(p,'#cancelEncounter');assert.equal(await p.locator('[data-edit-equipment="weapon"]').isDisabled(),false);assert.equal(await p.locator('#inventoryAdd').isDisabled(),false);});
test('210 dedicated reward acceptance and replacement remain available while ordinary inventory is locked',async p=>{await winPendingItem(p,{full:true});assert.equal(await p.locator('#inventoryAdd').isDisabled(),true);await click(p,'#rewardKeep');await p.locator('input[name="rewardDiscard"][value="2"]').check();await click(p,'#rewardReplaceConfirm');assert.equal((await read(p)).inventory[2].name,'Healing Potion');assert.equal((await read(p)).combat,null);});
test('211 stale inventory editor confirmation cannot modify an item after combat has begun',async p=>{await load(p,fixture({inventory:[gear('Original')]}));await click(p,'#inventoryToggle');await click(p,'[data-edit-item="0"]');await p.locator('#inventoryName').fill('Stale change');await p.locator('[data-mode="combat"]').evaluate(e=>e.click());await p.locator('#chooseCreateEnemy').evaluate(e=>e.click());await click(p,'#startCombat');assert.equal(await p.locator('#inventoryModal').isVisible(),false);await p.locator('#inventoryItemConfirm').evaluate(e=>e.click());assert.equal((await read(p)).inventory[0].name,'Original');});
test('212 Cube example uses resistant +6 CV and strong +2 WV, then applies armor reduction to actual wounds',async p=>{await keywordFight(p,{enemyWords:['Resistant against slash','Strong against metal'],weaponWords:['metal','melee','slash'],armorWords:['metal']});assert.match(await p.locator('#activeEnemyInfo').innerText(),/Challenge Value 22/);assert.match(await p.locator('#activeEnemyInfo').innerText(),/Wound Value 6/);assert.match(await p.locator('#activeEnemyInfo').innerText(),/CV \+6/);assert.match(await p.locator('#operation').innerText(),/Wound on failure: 5/);await pick(p,['H1']);await click(p,'#combatCommit');await p.locator('#combatResolve').click();assert.equal((await read(p)).woundTask.value,5);assert.equal((await read(p)).combat.lastWound,5);assert.equal((await read(p)).equipment.armor.equipment.usage.filter(Boolean).length,3);});
test('213 keyword matching is whole-word, case-insensitive and supports old abbreviated association text',async p=>{await keywordFight(p,{enemyWords:['Unprotected fire','resistant against SLASH'],weaponWords:['Fireball','Slashing']});assert.match(await p.locator('#activeEnemyInfo').innerText(),/Challenge Value 16/);await click(p,'#cancelEncounter');await keywordFight(p,{enemyWords:['Unprotected fire','resistant against SLASH'],weaponWords:[' FIRE ','Slash']});assert.match(await p.locator('#activeEnemyInfo').innerText(),/Challenge Value 16/);assert.match(await p.locator('#activeEnemyInfo').innerText(),/CV -6/);assert.match(await p.locator('#activeEnemyInfo').innerText(),/CV \+6/);});
test('214 duplicate associations apply once while distinct matching effects stack and opposite effects offset',async p=>{await keywordFight(p,{enemyWords:['Resistant against slash','RESISTANT slash','Resistant against metal','Unprotected against fire','Strong against metal','Weak against holy','Strong against Full Body'],weaponWords:['slash','metal','fire'],armorWords:['metal','holy','Full Body']});assert.match(await p.locator('#activeEnemyInfo').innerText(),/Challenge Value 22/);assert.match(await p.locator('#activeEnemyInfo').innerText(),/Wound Value 6/);assert.equal(await p.locator('.keyword-effects').evaluate(e=>(e.innerText.match(/CV \+6/g)||[]).length),2);});
test('215 vulnerability/weakness floors CV at one and WV at zero before normal modifier and armor resolution',async p=>{await keywordFight(p,{enemyWords:['Unprotected against fire','Weak against metal'],weaponWords:['fire'],armorWords:['metal'],base:3,woundValue:1});assert.match(await p.locator('#activeEnemyInfo').innerText(),/Challenge Value 1/);assert.match(await p.locator('#activeEnemyInfo').innerText(),/Wound Value 0/);await random(p,.01);await pick(p,['H1']);await click(p,'#combatCommit');assert.match(await p.locator('#operation').innerText(),/Final challenge 1/);await p.locator('#combatResolve').click();assert.equal((await read(p)).combat,null);});
test('216 broken gear loses keyword associations next retry while the already-resolved increased wound survives reload',async p=>{await keywordFight(p,{enemyWords:['Resistant against slash','Strong against metal'],weaponWords:['slash'],armorWords:['metal'],weaponPoints:1,armorPoints:1});await pick(p,['C5']);await click(p,'#combatCommit');await p.locator('#combatResolve').click();assert.equal((await read(p)).woundTask.value,5);await p.reload();await click(p,'[data-continue="one"]');assert.equal((await read(p)).woundTask.value,5);assert.match(await p.locator('#activeEnemyInfo').innerText(),/Challenge Value 22/);assert.match(await p.locator('#activeEnemyInfo').innerText(),/Wound Value 6/);await pick(p,['C5']);await click(p,'#woundNext');await click(p,'#combatRetry');assert.match(await p.locator('#operation').innerText(),/Base challenge 14 · Wound value 4/);assert.match(await p.locator('#operation').innerText(),/Weapon bonus: \+0 · Armor reduction: 0/);});
test('217 armor loses one usage when weakness prevents wounds even if its flat modifier is no longer needed',async p=>{await keywordFight(p,{enemyWords:['Weak against metal'],armorWords:['metal'],base:30,woundValue:2});await pick(p,['H1']);await click(p,'#combatCommit');await p.locator('#combatResolve').click();const s=await read(p);assert.equal(s.combat.stage,'afterFail');assert.equal(s.woundTask,null);assert.deepEqual(s.zones.wound,[]);assert.equal(s.equipment.armor.equipment.usage.filter(Boolean).length,3);});
test('218 custom prose and unrelated enemy keywords are displayed without inventing automatic modifiers',async p=>{await keywordFight(p,{enemyWords:['Special rule','resistant against slashing'],weaponWords:['slash']});assert.match(await p.locator('#activeEnemyInfo').innerText(),/Challenge Value 16/);assert.match(await p.locator('#activeEnemyInfo').innerText(),/No matching keyword effects/);});
test('219 enemy validation reserves safe numeric room for keyword CV/WV increases',async()=>{const {validateEnemyLibrary}=require('../scripts/enemy-library-v27.cjs');for(const modify of [e=>{e.CV=Number.MAX_SAFE_INTEGER-6;e.KW=['Resistant against slash']},e=>{e.WV=Number.MAX_SAFE_INTEGER;e.KW=['Strong against metal']}]){const data=structuredClone(actualLibrary);modify(data.enemies[0]);assert.throws(()=>validateEnemyLibrary(data))}});
test('220 Heal picker accepts only exact heal keyword, case-insensitively, and consumes the correct original inventory index',async p=>{const inventory=[{name:'Rest item',description:'',keywords:['rest'],baseValue:1},{name:'Healing word',description:'',keywords:['healing'],baseValue:1},{name:'Potion',description:'',keywords:['HeAl'],baseValue:1},{name:'Phrase',description:'',keywords:['heal potion'],baseValue:1}];await load(p,fixture({inventory,zones:{deck:['H3'],hand:[],fatigue:[],wound:['H1']}}));await action(p,'heal');await click(p,'#useHealItem');assert.equal(await p.locator('input[name="healItem"]').count(),1);assert.equal(await p.locator('input[name="healItem"]').inputValue(),'2');await p.locator('input[name="healItem"]').check();await click(p,'#healItemSelect');await pick(p,['H1']);await click(p,'#commit');assert.deepEqual((await read(p)).inventory.map(i=>i.name),['Rest item','Healing word','Phrase']);});
test('221 a nonempty inventory with no heal keyword gives a recoverable picker message without allowing an item',async p=>{await load(p,fixture({inventory:[{name:'Rest item',description:'',keywords:['rest'],baseValue:1}]}));const before=await read(p);await action(p,'heal');await click(p,'#useHealItem');assert.match(await p.locator('#healItemChoices').innerText(),/No items with the heal keyword/);assert.equal(await p.locator('#healItemSelect').isDisabled(),true);await click(p,'#healItemCancel');assert.deepEqual(await read(p),before);});
test('222 removing the heal keyword from a selected item invalidates consumption without losing the item',async p=>{await load(p,fixture({inventory:[{name:'Potion',description:'',keywords:['heal'],baseValue:1}],zones:{deck:['H3'],hand:[],fatigue:[],wound:['H1']}}));await action(p,'heal');await selectHealingItem(p);await click(p,'#inventoryToggle');await click(p,'[data-edit-item="0"]');await p.locator('#inventoryKeywords').fill('rest');await click(p,'#inventoryItemConfirm');assert.equal(await p.locator('#useHealItem').count(),1);assert.equal(await p.locator('#healItemNotice').count(),0);await pick(p,['H1']);await click(p,'#commit');assert.equal((await read(p)).inventory.length,1);});
test('223 keyword catalog contains the exact supplied groups and uses without dice metadata',async()=>{const {validateKeywordCatalog}=require('../scripts/enemy-library-v27.cjs'),data=validateKeywordCatalog(JSON.parse(fs.readFileSync(path.join(ROOT,'data/keywords.json'),'utf8')));assert.equal(data.keywords.length,36);const entry=word=>data.keywords.find(e=>e.keyword===word);assert.deepEqual(entry('melee').uses,['weapon']);assert.deepEqual(entry('leather').uses,['armor']);assert.deepEqual(entry('metal').uses,['weapon','armor','generic']);assert.deepEqual(entry('glass').uses,['weapon','generic']);assert.deepEqual(entry('Full Body').uses,['armor']);assert.deepEqual(entry('heal').uses,['generic']);assert.deepEqual(entry('rest').uses,['generic']);assert.equal(entry('cristal').category,'Material');assert.equal(JSON.stringify(data).includes('d6'),false);});
test('224 suggestions append with hyphens, avoid duplicates and preserve arbitrary custom keyword phrases',async p=>{await load(p);await click(p,'#inventoryToggle');await click(p,'#inventoryAdd');await p.locator('#inventoryKeywords').fill('my custom phrase');await click(p,'#inventorySuggestions [data-suggest-keyword="wood"]');assert.equal(await p.locator('#inventoryKeywords').inputValue(),'my custom phrase - wood');await click(p,'#inventorySuggestions [data-suggest-keyword="wood"]');assert.equal(await p.locator('#inventoryKeywords').inputValue(),'my custom phrase');assert.equal(await p.locator('#inventorySuggestions [data-suggest-keyword="wood"]').getAttribute('aria-pressed'),'false');await click(p,'#inventorySuggestions [data-suggest-keyword="wood"]');assert.equal(await p.locator('#inventorySuggestions [data-suggest-keyword="heal"]').count(),1);await chooseGearFields(p,'inventory',{type:'weapon',modifier:1});assert.equal(await p.locator('#inventorySuggestions [data-suggest-keyword="heal"]').count(),0);assert.equal(await p.locator('#inventorySuggestions [data-suggest-keyword="slash"]').count(),1);await p.locator('#inventoryEquipmentType').selectOption('armor');assert.equal(await p.locator('#inventorySuggestions [data-suggest-keyword="slash"]').count(),0);assert.equal(await p.locator('#inventorySuggestions [data-suggest-keyword="Full Body"]').count(),1);assert.equal(await p.locator('#inventoryKeywords').inputValue(),'my custom phrase - wood');});
test('225 suggestions work in starting/equipped/reward forms and cannot silently truncate content beyond the text budget',async p=>{await click(p,'#createCharacter');await click(p,'[data-start-equipment="armor"]');assert.equal(await p.locator('#inventorySuggestions [data-suggest-keyword="leather"]').count(),1);await p.locator('#inventoryDescription').fill('x'.repeat(298));await click(p,'#inventorySuggestions [data-suggest-keyword="metal"]');assert.equal(await p.locator('#inventoryKeywords').inputValue(),'');assert.match(await p.locator('#inventoryKeywordTip').innerText(),/exceed/);await click(p,'#inventoryModalCancel');await click(p,'#newGameTop');await load(p);await beginCustomCombat(p);await p.locator('#enemyHasItem').check();await chooseGearFields(p,'enemyItem',{type:'weapon',modifier:1});assert.equal(await p.locator('#enemyItemSuggestions [data-suggest-keyword="slash"]').count(),1);await click(p,'#enemyItemSuggestions [data-suggest-keyword="slash"]');assert.equal(await p.locator('#enemyItemKeywords').inputValue(),'slash');});
test('226 invalid keyword catalogs fail the build before writing outputs',async()=>{const dir=fs.mkdtempSync(path.join(os.tmpdir(),'qfg-catalog-')),file=path.join(dir,'bad.json'),output=path.join(dir,'app.html');try{fs.writeFileSync(file,JSON.stringify({format:'quest-for-glory-keywords',version:1,keywords:[{keyword:'heal, rest',category:'Effect',uses:['generic']}]}));const result=spawnSync(process.execPath,[path.join(ROOT,'scripts/build-v27.cjs'),'--keywords',file,'--output',output],{encoding:'utf8'});assert.notEqual(result.status,0);assert.equal(fs.existsSync(output),false)}finally{fs.rmSync(dir,{recursive:true,force:true})}});
test('227 Card Zones colors are derived from nonempty Wounds/Fatigue and update after healing/rest/Undo',async p=>{await load(p,fixture({zones:{deck:['H3'],hand:[],fatigue:['H1'],wound:['H2']}}));const zone=z=>p.locator(`[data-viewzone="${z}"]`);assert.equal(await zone('fatigue').evaluate(e=>getComputedStyle(e).backgroundColor),'rgb(212, 223, 227)');assert.equal(await zone('wound').evaluate(e=>getComputedStyle(e).backgroundColor),'rgb(237, 198, 194)');await zone('wound').hover();assert.equal(await zone('wound').evaluate(e=>getComputedStyle(e).backgroundColor),'rgb(237, 198, 194)');await action(p,'heal');await pick(p,['H2']);await click(p,'#commit');assert.equal(await zone('wound').evaluate(e=>e.classList.contains('zone-wounded')),false);await click(p,'#undo');assert.equal(await zone('wound').evaluate(e=>e.classList.contains('zone-wounded')),true);await action(p,'rest');await pick(p,['H1']);await click(p,'#commit');assert.equal(await zone('fatigue').evaluate(e=>e.classList.contains('zone-fatigued')),false);assert.doesNotMatch(await p.locator('#resourcesPanel').innerText(),/Tap a total to adjust/);});
test('228 keyword effects, tips and durability work offline without fetching data files',async(p,ctx,browser)=>{const c=await browser.newContext({offline:true});try{const q=await c.newPage(),origin=new URL(p.url()).origin,external=[];q.setDefaultTimeout(10000);await c.route('**/*',r=>{if(new URL(r.request().url()).origin!==origin){external.push(r.request().url());return r.abort()}return r.fulfill({status:200,contentType:'text/html',body:fs.readFileSync(APP_FILE)})});await q.goto(origin);await load(q,fixture({equipment:{weapon:withWords(gear(),['slash']),armor:null}}));await random(q);await selectLibraryEnemy(q,'Skeleton');assert.match(await q.locator('#activeEnemyInfo').innerText(),/Challenge Value 14/);await pick(q,['H1']);await click(q,'#combatCommit');await q.locator('#combatResolve').click();assert.equal((await read(q)).equipment.weapon.equipment.usage.filter(Boolean).length,3);await click(q,'#cancelEncounter');await click(q,'#inventoryToggle');await click(q,'#inventoryAdd');assert.equal(await q.locator('#inventorySuggestions [data-suggest-keyword="heal"]').count(),1);assert.deepEqual(external,[]);}finally{await c.close()}});
test('229 keyword suggestions and read-only gear layout remain usable on 320px screens',async(p,ctx,browser)=>{const c=await browser.newContext({viewport:{width:320,height:844},isMobile:true,hasTouch:true});try{const q=await c.newPage();q.setDefaultTimeout(10000);await q.goto(p.url());await load(q,fixture({equipment:{weapon:gear('Broken sword','weapon',1,0),armor:gear('Mail','armor',2,2)}}));await showGear(q);assert.ok(await q.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await q.locator('#equipmentBody').screenshot({path:path.join(OUT,'v27-equipment-mobile.png')});await click(q,'#inventoryToggle');await click(q,'#inventoryAdd');await chooseGearFields(q,'inventory',{type:'weapon',modifier:1});await click(q,'#inventorySuggestions [data-suggest-keyword="slash"]');assert.equal(await q.locator('#inventoryKeywords').inputValue(),'slash');assert.ok(await q.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await q.screenshot({path:path.join(OUT,'v27-keyword-tips-mobile.png')});}finally{await c.close()}});
test('230 unavailable embedded suggestions fall back to custom text without blocking the item editor',async(p,ctx,browser)=>{const html=fs.readFileSync(APP_FILE,'utf8').replace(/<script id="keywordCatalogData" type="application\/json">[\s\S]*?<\/script>/,'<script id="keywordCatalogData" type="application/json">{}</script>'),c=await browser.newContext();try{const q=await c.newPage();q.setDefaultTimeout(10000);await q.route('**/*',r=>r.fulfill({status:200,contentType:'text/html',body:html}));await q.goto('http://no-tips.local');await load(q);await click(q,'#inventoryToggle');await click(q,'#inventoryAdd');assert.match(await q.locator('#inventorySuggestions').innerText(),/still type custom keywords/);await q.locator('#inventoryName').fill('Custom');await q.locator('#inventoryKeywords').fill('custom phrase');await click(q,'#inventoryItemConfirm');assert.deepEqual((await read(q)).inventory[0].keywords,['custom phrase']);}finally{await c.close()}});

// V25 focused behavior.
function effortFixture(combatMode=false,{fate=8,base=1,wv=0,fatigue=['H1','H2','C5'],wound=['S4'],equipment={weapon:null,armor:null}}={}){const encounter={base,modifier:null,stage:'choose',adjusted:false};return fixture({res:{Coin:8,Fate:fate,Supply:2},equipment,zones:{deck:[],hand:[],fatigue,wound},...(combatMode?{combat:{...encounter,attempt:0,wound:wv}}:{challenge:{...encounter,allowed:['H','S','C','D']}})})}
async function confirmEffort(p,combatMode,ids){await random(p);await pick(p,ids);await click(p,combatMode?'#combatCommit':'#commitChallenge')}

test('231 suggestion chips toggle add/remove case-insensitively without changing unrelated keywords',async p=>{await load(p);await click(p,'#inventoryToggle');await click(p,'#inventoryAdd');await p.locator('#inventoryKeywords').fill('METAL - custom phrase');await click(p,'#inventorySuggestions [data-suggest-keyword="metal"]');assert.equal(await p.locator('#inventoryKeywords').inputValue(),'custom phrase');assert.equal(await p.locator('#inventorySuggestions [data-suggest-keyword="metal"]').getAttribute('aria-pressed'),'false');await click(p,'#inventorySuggestions [data-suggest-keyword="metal"]');assert.equal(await p.locator('#inventoryKeywords').inputValue(),'custom phrase - metal');});
test('232 manually confirmed keywords become character Custom toggles and remain after removal and Undo',async p=>{await load(p);await click(p,'#inventoryToggle');await click(p,'#inventoryAdd');await p.locator('#inventoryName').fill('Moon charm');await p.locator('#inventoryKeywords').fill('moon silver - custom phrase');await click(p,'#inventoryItemConfirm');assert.deepEqual((await read(p)).customKeywords,[{keyword:'moon silver',category:'custom',origin:'custom'},{keyword:'custom phrase',category:'custom',origin:'custom'}]);await click(p,'[data-edit-item="0"]');assert.match(await p.locator('#inventorySuggestions').innerText(),/Custom/);await click(p,'#inventorySuggestions [data-suggest-keyword="moon silver"]');await click(p,'#inventoryItemConfirm');assert.deepEqual((await read(p)).inventory[0].keywords,['custom phrase']);assert.equal((await read(p)).customKeywords.length,2);await click(p,'#undo');assert.equal((await read(p)).customKeywords.length,2);await click(p,'[data-remove-item="0"]');await click(p,'#inventoryRemoveConfirm');await click(p,'#inventoryAdd');assert.equal(await p.locator('#inventorySuggestions [data-suggest-keyword="moon silver"]').count(),1);});
test('233 cancelled/invalid drafts do not learn words and custom suggestions never leak between characters',async p=>{await seed(p,[slot(fixture(),'one'),slot(fixture(),'two')]);await click(p,'[data-continue="one"]');await click(p,'#inventoryToggle');await click(p,'#inventoryAdd');await p.locator('#inventoryKeywords').fill('cancelled phrase');await click(p,'#inventoryModalCancel');assert.deepEqual((await read(p)).customKeywords,[]);await click(p,'#inventoryAdd');await p.locator('#inventoryName').fill('Charm');await p.locator('#inventoryKeywords').fill('moon silver - MOON SILVER');await click(p,'#inventoryItemConfirm');assert.equal((await read(p)).customKeywords.length,1);await click(p,'#newGameTop');await click(p,'[data-continue="two"]');await click(p,'#inventoryToggle');await click(p,'#inventoryAdd');assert.equal(await p.locator('#inventorySuggestions [data-suggest-keyword="moon silver"]').count(),0);});
test('234 custom keywords persist through reload and version-19 export/import and appear for other equipment types',async p=>{await load(p);await click(p,'#inventoryToggle');await click(p,'#inventoryAdd');await p.locator('#inventoryName').fill('Charm');await p.locator('#inventoryKeywords').fill('moon silver');await click(p,'#inventoryItemConfirm');await click(p,'#newGameTop');const promise=p.waitForEvent('download');await click(p,'[data-export="one"]');const file=await promise,raw=JSON.parse(fs.readFileSync(await file.path(),'utf8'));assert.equal(raw.version,19);assert.deepEqual(raw.character.customKeywords,[{keyword:'moon silver',category:'custom',origin:'custom'}]);await importData(p,raw);await click(p,'[data-continue="one"]');await showGear(p);await click(p,'[data-add-equipment="armor"]');assert.equal(await p.locator('#inventorySuggestions [data-suggest-keyword="moon silver"]').count(),1);});
test('235 starting items and custom enemy reward entry learn confirmed words while cancellation preserves learned preferences',async p=>{await click(p,'#createCharacter');await click(p,'#addStartingItem');await p.locator('#inventoryName').fill('Charm');await p.locator('#inventoryKeywords').fill('moon silver');await click(p,'#inventoryItemConfirm');await click(p,'#setupCards [data-card="H1"]');await click(p,'#startGame');const id=await p.evaluate(STORE=>JSON.parse(localStorage.getItem(STORE)).slots[0].id,STORE);assert.equal((await read(p,id)).customKeywords[0].keyword,'moon silver');await beginCustomCombat(p);await p.locator('#enemyHasItem').check();await p.locator('#enemyItemName').fill('Relic');await p.locator('#enemyItemKeywords').fill('star stone');await click(p,'#startCombat');await click(p,'#cancelEncounter');assert.ok((await read(p,id)).customKeywords.some(e=>e.keyword==='star stone'));});
test('236 enemy card keeps original stats first and lists keyword-adjusted combat base separately',async p=>{await keywordFight(p,{enemyWords:['Resistant against slash','Strong against metal'],weaponWords:['slash'],armorWords:['metal']});const stats=await p.locator('#activeEnemyInfo .enemy-info-stats').innerText();assert.match(stats,/Challenge Value 16/);assert.match(stats,/Wound Value 4/);assert.match(await p.locator('.combat-adjusted-stats').innerText(),/Combat base Challenge Value 22 · Combat Wound Value 6/);assert.match(await p.locator('.combat-adjusted-stats').innerText(),/before retry reduction and the random modifier/);});
test('237 Deadly Effort costs two Fate per selected card and caps selection by available Fate',async p=>{for(const combatMode of [false,true]){await load(p,effortFixture(combatMode,{fate:3}));assert.match(await p.locator(combatMode?'#combatCommit':'#commitChallenge').innerText(),/Deadly Effort/);await pick(p,['H1']);assert.match(await p.locator(combatMode?'#combatCommit':'#commitChallenge').innerText(),/2 Fate/);assert.equal(await p.locator('#operation [data-card="H2"]').isDisabled(),true);assert.match(await p.locator('.deadly-effort-tip').innerText(),/2 Fate per Fatigue card/);await click(p,combatMode?'#combatCommit':'#commitChallenge');assert.equal((await read(p)).res.Fate,1);assert.deepEqual((await read(p))[combatMode?'combat':'challenge'].deadlyCards,['H1']);}});
test('238 successful Deadly Effort sends cards directly to Wounds in Combat and Challenge, independent of armor',async p=>{for(const combatMode of [false,true]){await load(p,effortFixture(combatMode,{equipment:{weapon:null,armor:gear('Plate','armor',10)}}));await confirmEffort(p,combatMode,['H1','H2']);assert.equal((await read(p)).res.Fate,4);await p.locator(combatMode?'#combatResolve':'#resolve').click();const s=await read(p);assert.deepEqual(s.zones.wound,['S4','H1','H2']);assert.deepEqual(s.zones.fatigue,['C5']);assert.deepEqual(s.zones.hand,[]);assert.equal(s.equipment.armor.equipment.usage.filter(Boolean).length,4);assert.equal(s.dead,false);invariant(s);}});
test('239 exact-match recovery cannot return Deadly Effort cards and still sends them to Wounds',async p=>{for(const combatMode of [false,true]){await load(p,effortFixture(combatMode,{base:3}));await confirmEffort(p,combatMode,['H1','H2']);await p.locator(combatMode?'#combatResolve':'#resolve').click();assert.equal((await read(p))[combatMode?'combat':'challenge'].stage,'exact');assert.equal(await p.locator('#operation [data-card="H1"]').isDisabled(),true);assert.match(await p.locator('#operation').innerText(),/Deadly Effort cards cannot be recovered/);await click(p,combatMode?'#combatExact':'#finishExact');assert.deepEqual((await read(p)).zones.wound,['S4','H1','H2']);assert.deepEqual((await read(p)).zones.deck,[]);}});
test('240 failed combat applies normal wounds separately from direct Deadly Effort wounds',async p=>{await load(p,effortFixture(true,{base:30,wv:2}));await confirmEffort(p,true,['H1']);await p.locator('#combatResolve').click();const s=await read(p);assert.deepEqual(s.zones.wound,['S4','H1']);assert.equal(s.woundTask.value,2);assert.deepEqual(s.zones.fatigue,['H2','C5']);await pick(p,['H2']);await click(p,'#woundNext');assert.deepEqual((await read(p)).zones.wound,['S4','H1','H2']);});
test('241 Deadly Effort tracking survives reload, Cancel and Undo without repeat payment or lost cards',async p=>{const previous=fixture({res:{Coin:8,Fate:8,Supply:2},zones:{deck:['H1','H2'],hand:[],fatigue:['C5'],wound:['S4']}}),start=effortFixture(false);start.challenge.rollback=JSON.stringify(previous);await load(p,start);const before=await read(p);await confirmEffort(p,false,['H1','H2']);await p.reload();await click(p,'[data-continue="one"]');assert.equal((await read(p)).res.Fate,4);assert.deepEqual((await read(p)).challenge.deadlyCards,['H1','H2']);await click(p,'#resolve');assert.deepEqual((await read(p)).zones.wound,['S4','H1','H2']);await click(p,'#undo');assert.equal((await read(p)).res.Fate,4);assert.deepEqual((await read(p)).zones.hand,['H1','H2']);invariant(await read(p));await click(p,'#cancelEncounter');assert.deepEqual(await read(p),previous);});
test('242 paid removal returns a Deadly Effort card to Fatigue, not the Attribute Deck, without refund',async p=>{await load(p,effortFixture(false));await confirmEffort(p,false,['H1','H2']);await click(p,'#remove');await pick(p,['H1']);await click(p,'#apply');const s=await read(p);assert.equal(s.res.Fate,3);assert.deepEqual(s.zones.deck,[]);assert.ok(s.zones.fatigue.includes('H1'));assert.deepEqual(s.challenge.deadlyCards,['H2']);});
test('243 all cards entering Wounds via Deadly Effort causes Game Over even after success',async p=>{await load(p,effortFixture(false,{fatigue:['H1'],wound:[],base:1}));await confirmEffort(p,false,['H1']);await click(p,'#resolve');await click(p,'#finishExact');assert.equal((await read(p)).dead,true);assert.deepEqual((await read(p)).zones.wound,['H1']);assert.match(await p.locator('#actionStatus').innerText(),/GAME OVER/);});
test('244 failed-action exhaustion requires zero Fate; one Fate survives in both action types',async p=>{for(const combatMode of [false,true])for(const fate of [0,1]){await load(p,fixture({res:{Coin:8,Fate:fate,Supply:2},zones:{deck:['H1'],hand:[],fatigue:['H2'],wound:['S4']}}));await random(p);if(combatMode){await combat(p,['H1'],30,0);await p.locator('#combatResolve').click()}else{await challenge(p,['H1'],30);await click(p,'#resolve')}assert.equal((await read(p)).dead,fate===0);}});
test('245 empty Attribute Deck buttons look unavailable but explain inside Actions without starting an encounter',async p=>{await load(p,fixture({zones:{deck:[],hand:[],fatigue:['H1'],wound:[]}}));const before=await read(p);for(const type of ['challenge','combat']){assert.equal(await p.locator(`[data-mode="${type}"]`).evaluate(e=>e.classList.contains('action-unavailable')),true);await action(p,type);assert.match(await p.locator('#actionStatus').innerText(),new RegExp('Unable to start'+(type==='challenge'?' a challenge':' combat')+' without attribute cards'));assert.equal(await p.locator('#status').innerText(),'');assert.deepEqual(await read(p),before)}assert.equal(await p.locator('#combatChoiceModal').isVisible(),false);});
test('246 victory, validation and reward messages are scoped to Actions while inventory messages remain global',async p=>{await load(p);await random(p);await combat(p,['C5'],4);await p.locator('#combatResolve').click();assert.equal(await p.locator('#actionStatus').innerText(),'Victory! Combat rewards collected.');assert.equal(await p.locator('#status').innerText(),'');await action(p,'challenge');await p.locator('#difficulty').fill('0');await click(p,'#begin');assert.match(await p.locator('#actionStatus').innerText(),/Enter a supported/);await click(p,'#inventoryToggle');await addItem(p);assert.equal(await p.locator('#status').innerText(),'Inventory updated.');});
test('247 malformed custom keyword metadata and Deadly Effort card tracking reject import without overwriting saves',async p=>{await seed(p);const before=await read(p);for(const customKeywords of ['bad',[{keyword:'a,b',category:'custom',origin:'custom'}],[{keyword:'moon',category:'other',origin:'predefined'}]]){await importData(p,fixture({customKeywords}));assert.match(await p.locator('#status').innerText(),/Import failed/)}const bad=effortFixture(false);bad.challenge.deadlyCards=['H1'];await importData(p,bad);assert.match(await p.locator('#status').innerText(),/Import failed/);assert.deepEqual(await read(p),before);});
test('248 new custom suggestions and Deadly Effort remain usable offline',async(p,ctx,browser)=>{const c=await browser.newContext({offline:true});try{const q=await c.newPage();q.setDefaultTimeout(10000);await c.route('**/*',r=>r.fulfill({status:200,contentType:'text/html',body:fs.readFileSync(APP_FILE)}));await q.goto(new URL(p.url()).origin);await load(q,effortFixture(false));await confirmEffort(q,false,['H1','H2']);await click(q,'#resolve');assert.deepEqual((await read(q)).zones.wound,['S4','H1','H2']);await click(q,'#inventoryToggle');await click(q,'#inventoryAdd');await q.locator('#inventoryName').fill('Charm');await q.locator('#inventoryKeywords').fill('moon silver');await click(q,'#inventoryItemConfirm');assert.equal((await read(q)).customKeywords[0].keyword,'moon silver');}finally{await c.close()}});

test('249 custom toggles and original/adjusted enemy stats fit mobile screens',async(p,ctx,browser)=>{const c=await browser.newContext({viewport:{width:320,height:844},isMobile:true,hasTouch:true});try{const q=await c.newPage();q.setDefaultTimeout(10000);await q.goto(p.url());await load(q,fixture({customKeywords:[{keyword:'moon silver',category:'custom',origin:'custom'},{keyword:'x'.repeat(300),category:'custom',origin:'custom'}],equipment:{weapon:withWords(gear(),['slash']),armor:null}}));await click(q,'#inventoryToggle');await click(q,'#inventoryAdd');await click(q,'#inventorySuggestions [data-suggest-keyword="moon silver"]');assert.equal(await q.locator('#inventoryKeywords').inputValue(),'moon silver');await click(q,'#inventorySuggestions [data-suggest-keyword="moon silver"]');assert.equal(await q.locator('#inventoryKeywords').inputValue(),'');assert.ok(await q.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await click(q,'#inventoryModalCancel');await defineEnemy(q,{base:16,keywords:['Resistant against slash']});assert.ok(await q.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await q.locator('#activeEnemyInfo').screenshot({path:path.join(OUT,'v27-enemy-mobile.png')});assert.match(await q.locator('.enemy-info-stats').innerText(),/Challenge Value 16/);assert.match(await q.locator('.combat-adjusted-stats').innerText(),/Challenge Value 22/);}finally{await c.close()}});
test('250 exact recovery can return ordinary cards while tracked Deadly Effort cards always enter Wounds',async p=>{await load(p,fixture({zones:{deck:['S4'],hand:['H1','H2'],fatigue:['C5'],wound:['D6']},challenge:{base:3,modifier:0,stage:'exact',adjusted:false,allowed:['H','S','C','D'],deadlyCards:['H1']}}));assert.equal(await p.locator('#operation [data-card="H1"]').isDisabled(),true);await pick(p,['H2']);await click(p,'#finishExact');const s=await read(p);assert.deepEqual(s.zones.deck,['S4','H2']);assert.deepEqual(s.zones.wound,['D6','H1']);assert.deepEqual(s.zones.fatigue,['C5']);invariant(s);});

// V26 draft catalog, manager, enemy associations and embedded sound.
async function addManagedWord(p,word,category='custom'){await p.locator('#manageKeywordText').fill(word);await p.locator('#manageKeywordCategory').selectOption(category);await click(p,'#manageKeywordAdd')}
async function importKeywordBundle(p,bundle){await p.locator('#importCustomKeywordFile').setInputFiles({name:'keywords.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(bundle))});await p.waitForTimeout(60)}
async function mockVictorySound(p,reject=false){await p.addInitScript(reject=>{window.victoryCalls=0;window.soundPauses=0;HTMLMediaElement.prototype.play=function(){window.victoryCalls++;return reject?Promise.reject(Error('Playback blocked')):Promise.resolve()};HTMLMediaElement.prototype.pause=function(){window.soundPauses++}},reject)}

test('251 equipment checkbox is beside and vertically aligned with its label in item and reward editors',async p=>{await load(p);await click(p,'#inventoryToggle');await click(p,'#inventoryAdd');for(const prefix of ['inventory','enemyItem']){if(prefix==='enemyItem'){await click(p,'#inventoryModalCancel');await beginCustomCombat(p);await p.locator('#enemyHasItem').check()}const position=await p.locator('#'+prefix+'IsEquipment').evaluate(input=>{const label=input.parentElement,text=[...label.childNodes].find(n=>n.nodeType===3&&n.textContent.trim()),range=document.createRange();range.selectNodeContents(text);const a=input.getBoundingClientRect(),b=range.getBoundingClientRect();return {width:a.width,left:a.x,right:a.right,textLeft:b.x,delta:Math.abs(a.y+a.height/2-b.y-b.height/2),display:getComputedStyle(label).display}});assert.equal(position.width,20);assert.equal(position.display,'flex');assert.ok(position.textLeft>=position.right);assert.ok(position.delta<3)}});
test('252 blur creates selected temporary toggles and a single Cancel click discards them permanently',async p=>{await load(p);await click(p,'#inventoryToggle');await click(p,'#inventoryAdd');await p.locator('#inventoryKeywords').fill('moon silver');await p.locator('#inventoryName').click();assert.equal(await p.locator('#inventorySuggestions [data-suggest-keyword="moon silver"]').getAttribute('aria-pressed'),'true');assert.deepEqual((await read(p)).customKeywords,[]);await click(p,'#inventoryModalCancel');assert.equal(await p.locator('#inventoryModal').isVisible(),false);await click(p,'#inventoryAdd');assert.equal(await p.locator('#inventorySuggestions [data-suggest-keyword="moon silver"]').count(),0);assert.deepEqual((await read(p)).customKeywords,[]);});
test('253 starting another keyword adds only completed phrases, with permanent learning on successful confirmation',async p=>{await load(p);await click(p,'#inventoryToggle');await click(p,'#inventoryAdd');await p.locator('#inventoryName').fill('Charm');await p.locator('#inventoryKeywords').fill('moon silver - star stone');assert.equal(await p.locator('#inventorySuggestions [data-suggest-keyword="moon silver"]').count(),1);assert.equal(await p.locator('#inventorySuggestions [data-suggest-keyword="star stone"]').count(),0);await p.locator('#inventoryName').click();assert.equal(await p.locator('#inventorySuggestions [data-suggest-keyword="star stone"]').getAttribute('aria-pressed'),'true');await click(p,'#inventorySuggestions [data-suggest-keyword="moon silver"]');assert.equal(await p.locator('#inventoryKeywords').inputValue(),'star stone');await click(p,'#inventoryItemConfirm');assert.deepEqual((await read(p)).customKeywords,[{keyword:'star stone',category:'custom',origin:'custom'}]);});
test('254 temporary suggestions also work for starting equipment and enemy reward entry without leaking cancelled words',async p=>{await click(p,'#createCharacter');await click(p,'[data-start-equipment="weapon"]');await p.locator('#inventoryKeywords').fill('moon silver -');assert.equal(await p.locator('#inventorySuggestions [data-suggest-keyword="moon silver"]').count(),1);await click(p,'#inventoryModalCancel');await click(p,'#newGameTop');await load(p);await beginCustomCombat(p);await p.locator('#enemyHasItem').check();await p.locator('#enemyItemKeywords').fill('star stone');await p.locator('#enemyItemName').click();assert.equal(await p.locator('#enemyItemSuggestions [data-suggest-keyword="star stone"]').count(),1);await click(p,'#enemySetupCancel');assert.deepEqual((await read(p)).customKeywords,[]);});
test('255 Manage Keywords adds/edits words, assigns predefined/new categories and retains custom origin',async p=>{await load(p);assert.equal(await p.locator('#editModule').evaluate(e=>e.nextElementSibling.id),'manageKeywords');await click(p,'#manageKeywords');await addManagedWord(p,'moon silver','Material');await p.locator('#newKeywordCategory').fill('Celestial');await click(p,'#createKeywordCategory');await click(p,'[data-manage-edit="0"]');await p.locator('#manageKeywordText').fill('lunar silver');await p.locator('#manageKeywordCategory').selectOption('Celestial');await click(p,'#keywordManagerSave');assert.deepEqual((await read(p)).customKeywords,[{keyword:'lunar silver',category:'Celestial',origin:'custom'}]);assert.ok((await read(p)).customCategories.includes('Celestial'));await click(p,'#inventoryToggle');await click(p,'#inventoryAdd');assert.match(await p.locator('#inventorySuggestions').innerText(),/Celestial/);assert.equal(await p.locator('#inventorySuggestions [data-suggest-keyword="lunar silver"]').count(),1);});
test('256 removing custom suggestions never rewrites items or reappears from unrelated item edits/Undo',async p=>{await load(p,fixture({customKeywords:[{keyword:'moon silver',category:'custom',origin:'custom'}],inventory:[{name:'Charm',description:'',keywords:['moon silver'],baseValue:1}]}));await click(p,'[data-resource="Coin"][data-delta="1"]');await click(p,'#manageKeywords');await click(p,'[data-manage-remove="0"]');await click(p,'#keywordManagerSave');assert.deepEqual((await read(p)).customKeywords,[]);assert.deepEqual((await read(p)).inventory[0].keywords,['moon silver']);await click(p,'#undo');assert.deepEqual((await read(p)).customKeywords,[]);await click(p,'#inventoryToggle');await click(p,'[data-edit-item="0"]');await p.locator('#inventoryName').fill('Renamed charm');await click(p,'#inventoryItemConfirm');assert.deepEqual((await read(p)).customKeywords,[]);});
test('257 manager Cancel discards category/keyword drafts and rejects comma names or duplicate case variants',async p=>{await load(p);const before=await read(p);await click(p,'#manageKeywords');await addManagedWord(p,'moon silver');await addManagedWord(p,'MOON SILVER');assert.match(await p.locator('#keywordManagerError').innerText(),/already/);await addManagedWord(p,'bad, keyword');assert.match(await p.locator('#keywordManagerError').innerText(),/Invalid/);await p.locator('#newKeywordCategory').fill('Celestial');await click(p,'#createKeywordCategory');await p.keyboard.press('Escape');assert.deepEqual(await read(p),before);});
test('258 custom keyword JSON shares all categories/origins between characters and merges duplicates without replacing assignments',async p=>{await seed(p,[slot(fixture({customKeywords:[{keyword:'moon silver',category:'Material',origin:'custom'},{keyword:'star stone',category:'Celestial',origin:'custom'}],customCategories:['Celestial','Empty category']}),'one'),slot(fixture({customKeywords:[{keyword:'MOON SILVER',category:'Effect',origin:'custom'}]}),'two')]);await click(p,'[data-continue="one"]');await click(p,'#manageKeywords');const pending=p.waitForEvent('download');await click(p,'#exportCustomKeywords');const file=await pending,bundle=JSON.parse(fs.readFileSync(await file.path(),'utf8'));assert.equal(bundle.format,'quest-for-glory-custom-keywords');assert.ok(bundle.keywords.every(e=>e.origin==='custom'));assert.ok(bundle.categories.includes('Empty category'));await click(p,'#keywordManagerCancel');await click(p,'#newGameTop');await click(p,'[data-continue="two"]');await click(p,'#manageKeywords');await importKeywordBundle(p,bundle);assert.match(await p.locator('#keywordManagerError').innerText(),/Imported 1/);assert.equal((await read(p,'two')).customKeywords.length,1);await click(p,'#keywordManagerSave');const s=await read(p,'two');assert.equal(s.customKeywords.length,2);assert.equal(s.customKeywords[0].category,'Effect');assert.equal(s.customKeywords[1].category,'Celestial');assert.ok(s.customCategories.includes('Empty category'));});
test('259 malformed custom imports and cancelled valid imports do not modify the character',async p=>{await load(p);const before=await read(p);await click(p,'#manageKeywords');await importKeywordBundle(p,{format:'quest-for-glory-custom-keywords',version:1,categories:[],keywords:[{keyword:'moon silver',category:'Material',origin:'predefined'}]});assert.match(await p.locator('#keywordManagerError').innerText(),/Import failed/);await importKeywordBundle(p,{format:'quest-for-glory-custom-keywords',version:1,categories:['Celestial'],keywords:[{keyword:'moon silver',category:'Celestial',origin:'custom'}]});await click(p,'#keywordManagerCancel');assert.deepEqual(await read(p),before);});
test('260 V25 keyword metadata migrates to custom origin and version-19 character export retains categories',async p=>{const old=fixture({customKeywords:[{keyword:'moon silver',category:'custom'}]});delete old.customCategories;await seed(p);await importData(p,{format:'quest-for-glory-character',version:17,character:old});const id=await p.locator('[data-continue]').last().getAttribute('data-continue');assert.deepEqual((await read(p,id)).customKeywords,[{keyword:'moon silver',category:'custom',origin:'custom'}]);await click(p,`[data-continue="${id}"]`);await click(p,'#manageKeywords');await click(p,'[data-manage-edit="0"]');await p.locator('#manageKeywordCategory').selectOption('Material');await click(p,'#keywordManagerSave');await click(p,'#newGameTop');const pending=p.waitForEvent('download');await click(p,`[data-export="${id}"]`);const file=await pending,data=JSON.parse(fs.readFileSync(await file.path(),'utf8'));assert.equal(data.version,19);assert.equal(data.character.customKeywords[0].origin,'custom');assert.equal(data.character.customKeywords[0].category,'Material');});
test('261 enemy comma input disables Begin combat and clearing it restores the button without starting combat',async p=>{await load(p);await beginCustomCombat(p);assert.equal(await p.locator('#enemyKeywords').getAttribute('placeholder'),null);await p.locator('#enemyKeywords').fill('undead, large');assert.equal(await p.locator('#startCombat').isDisabled(),true);assert.equal(await p.locator('#startCombat').evaluate(e=>getComputedStyle(e).backgroundColor),'rgb(221, 221, 221)');assert.equal((await read(p)).combat,null);await p.locator('#enemyKeywords').fill('undead - large');assert.equal(await p.locator('#startCombat').isDisabled(),false);await p.locator('#enemyHasItem').check();await p.locator('#enemyItemKeywords').fill('weapon, metal');assert.equal(await p.locator('#startCombat').isDisabled(),true);await p.locator('#enemyHasItem').uncheck();assert.equal(await p.locator('#startCombat').isDisabled(),false);});
test('262 enemy association toggles use the relevant equipment lists and toggle canonical/typed aliases',async p=>{await load(p);await beginCustomCombat(p);assert.equal(await p.locator('[data-association-kind="resistant"] button[data-association-target="slash"]').count(),1);assert.equal(await p.locator('[data-association-kind="weak"] button[data-association-target="slash"]').count(),0);assert.equal(await p.locator('[data-association-kind="weak"] button[data-association-target="Full Body"]').count(),1);await p.locator('details[data-association-kind="resistant"] summary').click();await click(p,'[data-enemy-association="Resistant against slash"]');assert.equal(await p.locator('#enemyKeywords').inputValue(),'Resistant against slash');assert.equal(await p.locator('[data-enemy-association="Resistant against slash"]').getAttribute('aria-pressed'),'true');await p.locator('#enemyKeywords').fill('Undead - resistant slash');await click(p,'[data-enemy-association="Resistant against slash"]');assert.equal(await p.locator('#enemyKeywords').inputValue(),'Undead');});
test('263 enemy associations selected through toggles feed actual combat values',async p=>{await load(p,fixture({equipment:{weapon:withWords(gear(),['slash']),armor:withWords(gear('Mail','armor',1),['metal'])}}));await beginCustomCombat(p);await p.locator('details[data-association-kind="resistant"] summary').click();await click(p,'[data-enemy-association="Resistant against slash"]');await p.locator('details[data-association-kind="strong"] summary').click();await click(p,'[data-enemy-association="Strong against metal"]');await click(p,'#startCombat');assert.deepEqual((await read(p)).combat.enemy.KW,['Resistant against slash','Strong against metal']);assert.match(await p.locator('.combat-adjusted-stats').innerText(),/Challenge Value 11 · Combat Wound Value 3/);assert.deepEqual((await read(p)).customKeywords,[]);});
test('264 victory sound source is preserved and embedded WAV decodes as three seconds',async p=>{const source=fs.readFileSync(path.join(ROOT,'audio/medieval_fantasy_victory_fanfare_3s.wav')),src=await p.locator('#combatVictorySound').getAttribute('src');assert.deepEqual(Buffer.from(src.split(',')[1],'base64'),source);assert.equal(source.toString('ascii',0,4),'RIFF');await p.waitForFunction(()=>Number.isFinite(document.getElementById('combatVictorySound').duration));assert.ok(Math.abs(await p.locator('#combatVictorySound').evaluate(e=>e.duration)-3)<.01);});
test('265 normal combat victory plays once and challenge success/failure never plays it',async p=>{await mockVictorySound(p);await load(p);await random(p);await combat(p,['C5'],4);await p.locator('#combatResolve').click();assert.equal(await p.evaluate(()=>window.victoryCalls),1);await challenge(p,['H3'],2);await click(p,'#resolve');assert.equal(await p.evaluate(()=>window.victoryCalls),1);await combat(p,['H1'],30,0);await p.locator('#combatResolve').click();assert.equal(await p.evaluate(()=>window.victoryCalls),1);});
test('266 exact combat sounds only after recovery is confirmed',async p=>{await mockVictorySound(p);await load(p);await random(p);await combat(p,['H2','H3'],5);await p.locator('#combatResolve').click();assert.equal(await p.evaluate(()=>window.victoryCalls),0);await click(p,'#combatExact');assert.equal(await p.evaluate(()=>window.victoryCalls),1);});
test('267 pending victory rewards save sound state and do not replay on reload or item decisions',async p=>{await mockVictorySound(p);await winPendingItem(p,{full:true});assert.equal(await p.evaluate(()=>window.victoryCalls),1);assert.equal((await read(p)).combat.victorySoundPlayed,true);await p.reload();await click(p,'[data-continue="one"]');assert.equal(await p.evaluate(()=>window.victoryCalls),0);await click(p,'#rewardDiscard');assert.equal(await p.evaluate(()=>window.victoryCalls),0);});
test('268 resource-overflow victory retries do not replay the fanfare or duplicate rewards',async p=>{await mockVictorySound(p);await load(p,fixture({res:{Coin:Number.MAX_SAFE_INTEGER,Fate:4,Supply:2}}));await random(p);await defineEnemy(p,{base:4,coin:1});await pick(p,['C5']);await click(p,'#combatCommit');await p.locator('#combatResolve').click();assert.equal(await p.evaluate(()=>window.victoryCalls),1);await click(p,'[data-resource="Coin"][data-delta="-1"]');await click(p,'#collectCombatRewards');assert.equal(await p.evaluate(()=>window.victoryCalls),1);assert.equal((await read(p)).res.Coin,Number.MAX_SAFE_INTEGER);});
test('269 blocked audio playback is harmless and victory resources still save',async p=>{await mockVictorySound(p,true);await load(p);await random(p);await combat(p,['C5'],4);await p.locator('#combatResolve').click();assert.equal(await p.evaluate(()=>window.victoryCalls),1);assert.equal((await read(p)).combat,null);assert.equal((await read(p)).res.Fate,5);});
test('270 Undo and menu navigation stop sound; a newly reconfirmed victory may play again',async p=>{await mockVictorySound(p);await load(p);await random(p);await combat(p,['C5'],4);await p.locator('#combatResolve').click();const before=await p.evaluate(()=>window.soundPauses);await click(p,'#undo');assert.ok(await p.evaluate(()=>window.soundPauses)>before);await p.locator('#combatResolve').click();assert.equal(await p.evaluate(()=>window.victoryCalls),2);const again=await p.evaluate(()=>window.soundPauses);await click(p,'#newGameTop');assert.ok(await p.evaluate(()=>window.soundPauses)>again);});
test('271 malformed WAV input fails the build without replacing output',async()=>{const dir=fs.mkdtempSync(path.join(os.tmpdir(),'qfg-sound-')),input=path.join(dir,'bad.wav'),output=path.join(dir,'app.html');try{fs.writeFileSync(input,'not a wav');fs.writeFileSync(output,'previous output');const result=spawnSync(process.execPath,[path.join(ROOT,'scripts/build-v27.cjs'),'--audio',input,'--output',output],{encoding:'utf8'});assert.notEqual(result.status,0);assert.equal(fs.readFileSync(output,'utf8'),'previous output')}finally{fs.rmSync(dir,{recursive:true,force:true})}});
test('272 manager and enemy association controls fit mobile and preserve keyboard cancellation',async(p,ctx,browser)=>{const c=await browser.newContext({viewport:{width:320,height:844},isMobile:true,hasTouch:true});try{const q=await c.newPage();q.setDefaultTimeout(10000);await q.goto(p.url());await load(q,fixture({customKeywords:[{keyword:'x'.repeat(300),category:'Celestial',origin:'custom'}],customCategories:['Celestial']}));await click(q,'#manageKeywords');assert.ok(await q.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));const input=await q.locator('#newKeywordCategory').boundingBox(),button=await q.locator('#createKeywordCategory').boundingBox();assert.ok(button.y>=input.y+input.height);await q.screenshot({path:path.join(OUT,'v27-keyword-manager-mobile.png')});await q.keyboard.press('Escape');assert.equal(await q.locator('#keywordManagerModal').isVisible(),false);await beginCustomCombat(q);await q.locator('details[data-association-kind="resistant"] summary').click();assert.ok(await q.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await q.screenshot({path:path.join(OUT,'v27-enemy-associations-mobile.png')});}finally{await c.close()}});
test('273 category manager preferences can change during combat without rewriting items or being reverted by cancellation',async p=>{await load(p,fixture({customKeywords:[{keyword:'moon silver',category:'custom',origin:'custom'}],equipment:{weapon:withWords(gear(),['moon silver']),armor:null}}));await defineEnemy(p,{keywords:['Resistant against moon silver']});await click(p,'#manageKeywords');await click(p,'[data-manage-remove="0"]');await click(p,'#keywordManagerSave');assert.deepEqual((await read(p)).customKeywords,[]);assert.deepEqual((await read(p)).equipment.weapon.keywords,['moon silver']);assert.match(await p.locator('.combat-adjusted-stats').innerText(),/Challenge Value 11/);await click(p,'#cancelEncounter');assert.deepEqual((await read(p)).customKeywords,[]);});
test('274 custom manager and victory sound work offline without external assets',async(p,ctx,browser)=>{const c=await browser.newContext({offline:true});try{const q=await c.newPage(),origin=new URL(p.url()).origin,external=[];q.setDefaultTimeout(10000);await mockVictorySound(q);await c.route('**/*',r=>{if(new URL(r.request().url()).origin!==origin){external.push(r.request().url());return r.abort()}return r.fulfill({status:200,contentType:'text/html',body:fs.readFileSync(APP_FILE)})});await q.goto(origin);await load(q);await click(q,'#manageKeywords');await addManagedWord(q,'moon silver','Material');await click(q,'#keywordManagerSave');await random(q);await combat(q,['C5'],4);await q.locator('#combatResolve').click();assert.equal(await q.evaluate(()=>window.victoryCalls),1);assert.equal((await read(q)).customKeywords[0].origin,'custom');assert.deepEqual(external,[]);}finally{await c.close()}});
test('275 custom keyword labels/imports are escaped and cannot execute markup',async p=>{await load(p);await click(p,'#manageKeywords');const word='<img src=x onerror="window.bad=true">';await addManagedWord(p,word,'Material');assert.equal(await p.locator('#managedKeywordList img').count(),0);await click(p,'#keywordManagerSave');await click(p,'#inventoryToggle');await click(p,'#inventoryAdd');assert.equal(await p.locator('#inventorySuggestions img').count(),0);assert.equal(await p.evaluate(()=>!!window.bad),false);});

async function enterDungeon(p){await click(p,'#startDungeonDelve');await p.locator('[name="dungeonChoice"]').first().check();await click(p,'#dungeonStart');}
async function winDungeonLevel(p,ids=['C5']){await p.evaluate(()=>{let calls=0;Math.random=()=>++calls===1?.4:.99});await click(p,'#dungeonChallenge');await pick(p,ids);await click(p,'#commitChallenge');await click(p,'#resolve');if(await p.locator('#finishExact').count())await click(p,'#finishExact');}
function delveFixture(level=1,phase='challenge',extra={}){const definition=JSON.parse(fs.readFileSync(path.join(ROOT,'data/dungeons.json'))).dungeons[0],enemies=JSON.parse(fs.readFileSync(path.join(ROOT,'data/enemies.json'))).enemies;return fixture({dungeonProgress:[{id:definition.id,rewardedLevels:Array.from({length:phase==='cleared'?level:level-1},(_,i)=>i+1),completed:false}],delve:{definition,enemies,level,phase,pendingCoins:0,restUsed:false,challengeWon:phase==='cleared',challengeAttempts:0,encounterRolled:false,enemyId:null,lastRoll:null,bossWon:false,...extra}})}
test('276 V27 Start Game is below and to the right of Add Item',async p=>{await click(p,'#createCharacter');const a=await p.locator('#startGame').boundingBox(),b=await p.locator('#addStartingItem').boundingBox();assert.ok(a.x>b.x);assert.ok(a.y>b.y+b.height)});
