test('285 dungeon snapshot survives reload and keeps encounter definitions',async p=>{await load(p);await enterDungeon(p);const d=(await read(p)).delve;await p.reload();await click(p,'[data-continue="one"]');assert.deepEqual((await read(p)).delve,d);assert.equal(await p.locator('#dungeonScreen').isVisible(),true)});
test('286 dungeon challenge success banks first-level Coins until exit',async p=>{await load(p);await enterDungeon(p);await winDungeonLevel(p);let s=await read(p);assert.equal(s.delve.phase,'cleared');assert.equal(s.delve.pendingCoins,4);assert.equal(s.res.Coin,8);await click(p,'#dungeonExit');s=await read(p);assert.equal(s.delve,null);assert.equal(s.res.Coin,12)});
test('287 repeat attempts start at level one without repeat level Coins',async p=>{await load(p);await enterDungeon(p);await winDungeonLevel(p);await click(p,'#dungeonExit');await enterDungeon(p);await winDungeonLevel(p,['S4','H1']);assert.equal((await read(p)).delve.pendingCoins,0);await click(p,'#dungeonExit');assert.equal((await read(p)).res.Coin,12)});
test('288 failed dungeon challenge permits retry and keeps support locked',async p=>{await load(p);await enterDungeon(p);await random(p);await click(p,'#dungeonChallenge');await pick(p,['H1']);await click(p,'#commitChallenge');await click(p,'#resolve');assert.equal((await read(p)).delve.phase,'challenge');assert.equal(await p.locator('#dungeonHeal').isDisabled(),true);assert.match(await p.locator('#dungeonChallenge').innerText(),/Retry/)});
test('289 delving deeper resets the level rest limit and support lock',async p=>{await load(p,delveFixture(1,'cleared',{restUsed:true}));await click(p,'#dungeonNext');const d=(await read(p)).delve;assert.equal(d.level,2);assert.equal(d.restUsed,false);assert.equal(d.challengeWon,false);assert.equal(await p.locator('#dungeonRest').isDisabled(),true)});
test('290 boss level permits only fight or exit before combat',async p=>{await load(p,delveFixture(5,'boss'));assert.equal(await p.locator('#dungeonChallenge').count(),0);for(const id of ['Heal','Rest','Upgrade'])assert.equal(await p.locator('#dungeon'+id).isDisabled(),true);assert.equal(await p.locator('#dungeonFight').isEnabled(),true);await click(p,'#dungeonFight');assert.equal((await read(p)).combat.enemy.boss,true);assert.equal((await read(p)).combat.dungeon,true)});
test('291 leaving a dungeon challenge does not refund committed cards',async p=>{await load(p);await enterDungeon(p);await random(p);await click(p,'#dungeonChallenge');await pick(p,['H1']);await click(p,'#commitChallenge');await click(p,'#dungeonExit');const s=await read(p);assert.equal(s.delve,null);assert.ok(s.zones.fatigue.includes('H1'));invariant(s)});
test('292 dungeon JSON rejects missing references and malformed formulas',async()=>{const v=require('../scripts/enemy-library-v27.cjs'),enemies=JSON.parse(fs.readFileSync(path.join(ROOT,'data/enemies.json'))).enemies,d=JSON.parse(fs.readFileSync(path.join(ROOT,'data/dungeons.json')));for(const mutate of [x=>x.dungeons[0].boss.enemyId='Missing',x=>x.dungeons[0].challenge.perLevel=-1,x=>x.dungeons[0].encounters[0].rolls=[1]]){const x=structuredClone(d);mutate(x);assert.throws(()=>v.validateDungeonLibrary(x,enemies))}});
test('293 invalid saved dungeon reward gaps reject import',async p=>{await seed(p);const before=await read(p),bad=delveFixture(3);bad.dungeonProgress[0].rewardedLevels=[2];await importData(p,bad);assert.match(await p.locator('#status').innerText(),/Import failed/);assert.deepEqual(await read(p),before)});
test('294 dungeon cannot start with empty Attribute Deck',async p=>{await load(p,fixture({zones:{deck:[],hand:[],fatigue:['H1'],wound:[]}}));await click(p,'#startDungeonDelve');await p.locator('[name="dungeonChoice"]').first().check();await click(p,'#dungeonStart');assert.equal((await read(p)).delve,null);assert.match(await p.locator('#dungeonChoiceError').innerText(),/Restore Attribute/)});

test('295 encounter roll uses enemy library and existing combat flow',async p=>{await load(p);await enterDungeon(p);await p.evaluate(()=>{let i=0;Math.random=()=>[.4,0,.55][Math.min(i++,2)]});await click(p,'#dungeonChallenge');await pick(p,['C5']);await click(p,'#commitChallenge');await click(p,'#resolve');let s=await read(p);assert.equal(s.delve.phase,'encounter');assert.equal(s.delve.enemyId,'Skeleton');assert.equal(s.delve.pendingCoins,0);await click(p,'#dungeonFight');s=await read(p);assert.equal(s.combat.enemy.CV,8);assert.equal(s.combat.dungeon,true);assert.equal(await p.locator('#cancelEncounter').count(),0)});
test('296 Rest completes once per cleared level using existing Supply and Round rules',async p=>{const f=delveFixture(1,'cleared');f.zones={deck:['H1','H2','H3','S4'],fatigue:['C5'],hand:[],wound:[]};delete f.pool;delete f.upgradePoints;f.delve.pendingCoins=4;f.dungeonProgress[0].rewardedLevels=[1];await load(p,fixture(f));await click(p,'#dungeonRest');await click(p,'#restConfirmYes');await pick(p,['C5']);await click(p,'#commit');const s=await read(p);assert.equal(s.delve.restUsed,true);assert.equal(s.round,1);assert.equal(s.res.Supply,1);assert.equal(await p.locator('#dungeonRest').isDisabled(),true)});
test('297 boss victory pays Coins and offers treasure only after victory',async p=>{const f=delveFixture(5,'boss',{pendingCoins:22});await load(p,f);await random(p);await click(p,'#dungeonFight');await pick(p,['C5','D6','S4','H3','H2']);await click(p,'#combatCommit');await click(p,'#combatResolve');assert.equal(await p.locator('#dungeonTreasureModal').isVisible(),true);let s=await read(p);assert.equal(s.res.Coin,38);assert.equal(s.res.Fate,7);assert.equal(s.dungeonProgress[0].completed,true);await click(p,'#dungeonTreasureKeep');s=await read(p);assert.equal(s.delve,null);assert.equal(s.inventory[0].equipment.modifier,2);await click(p,'#startDungeonDelve');assert.equal(await p.locator('[name="dungeonChoice"]').count(),0)});
test('298 exiting boss level grants no treasure and leaves dungeon retryable',async p=>{await load(p,delveFixture(5,'boss',{pendingCoins:22}));await click(p,'#dungeonExit');assert.equal((await read(p)).inventory.length,0);assert.equal((await read(p)).dungeonProgress[0].completed,false);await enterDungeon(p);assert.equal((await read(p)).delve.level,1)});
test('299 dungeon layout fits mobile and uses one copy of every character panel',async(p,ctx,browser)=>{const c=await browser.newContext({viewport:{width:320,height:844},isMobile:true,hasTouch:true});try{const q=await c.newPage();q.setDefaultTimeout(10000);await q.goto(p.url());await load(q);await enterDungeon(q);assert.ok(await q.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await click(q,'#dungeonSheetToggle');for(const id of ['resourcesPanel','cardZonesPanel','equipmentPanel','inventoryPanel','dicePanel'])assert.equal(await q.locator('#dungeonSheetBody #'+id).count(),1);await q.screenshot({path:path.join(OUT,'v27-dungeon-mobile.png'),fullPage:true});}finally{await c.close()}});
test('300 enemy association custom target is temporary until Begin Combat',async p=>{await load(p);await beginCustomCombat(p);await p.locator('#enemyKeywords').fill('Weak against water');await p.locator('#enemyDescription').click();await p.locator('[data-association-kind="weak"] summary').click();assert.equal(await p.locator('button[data-association-kind="weak"][data-association-target="water"]').getAttribute('aria-pressed'),'true');assert.deepEqual((await read(p)).customKeywords,[]);await click(p,'#startCombat');assert.ok((await read(p)).customKeywords.some(e=>e.keyword==='water'));});
test('301 active keyword and contributing gear are bold red during combat',async p=>{await load(p,fixture({equipment:{weapon:withWords(gear(),['slash']),armor:null}}));await defineEnemy(p,{keywords:['Resistant against slash']});assert.ok(await p.locator('#operation .active-keyword').count()>0);assert.ok(await p.locator('#equipmentPanel .active-keyword').count()>0);const color=await p.locator('#equipmentPanel .active-keyword').first().evaluate(e=>getComputedStyle(e).color);assert.notEqual(color,'rgb(0, 0, 0)')});

test('302 boss treasure replaces one full-inventory item without sale income',async p=>{const f=delveFixture(5,'boss');f.inventory=Array.from({length:8},(_,i)=>({name:'Item '+i,description:'',keywords:[],baseValue:100}));await load(p,f);await random(p);await click(p,'#dungeonFight');await pick(p,['C5','D6','S4','H3','H2']);await click(p,'#combatCommit');await click(p,'#combatResolve');await click(p,'#dungeonTreasureKeep');await p.locator('[name="dungeonTreasureDiscard"][value="3"]').check();await click(p,'#dungeonTreasureConfirm');const s=await read(p);assert.equal(s.inventory.length,8);assert.equal(s.inventory[3].name,'Specter of the unholy mice');assert.equal(s.res.Coin,16);assert.equal(s.delve,null)});
test('303 dungeon challenge and hand resume after reload',async p=>{await load(p);await enterDungeon(p);await random(p);await click(p,'#dungeonChallenge');await pick(p,['C5']);await click(p,'#commitChallenge');await p.reload();await click(p,'[data-continue="one"]');assert.deepEqual((await read(p)).zones.hand,['C5']);await random(p,.99);await click(p,'#resolve');assert.equal((await read(p)).delve.phase,'cleared')});
test('304 locked dungeon resources ignore manual adjustment while card inspection stays available',async p=>{await load(p);await enterDungeon(p);await click(p,'#dungeonSheetToggle');const before=(await read(p)).res.Coin;assert.equal(await p.locator('[data-resource="Coin"][data-delta="1"]').isDisabled(),true);assert.equal((await read(p)).res.Coin,before);await click(p,'[data-viewzone="deck"]');assert.equal(await p.locator('#zoneView').isVisible(),true);assert.equal(await p.locator('#roundDisplay').isDisabled(),true)});
test('305 completed dungeon state exports and imports with its treasure decision',async p=>{const f=delveFixture(5,'treasure',{bossWon:true,challengeWon:true});f.dungeonProgress[0].completed=true;f.dungeonProgress[0].rewardedLevels=[1,2,3,4,5];await load(p,f);await p.reload();await click(p,'[data-continue="one"]');assert.equal(await p.locator('#dungeonTreasureModal').isVisible(),true);await click(p,'#dungeonTreasureDecline');assert.equal((await read(p)).inventory.length,0);assert.equal((await read(p)).delve,null)});
test('306 cancelled enemy association targets never enter permanent suggestions',async p=>{await load(p);await beginCustomCombat(p);await p.locator('#enemyKeywords').fill('Weak against water');await p.locator('#enemyDescription').click();await click(p,'#enemySetupCancel');assert.deepEqual((await read(p)).customKeywords,[])});
test('307 dungeon snapshot invalid base challenge rejects import without data loss',async p=>{await seed(p);const bad=delveFixture();bad.challenge={base:999,modifier:null,stage:'choose',adjusted:false,adjustmentsUsed:0,allowed:['H','S','C','D'],dungeon:true};await importData(p,bad);assert.match(await p.locator('#status').innerText(),/Import failed/);assert.equal((await read(p)).delve,null)});
test('308 dungeon normal combat victory banks encounter Coins until exit',async p=>{const f=delveFixture(1,'encounter',{challengeWon:true,encounterRolled:true,enemyId:'Skeleton',lastRoll:{chance:1,enemy:4}});await load(p,f);await random(p);await click(p,'#dungeonFight');await pick(p,['C5','D6']);await click(p,'#combatCommit');await click(p,'#combatResolve');let s=await read(p);assert.equal(s.res.Coin,8);assert.equal(s.delve.pendingCoins,5);assert.equal(s.delve.phase,'cleared');await click(p,'#dungeonExit');assert.equal((await read(p)).res.Coin,13)});
test('309 repeated-level monster Coins are not awarded a second time',async p=>{const f=delveFixture(1,'encounter',{challengeWon:true,encounterRolled:true,enemyId:'Skeleton',lastRoll:{chance:1,enemy:4}});f.dungeonProgress[0].rewardedLevels=[1];await load(p,f);await random(p);await click(p,'#dungeonFight');await pick(p,['C5','D6']);await click(p,'#combatCommit');await click(p,'#combatResolve');assert.equal((await read(p)).delve.pendingCoins,0)});
test('310 failed dungeon combat Flee uses normal Fate cost and exits dungeon',async p=>{const f=delveFixture(1,'encounter',{challengeWon:true,encounterRolled:true,enemyId:'Skeleton',lastRoll:{chance:1,enemy:4}});await load(p,f);await random(p);await click(p,'#dungeonFight');await pick(p,['H1']);await click(p,'#combatCommit');await click(p,'#combatResolve');await pick(p,['H1']);await click(p,'#woundNext');await click(p,'#combatFlee');const s=await read(p);assert.equal(s.delve,null);assert.equal(s.res.Fate,2);assert.equal(s.res.Coin,8)});
test('311 dungeon selection and saved definitions work with networking disabled',async(p,ctx,browser)=>{const c=await browser.newContext({offline:true});try{const q=await c.newPage();q.setDefaultTimeout(10000);await c.route('**/*',r=>r.fulfill({status:200,contentType:'text/html',body:fs.readFileSync(APP_FILE)}));await q.goto(new URL(p.url()).origin);await load(q);await enterDungeon(q);assert.equal((await read(q)).delve.enemies.find(e=>e.boss).CV,18);assert.equal(await q.locator('#dungeonScreen').isVisible(),true)}finally{await c.close()}});
test('312 pending dungeon Coin overflow shows action instructions and pays exactly once',async p=>{const f=delveFixture(1,'cleared',{pendingCoins:4});f.res.Coin=Number.MAX_SAFE_INTEGER;await load(p,f);await click(p,'#dungeonExit');assert.equal((await read(p)).delve.phase,'payout');assert.equal(await p.locator('#actionStatus').isVisible(),true);assert.match(await p.locator('#actionStatus').innerText(),/Reduce Coin/);await click(p,'#dungeonSheetToggle');await click(p,'[data-resource="Coin"][data-delta="-1"]');await click(p,'[data-resource="Coin"][data-delta="-1"]');await click(p,'[data-resource="Coin"][data-delta="-1"]');await click(p,'[data-resource="Coin"][data-delta="-1"]');await click(p,'#dungeonCollect');assert.equal((await read(p)).res.Coin,Number.MAX_SAFE_INTEGER);assert.equal((await read(p)).delve,null)});
test('313 zero available Upgrade points do not flash on shortcut',async p=>{await load(p,fixture({pointLimit:27,upgradePoints:0}));await click(p,'#attributePoints');assert.equal(await p.locator('#availableUpgradePoints').evaluate(e=>e.classList.contains('points-flash')),false)});

(async()=>{fs.mkdirSync(OUT,{recursive:true});const source=fs.readFileSync(APP_FILE);const server=http.createServer((req,res)=>{if(req.url==='/favicon.ico'){res.writeHead(204).end();return;}res.setHeader('Content-Type','text/html; charset=utf-8');res.end(source);});await new Promise(r=>server.listen(0,'127.0.0.1',r));const origin=`http://127.0.0.1:${server.address().port}`;let browser;const results=[];try{browser=await chromium.launch({executablePath:process.env.CHROMIUM_PATH||(fs.existsSync('/usr/bin/chromium')?'/usr/bin/chromium':undefined),headless:true,args:['--no-sandbox']});for(const c of cases.filter(c=>!process.env.TEST_FILTER||new RegExp(process.env.TEST_FILTER).test(c.name))){const context=await browser.newContext({acceptDownloads:true});await context.route('**/*',route=>new URL(route.request().url()).origin===origin?route.continue():route.abort());const page=await context.newPage();page.setDefaultTimeout(10000);const errors=[];page.on('pageerror',e=>errors.push(e.message));const started=Date.now();try{await page.goto(origin);await c.fn(page,context,browser);assert.deepEqual(errors,[],'no unhandled browser errors');results.push({name:c.name,status:'PASS',ms:Date.now()-started});}catch(e){results.push({name:c.name,status:'FAIL',error:e.message,errors,ms:Date.now()-started});await page.screenshot({path:path.join(OUT,`failure-${c.name.slice(0,2)}.png`),fullPage:true}).catch(()=>{});}console.log(results.at(-1).status,c.name,results.at(-1).error||'');await context.close();}const summary={date:new Date().toISOString(),browser:browser.version(),sourceSHA256:require('node:crypto').createHash('sha256').update(source).digest('hex'),passed:results.filter(r=>r.status==='PASS').length,failed:results.filter(r=>r.status==='FAIL').length,results};fs.writeFileSync(path.join(OUT,process.env.TEST_FILTER?'filtered-results.json':'baseline-results.json'),JSON.stringify(summary,null,2));console.log(JSON.stringify({passed:summary.passed,failed:summary.failed}));process.exitCode=summary.failed?1:0;}finally{if(browser)await browser.close();server.close();}})();
